/* ═══════════════════════════════════════════════════════════
   WANDLORE · UI
   ═══════════════════════════════════════════════════════════ */
@font-face { font-family: 'Cinzel'; src: url('./assets/fonts/cinzel-700.ttf') format('truetype'); font-weight: 700; font-display: swap; }
@font-face { font-family: 'Cinzel'; src: url('./assets/fonts/cinzel-900.ttf') format('truetype'); font-weight: 900; font-display: swap; }
@font-face { font-family: 'Spectral'; src: url('./assets/fonts/spectral-400.ttf') format('truetype'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Spectral'; src: url('./assets/fonts/spectral-italic.ttf') format('truetype'); font-weight: 400; font-style: italic; font-display: swap; }

:root {
  --ink: #08060f;
  --ink-2: #100b1e;
  --panel: rgba(15, 11, 27, .92);
  --panel-2: rgba(26, 19, 43, .82);
  --gold: #e9c988;
  --gold-2: #c39a4f;
  --gold-dim: #8d6f3c;
  --parch: #f1e4c8;
  --parch-dim: #cdbd9e;
  --arcane: #ab8cff;
  --arcane-2: #6f54d6;
  --teal: #7de6d0;
  --rose: #ff8c9a;
  --ember: #ffb05a;
  --green: #96e08a;
  --line: rgba(233, 201, 136, .22);
  --line-soft: rgba(233, 201, 136, .11);
  --shadow: 0 30px 90px rgba(0, 0, 0, .65);
  --serif: 'Cormorant Garamond', 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
  --display: 'Cinzel', 'Iowan Old Style', Palatino, Georgia, serif;
  --body: 'Spectral', 'Iowan Old Style', Palatino, Georgia, serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--ink);
  color: var(--parch);
  font-family: var(--body);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
button { font-family: inherit; color: inherit; border: none; background: none; cursor: pointer; }
input { font-family: inherit; }
.hidden { display: none !important; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,.03); }
::-webkit-scrollbar-thumb { background: linear-gradient(var(--gold-dim), #5c4728); border-radius: 8px; }

#app { position: fixed; inset: 0; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.scene-grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 30%, rgba(8,5,16,.22) 70%, rgba(8,5,16,.58) 100%),
    linear-gradient(to bottom, rgba(12,8,26,.18), transparent 22%, transparent 74%, rgba(7,5,14,.52));
}
.scene-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  box-shadow: inset 0 0 180px 20px rgba(5, 3, 12, .78);
}

/* ── LOADING ─────────────────────────────────────────────── */
#loading {
  position: absolute; inset: 0; z-index: 90; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 8px;
  background: radial-gradient(ellipse at center, #19112c 0%, #08060f 70%);
  transition: opacity .8s ease;
}
#loading.done { opacity: 0; pointer-events: none; }
.load-sigil { position: relative; width: 104px; height: 104px; display: grid; place-items: center; margin-bottom: 20px; }
.load-ring { position: absolute; inset: 0; border: 1px solid rgba(233,201,136,.5); border-radius: 50%; border-top-color: transparent; animation: spin 3s linear infinite; }
.load-ring.r2 { inset: 15px; border-color: rgba(171,140,255,.45); border-bottom-color: transparent; animation: spin 2s linear infinite reverse; }
.load-core { font-size: 28px; color: var(--gold); text-shadow: 0 0 26px var(--gold); animation: pulse 2.2s ease-in-out infinite; }
.load-title { font-family: var(--display); letter-spacing: .5em; font-size: 24px; color: var(--parch); padding-left: .5em; }
.load-sub { font-family: var(--display); font-size: 9px; letter-spacing: .32em; color: var(--gold-dim); text-transform: uppercase; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { 50% { opacity: .45; transform: scale(.88); text-shadow: 0 0 6px var(--gold); } }

/* ── TITLE ───────────────────────────────────────────────── */
#title-screen {
  position: absolute; inset: 0; z-index: 30; display: flex; align-items: center;
  padding: clamp(28px, 5vw, 84px);
  background:
    linear-gradient(90deg, rgba(7,5,14,.88) 0%, rgba(7,5,14,.66) 34%, rgba(7,5,14,.12) 62%, rgba(7,5,14,.55) 100%),
    radial-gradient(ellipse at 66% 46%, transparent 0%, rgba(8,6,16,.25) 60%, rgba(8,6,16,.75) 100%);
}
.title-glow {
  position: absolute; width: 70vw; height: 70vw; left: -20vw; bottom: -40vw; pointer-events: none;
  background: radial-gradient(circle, rgba(126,79,220,.18), transparent 62%);
}
.title-inner { position: relative; width: min(620px, 52vw); padding-left: 6px; animation: rise .9s ease both; }
.title-eyebrow {
  display: flex; align-items: center; gap: 14px; margin-bottom: 20px;
  font-family: var(--display); font-size: 10px; font-weight: 700; letter-spacing: .42em; color: var(--gold);
}
.title-eyebrow span { width: 34px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold-2)); }
.title-eyebrow span:last-child { background: linear-gradient(90deg, var(--gold-2), transparent); }
.game-title {
  font-family: var(--display); font-weight: 900; margin: 0; line-height: .84;
  font-size: clamp(70px, 10.4vw, 152px); letter-spacing: .03em; color: var(--parch);
  text-shadow: 0 4px 40px rgba(0,0,0,.6), 0 0 70px rgba(206,170,255,.16);
}
.game-title em {
  display: block; font-style: normal; font-size: .48em; letter-spacing: .22em;
  color: var(--gold); padding-left: .16em; margin-bottom: .08em;
  background: linear-gradient(100deg, #f5dfae, #bd8f45 38%, #fff0c8 52%, #b8893f 68%, #edd196);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 24px rgba(233,201,136,.18));
}
.game-title strong { font-weight: 900; letter-spacing: .06em; }
.title-rule { display: flex; align-items: center; gap: 14px; margin: 22px 0 18px; width: 74%; }
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, var(--line)); }
.title-rule i:last-child { background: linear-gradient(90deg, var(--line), transparent); }
.title-rule span { font-size: 12px; color: var(--gold); }
.title-tagline {
  font-family: var(--body); font-style: italic; font-size: clamp(16px, 1.45vw, 20px);
  line-height: 1.55; color: var(--parch-dim); margin: 0 0 34px; max-width: 480px;
}
.title-actions { display: flex; align-items: stretch; gap: 14px; flex-wrap: wrap; }
.btn-primary {
  position: relative; overflow: hidden;
  font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: .24em; text-transform: uppercase;
  color: #23180a; padding: 15px 34px; border-radius: 2px;
  background: linear-gradient(160deg, #f4dda8, #d1a95f 48%, #a97c37);
  box-shadow: 0 8px 30px rgba(201,158,80,.28), inset 0 1px 0 rgba(255,255,255,.5);
  transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
}
.btn-primary::after {
  content: ''; position: absolute; inset: 0; transform: translateX(-120%) skewX(-18deg);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.55), transparent); transition: transform .6s ease;
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 38px rgba(220,175,95,.4), inset 0 1px 0 rgba(255,255,255,.5); }
.btn-primary:hover::after { transform: translateX(120%) skewX(-18deg); }
.btn-primary.btn-lg { padding: 17px 42px; font-size: 12.5px; }
.btn-ghost {
  font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: .22em; text-transform: uppercase;
  padding: 15px 30px; border: 1px solid var(--line); color: var(--parch); border-radius: 2px;
  background: rgba(20,14,35,.5); transition: .2s ease;
}
.btn-ghost:hover { border-color: var(--gold); background: rgba(233,201,136,.08); }
.title-name { display: flex; align-items: center; gap: 12px; margin-top: 22px; }
.title-name label { font-family: var(--display); font-size: 9px; letter-spacing: .26em; color: var(--gold-dim); text-transform: uppercase; }
.title-name input {
  background: rgba(12,8,22,.6); border: none; border-bottom: 1px solid var(--line); padding: 7px 2px;
  color: var(--parch); font-family: var(--body); font-size: 17px; width: 210px; outline: none; transition: .2s;
}
.title-name input:focus { border-color: var(--gold); }
.title-name input::placeholder { color: rgba(241,228,200,.3); }
.title-features { display: flex; gap: 26px; margin-top: 44px; }
.feature { display: flex; flex-direction: column; gap: 4px; }
.f-icon { font-size: 17px; color: var(--gold); text-shadow: 0 0 16px rgba(233,201,136,.4); margin-bottom: 3px; }
.feature b { font-family: var(--display); font-size: 9.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.feature small { font-size: 11.5px; color: rgba(205,189,158,.66); font-style: italic; }
.title-side {
  position: absolute; right: clamp(30px, 6vw, 100px); bottom: 24%; width: 280px; text-align: right;
  animation: rise 1.1s .18s ease both;
}
.side-quote { font-family: var(--body); font-style: italic; font-size: 18px; line-height: 1.5; color: rgba(241,228,200,.82); text-shadow: 0 2px 16px #000; }
.side-attr { font-family: var(--display); font-size: 8.5px; letter-spacing: .2em; color: var(--gold-dim); margin-top: 12px; text-transform: uppercase; }
.side-chips { display: flex; justify-content: flex-end; gap: 8px; margin-top: 22px; flex-wrap: wrap; }
.side-chips span { font-family: var(--display); font-size: 7.5px; letter-spacing: .16em; text-transform: uppercase; padding: 5px 9px; border: 1px solid var(--line-soft); color: rgba(241,228,200,.55); }
.title-foot {
  position: absolute; left: clamp(28px, 5vw, 84px); right: clamp(28px, 5vw, 84px); bottom: 26px;
  display: flex; justify-content: space-between; font-family: var(--display); font-size: 8px;
  letter-spacing: .26em; text-transform: uppercase; color: rgba(233,201,136,.35);
}
@keyframes rise { from { opacity: 0; transform: translateY(22px); } }

/* ── HUD ─────────────────────────────────────────────────── */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#hud button, #hud .player-card, #hud .minimap-wrap { pointer-events: auto; }

.hud-top-left { position: absolute; top: 22px; left: 24px; display: flex; flex-direction: column; gap: 10px; }
.player-card {
  display: flex; align-items: center; gap: 12px; padding: 10px 18px 10px 10px;
  background: linear-gradient(120deg, rgba(17,12,29,.92), rgba(17,12,29,.6));
  border: 1px solid var(--line-soft); border-left: 1px solid var(--gold-dim);
  border-radius: 3px; backdrop-filter: blur(12px); box-shadow: 0 10px 40px rgba(0,0,0,.35);
  min-width: 272px;
}
.portrait {
  position: relative; width: 48px; height: 48px; border-radius: 50%; flex: none; display: grid; place-items: center;
  background: radial-gradient(circle at 32% 26%, #43306b, #1b1230 65%, #0d0918);
  border: 1px solid rgba(233,201,136,.45); box-shadow: inset 0 0 18px rgba(171,140,255,.25);
}
.portrait span { font-family: var(--display); font-weight: 700; font-size: 15px; color: var(--gold); letter-spacing: .05em; }
.portrait-ring { position: absolute; inset: -4px; border-radius: 50%; border: 1px dashed rgba(233,201,136,.25); animation: spin 26s linear infinite; }
.player-meta { flex: 1; min-width: 0; }
.player-name-row { display: flex; align-items: center; gap: 8px; }
#player-name { font-family: var(--display); font-size: 12.5px; font-weight: 700; letter-spacing: .06em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.level-pip { font-family: var(--display); font-size: 9px; font-weight: 700; color: #1c1307; background: linear-gradient(140deg,#f0d79e,#bd9149); padding: 1px 6px 0; border-radius: 2px; }
.player-title { font-size: 11px; font-style: italic; color: rgba(205,189,158,.72); margin: 2px 0 5px; }
.xp-bar { position: relative; height: 7px; background: rgba(255,255,255,.07); border-radius: 4px; overflow: hidden; }
.xp-bar #xp-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #6d50c8, #b093ff); box-shadow: 0 0 10px rgba(171,140,255,.5); transition: width .5s ease; }
.xp-bar span { position: absolute; inset: 0; display: grid; place-items: center; font-family: var(--display); font-size: 6.5px; letter-spacing: .12em; color: rgba(255,255,255,.7); }
.resource-strip {
  display: flex; gap: 4px; padding: 7px 10px; background: rgba(12,9,21,.72); border: 1px solid var(--line-soft);
  border-radius: 3px; backdrop-filter: blur(10px); width: fit-content;
}
.res { display: flex; align-items: center; gap: 5px; font-family: var(--display); font-size: 10px; font-weight: 700; letter-spacing: .04em; padding: 0 9px; border-right: 1px solid var(--line-soft); white-space: nowrap; }
.res:last-child { border-right: none; }
.res-ico { font-size: 11px; }
.res-ico.gold { color: var(--gold); text-shadow: 0 0 8px rgba(233,201,136,.5); }
.res-ico.rep { color: var(--arcane); text-shadow: 0 0 8px rgba(171,140,255,.6); }
.res-ico.rank { color: var(--rose); }
.res-ico.wand { color: var(--teal); }

.hud-top-center { position: absolute; top: 20px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 8px; }
.location-chip {
  display: flex; align-items: center; gap: 9px; padding: 7px 18px;
  font-family: var(--display); font-size: 9px; letter-spacing: .24em; text-transform: uppercase;
  color: rgba(241,228,200,.85); background: rgba(11,8,20,.58); border: 1px solid var(--line-soft);
  border-radius: 20px; backdrop-filter: blur(10px); white-space: nowrap;
}
.loc-rune { color: var(--gold); font-size: 9px; }
.loc-divider { width: 1px; height: 9px; background: var(--line); }
#clock { color: var(--gold-dim); }
.compass { position: relative; width: 220px; height: 22px; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent); }
.compass-track { display: flex; width: 100%; height: 100%; justify-content: space-between; align-items: center; padding: 0 12px; }
.compass-track span { font-family: var(--display); font-size: 7px; letter-spacing: .18em; color: rgba(241,228,200,.32); transform: translateY(var(--y, 0)); }
.compass-needle { position: absolute; left: 50%; top: 0; width: 1px; height: 100%; background: linear-gradient(transparent, var(--gold), transparent); opacity: .6; }

.hud-top-right { position: absolute; top: 22px; right: 24px; }
.minimap-wrap { position: relative; width: 156px; height: 156px; }
#minimap { width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 10px 40px rgba(0,0,0,.5), inset 0 0 30px rgba(0,0,0,.6); }
.minimap-ring {
  position: absolute; inset: -7px; border-radius: 50%; pointer-events: none;
  border: 1px solid rgba(233,201,136,.32);
  background: radial-gradient(circle, transparent 64%, rgba(8,6,15,.82) 65%);
  box-shadow: inset 0 0 0 5px rgba(8,6,15,.6), 0 0 26px rgba(171,140,255,.12);
}
.minimap-ring::before, .minimap-ring::after {
  content: '✦'; position: absolute; font-size: 7px; color: var(--gold-dim);
}
.minimap-ring::before { top: -4px; left: 50%; transform: translateX(-50%); }
.minimap-ring::after { bottom: -4px; left: 50%; transform: translateX(-50%) rotate(180deg); }
.minimap-label {
  position: absolute; bottom: -25px; left: 50%; transform: translateX(-50%); white-space: nowrap;
  font-family: var(--display); font-size: 7.5px; letter-spacing: .2em; text-transform: uppercase; color: rgba(241,228,200,.55);
}
.mini-expand {
  position: absolute; top: 2px; right: 2px; width: 24px; height: 24px; border-radius: 50%;
  background: rgba(10,7,18,.75); border: 1px solid var(--line-soft); color: var(--parch-dim);
  font-size: 11px; line-height: 1; display: grid; place-items: center; transition: .2s;
}
.mini-expand:hover { color: var(--gold); border-color: var(--gold); }

.hud-left { position: absolute; left: 24px; bottom: 26px; display: flex; flex-direction: column; gap: 10px; width: 286px; }
.quest-tracker {
  padding: 13px 16px 14px; background: linear-gradient(135deg, rgba(17,12,29,.9), rgba(17,12,29,.58));
  border: 1px solid var(--line-soft); border-left: 2px solid var(--gold-2); border-radius: 2px;
  backdrop-filter: blur(12px); box-shadow: 0 12px 40px rgba(0,0,0,.3);
}
.qt-head { display: flex; align-items: center; gap: 6px; font-family: var(--display); font-size: 7.5px; letter-spacing: .22em; color: var(--gold-dim); text-transform: uppercase; }
.qt-rune { color: var(--gold); font-size: 8px; }
.qt-count { margin-left: auto; color: rgba(241,228,200,.45); }
.qt-title { font-family: var(--display); font-size: 12px; font-weight: 700; color: var(--parch); margin: 8px 0 4px; letter-spacing: .02em; }
.qt-objective { font-size: 12.5px; font-style: italic; color: rgba(205,189,158,.8); line-height: 1.35; }
.qt-progress { height: 2px; background: rgba(255,255,255,.08); margin-top: 10px; }
.qt-progress div { height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); transition: width .4s; }
.hint-panel { display: flex; flex-wrap: wrap; gap: 3px 10px; padding: 8px 12px; background: rgba(11,8,20,.5); border: 1px solid rgba(233,201,136,.08); backdrop-filter: blur(8px); }
.hint-row { display: flex; align-items: center; gap: 5px; font-family: var(--display); font-size: 6.5px; letter-spacing: .12em; color: rgba(241,228,200,.4); text-transform: uppercase; }
.hint-row kbd { font-family: var(--display); font-size: 6.5px; letter-spacing: .05em; padding: 2px 4px; border: 1px solid rgba(233,201,136,.2); color: rgba(241,228,200,.63); border-radius: 2px; background: rgba(255,255,255,.03); }

.action-rail { position: absolute; right: 27px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 7px; }
.rail-btn {
  position: relative; width: 54px; height: 50px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  background: linear-gradient(140deg, rgba(22,16,38,.86), rgba(11,8,20,.72)); border: 1px solid var(--line-soft);
  border-radius: 2px; backdrop-filter: blur(10px); transition: .2s ease;
}
.rail-btn span { font-size: 15px; color: var(--gold); line-height: 1; transition: .2s; }
.rail-btn label { font-family: var(--display); font-size: 6.5px; letter-spacing: .16em; text-transform: uppercase; color: rgba(241,228,200,.5); cursor: pointer; }
.rail-btn:hover { border-color: rgba(233,201,136,.55); background: linear-gradient(140deg, rgba(44,30,72,.9), rgba(16,11,28,.8)); transform: translateX(-3px); }
.rail-btn:hover span { text-shadow: 0 0 14px var(--gold); }
.rail-duel { border-color: rgba(255,140,154,.24); }
.rail-duel span { color: var(--rose); }

.spellbar-wrap { position: absolute; left: 50%; bottom: 24px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; }
.cast-orb {
  position: relative; width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 30%, #32234f, #120c22 70%);
  border: 1px solid rgba(233,201,136,.35); margin-bottom: -2px;
  box-shadow: 0 0 26px rgba(171,140,255,.16), inset 0 0 16px rgba(171,140,255,.2);
}
.cast-orb span { font-size: 17px; color: var(--gold); text-shadow: 0 0 12px var(--gold); z-index: 1; }
#cast-orb-glow { position: absolute; inset: -8px; border-radius: 50%; background: radial-gradient(circle, rgba(171,140,255,.2), transparent 65%); animation: pulse 3s ease-in-out infinite; }
.spellbar { display: flex; align-items: flex-end; gap: 5px; padding: 5px; background: rgba(10,7,18,.55); border: 1px solid var(--line-soft); border-radius: 3px; backdrop-filter: blur(12px); }
.spell-slot {
  position: relative; width: 50px; height: 56px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  border: 1px solid rgba(233,201,136,.12); background: linear-gradient(160deg, rgba(35,24,56,.55), rgba(13,9,23,.6));
  border-radius: 2px; transition: .15s ease; overflow: hidden;
}
.spell-slot:hover { border-color: rgba(233,201,136,.5); transform: translateY(-3px); }
.spell-slot.active { border-color: var(--gold); box-shadow: 0 0 18px rgba(233,201,136,.2), inset 0 0 14px rgba(233,201,136,.08); }
.spell-slot.locked { opacity: .42; filter: saturate(.2); }
.spell-slot .slot-rune { font-size: 18px; color: var(--sc, var(--gold)); text-shadow: 0 0 12px currentColor; line-height: 1; }
.spell-slot .slot-key { position: absolute; top: 2px; left: 4px; font-family: var(--display); font-size: 6.5px; color: rgba(241,228,200,.42); }
.spell-slot .slot-name { font-family: var(--display); font-size: 6px; letter-spacing: .08em; color: rgba(241,228,200,.7); text-transform: uppercase; white-space: nowrap; }
.spell-slot .slot-cd { position: absolute; inset: 0; background: rgba(5,3,10,.76); transform-origin: bottom; transform: scaleY(0); pointer-events: none; }
.spell-slot .slot-cost { position: absolute; bottom: 2px; right: 4px; font-family: var(--display); font-size: 6px; color: rgba(141,211,255,.75); }
.combat-meters { display: none; width: 100%; grid-template-columns: 1fr 1fr; gap: 6px; }
.combat-on .combat-meters { display: grid; }
.meter { display: flex; align-items: center; gap: 5px; font-family: var(--display); font-size: 6.5px; letter-spacing: .1em; color: rgba(241,228,200,.5); }
.meter-track { flex: 1; height: 5px; background: rgba(255,255,255,.07); border-radius: 4px; overflow: hidden; }
.meter-track div { height: 100%; width: 100%; transition: width .2s ease; }
.meter.hp .meter-track div { background: linear-gradient(90deg, #8e2d46, #ff6a86); box-shadow: 0 0 8px rgba(255,106,134,.45); }
.meter.mp .meter-track div { background: linear-gradient(90deg, #2b4d9c, #6fb8ff); box-shadow: 0 0 8px rgba(111,184,255,.45); }
.meter b { font-size: 7px; min-width: 22px; text-align: right; color: rgba(241,228,200,.8); }

.interact-prompt {
  position: absolute; left: 50%; bottom: 124px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; padding: 9px 20px 9px 10px;
  background: rgba(12,8,22,.85); border: 1px solid rgba(233,201,136,.35); border-radius: 40px;
  backdrop-filter: blur(12px); box-shadow: 0 10px 40px rgba(0,0,0,.5); animation: promptIn .25s ease;
}
.interact-prompt kbd {
  width: 25px; height: 25px; border-radius: 50%; display: grid; place-items: center;
  background: linear-gradient(150deg, #eed49b, #bb8d44); color: #23180a; font-family: var(--display); font-weight: 700; font-size: 10px;
}
.interact-prompt span { font-family: var(--display); font-size: 9.5px; letter-spacing: .17em; text-transform: uppercase; color: var(--parch); }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } }

.toasts { position: absolute; top: 206px; right: 24px; display: flex; flex-direction: column; gap: 7px; align-items: flex-end; }
.toast {
  display: flex; align-items: center; gap: 10px; min-width: 220px; max-width: 320px;
  padding: 10px 14px; background: linear-gradient(120deg, rgba(24,17,41,.95), rgba(14,10,26,.9));
  border: 1px solid var(--line-soft); border-right: 2px solid var(--tone, var(--gold));
  box-shadow: 0 8px 30px rgba(0,0,0,.4); animation: toastIn .35s cubic-bezier(.2,.8,.2,1); backdrop-filter: blur(12px);
}
.toast.out { animation: toastOut .3s ease forwards; }
.toast .t-ico { font-size: 15px; color: var(--tone, var(--gold)); text-shadow: 0 0 12px currentColor; }
.toast .t-body { display: flex; flex-direction: column; gap: 1px; }
.toast b { font-family: var(--display); font-size: 8.5px; letter-spacing: .08em; color: var(--parch); }
.toast span { font-size: 11.5px; color: rgba(205,189,158,.8); line-height: 1.25; }
@keyframes toastIn { from { opacity: 0; transform: translateX(26px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(26px); } }

.objective-toast {
  position: absolute; top: 118px; left: 50%; transform: translateX(-50%);
  padding: 10px 24px; background: rgba(12,8,22,.8); border: 1px solid var(--line-soft);
  border-top: 1px solid var(--gold-dim); text-align: center; backdrop-filter: blur(10px); animation: objIn .4s ease;
}
.objective-toast b { display: block; font-family: var(--display); font-size: 7px; letter-spacing: .26em; color: var(--gold-dim); text-transform: uppercase; margin-bottom: 2px; }
.objective-toast span { font-size: 13px; font-style: italic; color: var(--parch); }
@keyframes objIn { from { opacity: 0; transform: translate(-50%, -8px); } }

.combat-ui { position: absolute; inset: 0; pointer-events: none; }
.enemy-card { position: absolute; top: 96px; left: 50%; transform: translateX(-50%); width: min(430px, 40vw); }
.enemy-name-row { display: flex; align-items: baseline; justify-content: center; gap: 10px; margin-bottom: 6px; }
#enemy-rank { font-family: var(--display); font-size: 7px; letter-spacing: .24em; color: var(--rose); border: 1px solid rgba(255,140,154,.3); padding: 3px 7px; }
#enemy-name { font-family: var(--display); font-size: 13px; letter-spacing: .14em; color: var(--parch); text-transform: uppercase; text-shadow: 0 2px 12px #000; }
.enemy-hp { position: relative; height: 11px; background: rgba(8,5,15,.75); border: 1px solid rgba(255,140,154,.25); overflow: hidden; }
#enemy-hp-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #6b1830, #d94a65 55%, #ff8c9a); transition: width .18s ease; box-shadow: 0 0 14px rgba(255,100,120,.4); }
#enemy-hp-text { position: absolute; inset: 0; display: grid; place-items: center; font-family: var(--display); font-size: 6.5px; letter-spacing: .12em; color: rgba(255,255,255,.85); }
.enemy-cast { display: flex; align-items: center; justify-content: center; gap: 7px; margin-top: 6px; height: 14px; opacity: 0; transition: opacity .2s; }
.enemy-cast.on { opacity: 1; }
.enemy-cast i { width: 7px; height: 7px; border-radius: 50%; background: var(--cast-col, var(--rose)); box-shadow: 0 0 12px currentColor; animation: pulse .6s infinite; }
.enemy-cast span { font-family: var(--display); font-size: 6.5px; letter-spacing: .2em; color: rgba(241,228,200,.6); text-transform: uppercase; }
.duel-round { position: absolute; top: 176px; left: 50%; transform: translateX(-50%); font-family: var(--display); font-size: 7px; letter-spacing: .32em; color: var(--gold-dim); }
.combo { position: absolute; right: 118px; top: 38%; font-family: var(--display); font-weight: 900; font-size: 34px; color: var(--gold); text-shadow: 0 0 30px rgba(233,201,136,.5); opacity: 0; transform: scale(.7); transition: .2s; }
.combo.on { opacity: 1; transform: scale(1); }
.combat-log { position: absolute; left: 26px; top: 39%; width: 250px; display: flex; flex-direction: column; gap: 3px; }
.log-line { font-size: 11.5px; font-style: italic; color: rgba(205,189,158,.75); text-shadow: 0 1px 6px #000; animation: logIn .25s ease; }
.log-line b { font-style: normal; font-family: var(--display); font-size: 8px; letter-spacing: .08em; }
.log-line.dmg b { color: var(--rose); }
.log-line.good b { color: var(--teal); }
.log-line.spell b { color: var(--gold); }
@keyframes logIn { from { opacity: 0; transform: translateX(-8px); } }
.crosshair { position: absolute; left: 50%; top: 50%; width: 16px; height: 16px; transform: translate(-50%, -50%); opacity: .55; }
.crosshair::before, .crosshair::after { content: ''; position: absolute; background: rgba(233,201,136,.7); }
.crosshair::before { left: 50%; top: 0; width: 1px; height: 100%; }
.crosshair::after { top: 50%; left: 0; height: 1px; width: 100%; }

.damage-layer { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.dmg-num {
  position: absolute; transform: translate(-50%, -50%); font-family: var(--display); font-weight: 700;
  font-size: 16px; color: #ffe0a6; text-shadow: 0 2px 8px #000, 0 0 14px currentColor;
  animation: floatUp .9s ease-out forwards; white-space: nowrap;
}
.dmg-num.crit { font-size: 23px; color: #fff1c2; }
.dmg-num.heal { color: #a9f2bf; }
.dmg-num.enemy { color: #ff9eac; }
@keyframes floatUp { to { opacity: 0; transform: translate(-50%, -180%) scale(1.1); } }

.hud-bottom-right { position: absolute; right: 26px; bottom: 22px; display: flex; align-items: center; gap: 10px; }
.sound-btn {
  width: 30px; height: 30px; border: 1px solid var(--line-soft); background: rgba(11,8,20,.6);
  color: var(--gold); font-size: 12px; display: grid; place-items: center; border-radius: 50%; pointer-events: auto;
}
.sound-btn.muted { color: rgba(241,228,200,.28); }
.autosave { font-family: var(--display); font-size: 6.5px; letter-spacing: .2em; color: rgba(233,201,136,.35); text-transform: uppercase; opacity: 0; transition: opacity .5s; }
.autosave.on { opacity: 1; }

/* ── GRIMOIRE PANEL ──────────────────────────────────────── */
#overlay { position: absolute; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center; padding: 3vh 3vw; }
.overlay-backdrop { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(10,6,20,.55), rgba(5,3,10,.82)); backdrop-filter: blur(4px); }
.grimoire {
  position: relative; width: min(1180px, 95vw); height: min(820px, 92vh);
  display: flex; background:
    radial-gradient(ellipse at 18% 0%, rgba(96,62,150,.12), transparent 45%),
    linear-gradient(140deg, rgba(21,15,35,.985), rgba(11,8,20,.99));
  border: 1px solid rgba(233,201,136,.26); box-shadow: var(--shadow), inset 0 0 100px rgba(0,0,0,.4);
  animation: grimoireIn .35s cubic-bezier(.2,.8,.2,1);
}
@keyframes grimoireIn { from { opacity: 0; transform: scale(.97) translateY(10px); } }
.grimoire::before {
  content: ''; position: absolute; inset: 7px; border: 1px solid rgba(233,201,136,.09); pointer-events: none;
}
.grimoire-corner { position: absolute; width: 22px; height: 22px; border-color: var(--gold-2); border-style: solid; pointer-events: none; }
.grimoire-corner.tl { top: 8px; left: 8px; border-width: 1px 0 0 1px; }
.grimoire-corner.tr { top: 8px; right: 8px; border-width: 1px 1px 0 0; }
.grimoire-corner.bl { bottom: 8px; left: 8px; border-width: 0 0 1px 1px; }
.grimoire-corner.br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }
.grimoire-nav {
  width: 188px; flex: none; padding: 28px 0 22px; border-right: 1px solid var(--line-soft);
  display: flex; flex-direction: column; gap: 2px; background: rgba(8,6,15,.28);
}
.nav-brand { padding: 0 24px 22px; font-family: var(--display); font-size: 9px; letter-spacing: .32em; color: var(--gold-dim); }
.nav-brand b { color: var(--parch); display: block; font-size: 15px; letter-spacing: .18em; margin-top: 5px; }
.nav-btn {
  position: relative; display: flex; align-items: center; gap: 12px; padding: 12px 22px;
  font-family: var(--display); font-size: 8.5px; letter-spacing: .17em; text-transform: uppercase;
  color: rgba(205,189,158,.6); transition: .15s; text-align: left;
}
.nav-btn span { width: 17px; text-align: center; font-size: 12px; color: var(--gold-dim); }
.nav-btn:hover { color: var(--parch); background: rgba(233,201,136,.04); }
.nav-btn.active { color: var(--gold); background: linear-gradient(90deg, rgba(233,201,136,.1), transparent); }
.nav-btn.active::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--gold); box-shadow: 0 0 12px var(--gold); }
.nav-btn.active span { color: var(--gold); text-shadow: 0 0 10px var(--gold); }
.nav-foot { margin-top: auto; padding: 18px 24px 0; border-top: 1px solid var(--line-soft); font-family: var(--display); font-size: 6.5px; letter-spacing: .18em; color: rgba(233,201,136,.28); line-height: 2; }
.nav-foot b { color: rgba(233,201,136,.55); font-weight: 700; }
.grimoire-main { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.grimoire-head { display: flex; align-items: flex-end; justify-content: space-between; padding: 26px 32px 18px; border-bottom: 1px solid var(--line-soft); }
.panel-kicker { font-family: var(--display); font-size: 7.5px; letter-spacing: .3em; color: var(--gold-dim); text-transform: uppercase; margin-bottom: 5px; }
.grimoire-head h2 { font-family: var(--display); font-size: 27px; font-weight: 700; margin: 0; letter-spacing: .04em; color: var(--parch); }
.panel-head-right { display: flex; align-items: center; gap: 22px; }
.panel-res { display: flex; align-items: center; gap: 7px; font-family: var(--display); font-size: 11px; color: var(--parch); }
.panel-res .res-ico { font-size: 12px; }
.panel-res b { margin-right: 6px; font-weight: 700; }
.btn-close { width: 32px; height: 32px; border: 1px solid var(--line); color: var(--parch-dim); font-size: 12px; display: grid; place-items: center; transition: .2s; }
.btn-close:hover { border-color: var(--gold); color: var(--gold); transform: rotate(90deg); }
.grimoire-body { flex: 1; overflow-y: auto; padding: 24px 32px 30px; }

.panel-tabs { display: flex; gap: 4px; margin-bottom: 20px; border-bottom: 1px solid var(--line-soft); }
.panel-tab {
  padding: 8px 15px 10px; font-family: var(--display); font-size: 7.5px; letter-spacing: .18em; text-transform: uppercase;
  color: rgba(205,189,158,.5); border-bottom: 1px solid transparent; margin-bottom: -1px; transition: .15s;
}
.panel-tab:hover { color: var(--parch); }
.panel-tab.active { color: var(--gold); border-bottom-color: var(--gold); }
.tab-body { animation: fadeIn .25s ease; }
@keyframes fadeIn { from { opacity: 0; } }

/* crafting */
.craft-layout { display: grid; grid-template-columns: 1.06fr .94fr; gap: 24px; }
.craft-left, .craft-right { min-width: 0; }
.ing-section-head { display: flex; align-items: center; justify-content: space-between; margin: 0 0 9px; }
.ing-section-head h3 { font-family: var(--display); font-size: 8px; letter-spacing: .22em; text-transform: uppercase; color: var(--gold-dim); margin: 0; font-weight: 700; }
.ing-section-head small { font-size: 11px; font-style: italic; color: rgba(205,189,158,.45); }
.ing-tabs { display: flex; gap: 3px; margin-bottom: 10px; }
.ing-tab { padding: 5px 10px; font-family: var(--display); font-size: 7px; letter-spacing: .14em; text-transform: uppercase; color: rgba(205,189,158,.5); border: 1px solid transparent; }
.ing-tab.active { color: var(--gold); border-color: var(--line); background: rgba(233,201,136,.05); }
.ing-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; max-height: 292px; overflow-y: auto; padding-right: 5px; }
.ing-card {
  position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px;
  border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.022); transition: .15s; text-align: left; min-height: 54px;
}
.ing-card:hover { border-color: rgba(233,201,136,.35); background: rgba(233,201,136,.04); }
.ing-card.selected { border-color: var(--gold); background: rgba(233,201,136,.08); box-shadow: inset 0 0 18px rgba(233,201,136,.06); }
.ing-card.selected::after { content: '✓'; position: absolute; top: 3px; right: 5px; font-size: 8px; color: var(--gold); }
.ing-card.empty { opacity: .32; cursor: not-allowed; }
.ing-orb { width: 32px; height: 32px; border-radius: 50%; flex: none; position: relative; box-shadow: inset -4px -5px 9px rgba(0,0,0,.5), 0 0 13px var(--swatch, transparent); background: radial-gradient(circle at 34% 27%, #fff6, transparent 35%), var(--swatch, #777); border: 1px solid rgba(255,255,255,.2); }
.ing-orb.wood { border-radius: 45% 55% 12px 12px / 30% 30% 8px 8px; }
.ing-orb.core { border-radius: 50%; }
.ing-orb.mat { border-radius: 4px; transform: rotate(45deg) scale(.8); }
.ing-info { display: flex; flex-direction: column; min-width: 0; gap: 2px; }
.ing-name { font-family: var(--display); font-size: 8px; letter-spacing: .05em; color: var(--parch); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ing-meta { font-size: 10.5px; color: rgba(205,189,158,.6); font-style: italic; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ing-qty { margin-left: auto; font-family: var(--display); font-size: 8px; color: var(--gold-dim); }
.rar-common { --rar: #a8a49a; } .rar-uncommon { --rar: #8fd18a; } .rar-rare { --rar: #6fb8ff; } .rar-epic { --rar: #c395ff; } .rar-legendary { --rar: #ffc96b; }
.rar-tag { font-family: var(--display); font-size: 6px; letter-spacing: .14em; color: var(--rar, #999); text-transform: uppercase; }

.wand-stage {
  position: relative; min-height: 250px; display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(255,255,255,.06); margin-bottom: 12px; overflow: hidden;
  background: radial-gradient(ellipse at 50% 45%, rgba(120,83,190,.18), transparent 62%), rgba(5,3,11,.45);
}
.wand-stage::before { content: ''; position: absolute; inset: 0; background-image: radial-gradient(rgba(233,201,136,.18) 1px, transparent 1px); background-size: 22px 22px; opacity: .24; }
.wand-stage::after { content: ''; position: absolute; left: 12%; right: 12%; bottom: 38px; height: 1px; background: linear-gradient(90deg, transparent, rgba(233,201,136,.3), transparent); }
.wand-stage svg { width: 92%; height: 190px; filter: drop-shadow(0 18px 24px rgba(0,0,0,.55)); position: relative; z-index: 1; }
.wand-idle .wand-svg { animation: wandFloat 5s ease-in-out infinite; }
@keyframes wandFloat { 50% { transform: translateY(-7px) rotate(-1deg); } }
.stage-tag { position: absolute; top: 10px; left: 12px; font-family: var(--display); font-size: 7px; letter-spacing: .2em; color: rgba(233,201,136,.45); text-transform: uppercase; }
.stage-rarity { position: absolute; top: 10px; right: 12px; font-family: var(--display); font-size: 7px; letter-spacing: .14em; color: var(--rar, var(--gold)); text-transform: uppercase; }
.wand-placeholder { text-align: center; color: rgba(205,189,158,.4); font-style: italic; font-size: 13px; position: relative; z-index: 1; }
.wand-placeholder span { display: block; font-size: 26px; margin-bottom: 8px; color: rgba(233,201,136,.35); }

.wand-readout { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 5px; }
.wand-name { font-family: var(--display); font-size: 15px; color: var(--parch); }
.wand-sub { font-size: 11.5px; font-style: italic; color: rgba(205,189,158,.55); }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 14px; margin: 10px 0; }
.stat { display: grid; grid-template-columns: 52px 1fr 27px; align-items: center; gap: 6px; font-family: var(--display); font-size: 6.5px; letter-spacing: .1em; text-transform: uppercase; color: rgba(205,189,158,.6); }
.stat-bar { height: 3px; background: rgba(255,255,255,.07); }
.stat-bar div { height: 100%; background: var(--sc, var(--gold)); box-shadow: 0 0 6px var(--sc, var(--gold)); transition: width .3s; }
.stat b { font-size: 7.5px; text-align: right; color: var(--parch-dim); font-weight: 400; }
.affinity-row { display: flex; flex-wrap: wrap; gap: 4px; margin: 8px 0 10px; }
.affinity-chip { font-family: var(--display); font-size: 6.5px; letter-spacing: .1em; padding: 3px 7px; border: 1px solid rgba(233,201,136,.17); color: rgba(233,201,136,.8); text-transform: uppercase; background: rgba(233,201,136,.04); }
.affinity-chip.neg { border-color: rgba(255,120,120,.2); color: rgba(255,150,150,.7); }
.wand-trait { padding: 8px 11px; border-left: 2px solid var(--gold-dim); background: rgba(233,201,136,.04); font-size: 11.5px; font-style: italic; color: rgba(205,189,158,.8); line-height: 1.4; margin-bottom: 10px; }
.wand-trait b { font-family: var(--display); font-style: normal; font-size: 7px; letter-spacing: .14em; color: var(--gold); text-transform: uppercase; display: block; margin-bottom: 2px; }
.slider-row { margin: 10px 0; }
.slider-head { display: flex; justify-content: space-between; font-family: var(--display); font-size: 7px; letter-spacing: .14em; text-transform: uppercase; color: rgba(205,189,158,.55); margin-bottom: 5px; }
.slider-head b { color: var(--gold); font-size: 8px; }
input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 3px; background: rgba(255,255,255,.1); outline: none; border-radius: 3px; }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 13px; height: 13px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #f6e3b4, #b98b3f); box-shadow: 0 0 10px rgba(233,201,136,.5); cursor: pointer; }
.mat-slots { display: flex; gap: 5px; margin-bottom: 12px; }
.mat-slot { flex: 1; height: 38px; border: 1px dashed rgba(233,201,136,.2); display: flex; align-items: center; justify-content: center; font-family: var(--display); font-size: 6px; letter-spacing: .1em; color: rgba(205,189,158,.35); text-transform: uppercase; text-align: center; padding: 2px; }
.mat-slot.filled { border-style: solid; color: var(--parch-dim); background: rgba(233,201,136,.05); cursor: pointer; }
.mat-slot.filled:hover { border-color: var(--rose); color: var(--rose); }
.mat-slot.locked { opacity: .4; }
.craft-actions { display: flex; gap: 8px; align-items: center; }
.btn-gold { font-family: var(--display); font-size: 8.5px; letter-spacing: .2em; text-transform: uppercase; padding: 11px 20px; color: #23180a; background: linear-gradient(150deg,#f3daa1,#c39852); transition: .2s; }
.btn-gold:hover { filter: brightness(1.1); transform: translateY(-1px); }
.btn-gold:disabled { opacity: .35; filter: grayscale(.5); cursor: not-allowed; transform: none; }
.btn-line { font-family: var(--display); font-size: 8px; letter-spacing: .16em; text-transform: uppercase; padding: 10px 14px; border: 1px solid var(--line); color: var(--parch-dim); transition: .2s; }
.btn-line:hover { border-color: var(--gold); color: var(--gold); }
.btn-line:disabled { opacity: .35; cursor: not-allowed; }
.craft-hint { font-size: 10.5px; font-style: italic; color: rgba(205,189,158,.45); margin-left: auto; text-align: right; }

.discovery-strip { margin-top: 16px; }
.discovery-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.disc { padding: 8px; border: 1px solid rgba(255,255,255,.05); background: rgba(255,255,255,.02); text-align: center; position: relative; }
.disc.found { border-color: rgba(255,201,107,.28); background: rgba(255,201,107,.05); }
.disc span { display: block; font-family: var(--display); font-size: 6.5px; letter-spacing: .1em; color: rgba(205,189,158,.38); text-transform: uppercase; }
.disc.found span { color: var(--gold); }
.disc small { display: block; margin-top: 3px; font-size: 9.5px; font-style: italic; color: rgba(205,189,158,.4); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.disc.found small { color: rgba(233,201,136,.7); }

/* generic panel bits */
.section-title { font-family: var(--display); font-size: 9px; letter-spacing: .22em; text-transform: uppercase; color: var(--gold-dim); margin: 0 0 12px; display: flex; align-items: center; gap: 10px; }
.section-title::after { content: ''; flex: 1; height: 1px; background: var(--line-soft); }
.section-title small { font-family: var(--body); font-size: 11px; font-style: italic; letter-spacing: 0; text-transform: none; color: rgba(205,189,158,.45); }
.empty-state { padding: 40px; text-align: center; color: rgba(205,189,158,.45); font-style: italic; }
.empty-state span { display: block; font-size: 28px; margin-bottom: 12px; color: rgba(233,201,136,.3); }

/* spellbook */
.spell-layout { display: grid; grid-template-columns: 1fr 300px; gap: 22px; }
.spell-cats { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 16px; }
.cat-chip { display: flex; align-items: center; gap: 6px; padding: 6px 11px; border: 1px solid rgba(255,255,255,.07); font-family: var(--display); font-size: 7px; letter-spacing: .14em; text-transform: uppercase; color: rgba(205,189,158,.55); transition: .15s; }
.cat-chip:hover { color: var(--parch); border-color: var(--line); }
.cat-chip.active { color: var(--gold); border-color: var(--gold-dim); background: rgba(233,201,136,.06); }
.cat-chip .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cc, var(--gold)); box-shadow: 0 0 7px var(--cc, var(--gold)); }
.spell-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.spell-card {
  position: relative; display: flex; gap: 11px; padding: 11px; border: 1px solid rgba(255,255,255,.06);
  background: linear-gradient(140deg, rgba(255,255,255,.03), transparent); text-align: left; transition: .18s; overflow: hidden;
}
.spell-card:hover { border-color: rgba(233,201,136,.32); background: rgba(233,201,136,.035); }
.spell-card.locked { opacity: .58; }
.spell-card.unknown { opacity: .34; filter: saturate(.1); }
.spell-card .sc-icon { width: 38px; height: 38px; flex: none; display: grid; place-items: center; border: 1px solid color-mix(in srgb, var(--sc) 35%, transparent); background: radial-gradient(circle, color-mix(in srgb, var(--sc) 14%, transparent), transparent 70%); font-size: 18px; color: var(--sc); text-shadow: 0 0 14px var(--sc); }
.spell-card .sc-body { min-width: 0; }
.spell-card .sc-name { font-family: var(--display); font-size: 10px; letter-spacing: .04em; color: var(--parch); display: flex; align-items: center; gap: 5px; }
.spell-card .sc-cat { font-family: var(--display); font-size: 5.8px; letter-spacing: .14em; text-transform: uppercase; color: var(--sc); opacity: .8; }
.spell-card .sc-desc { font-size: 10.5px; font-style: italic; color: rgba(205,189,158,.58); line-height: 1.35; margin-top: 3px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.spell-card .sc-mastery { margin-top: 6px; height: 2px; background: rgba(255,255,255,.08); }
.spell-card .sc-mastery div { height: 100%; background: var(--sc); }
.spell-card .lock-tag { position: absolute; top: 5px; right: 7px; font-family: var(--display); font-size: 5.5px; letter-spacing: .1em; color: rgba(205,189,158,.4); }
.lesson-side { border: 1px solid var(--line-soft); background: rgba(255,255,255,.02); padding: 16px; height: fit-content; }
.lesson-side h3 { font-family: var(--display); font-size: 9px; letter-spacing: .18em; color: var(--gold); text-transform: uppercase; margin: 0 0 4px; }
.lesson-side p { font-size: 11.5px; font-style: italic; color: rgba(205,189,158,.6); line-height: 1.5; margin: 0 0 14px; }
.lesson-item { display: flex; align-items: center; gap: 9px; padding: 9px 0; border-top: 1px solid var(--line-soft); }
.lesson-num { width: 22px; height: 22px; border: 1px solid var(--line); border-radius: 50%; display: grid; place-items: center; font-family: var(--display); font-size: 7px; color: var(--gold-dim); flex: none; }
.lesson-item.done .lesson-num { border-color: var(--teal); color: var(--teal); background: rgba(125,230,208,.08); }
.lesson-item .li-body { flex: 1; min-width: 0; }
.lesson-item .li-name { font-family: var(--display); font-size: 7.5px; letter-spacing: .06em; color: var(--parch-dim); }
.lesson-item .li-sub { font-size: 9.5px; font-style: italic; color: rgba(205,189,158,.45); }
.lesson-item button { font-family: var(--display); font-size: 6px; letter-spacing: .1em; padding: 4px 6px; border: 1px solid var(--line); color: var(--gold-dim); text-transform: uppercase; }
.lesson-item button:hover { color: var(--gold); border-color: var(--gold); }
.lesson-item button:disabled { opacity: .3; cursor: not-allowed; }

/* quests */
.quest-list { display: flex; flex-direction: column; gap: 7px; }
.quest-card { display: flex; gap: 14px; padding: 13px 15px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.018); }
.quest-card.active { border-left: 2px solid var(--gold); background: linear-gradient(90deg, rgba(233,201,136,.05), transparent); }
.quest-card.done { opacity: .55; }
.quest-rune { font-size: 17px; color: var(--gold-dim); width: 26px; text-align: center; padding-top: 2px; }
.quest-card.active .quest-rune { color: var(--gold); text-shadow: 0 0 12px rgba(233,201,136,.4); }
.quest-card.done .quest-rune { color: var(--teal); }
.quest-body { flex: 1; }
.quest-name { font-family: var(--display); font-size: 10.5px; letter-spacing: .04em; color: var(--parch); }
.quest-desc { font-size: 11.5px; font-style: italic; color: rgba(205,189,158,.6); margin: 3px 0 7px; line-height: 1.4; }
.quest-obj { display: flex; align-items: center; gap: 7px; font-size: 11px; color: rgba(241,228,200,.72); }
.quest-obj::before { content: '◆'; font-size: 5px; color: var(--gold); }
.quest-obj.done { color: var(--teal); }
.quest-obj.done::before { color: var(--teal); }
.quest-reward { margin-left: auto; font-family: var(--display); font-size: 7px; letter-spacing: .08em; color: var(--gold-dim); white-space: nowrap; }
.quest-progress { margin-top: 8px; height: 2px; background: rgba(255,255,255,.07); }
.quest-progress div { height: 100%; background: var(--gold-dim); }

.achievement-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.achv { display: flex; gap: 9px; align-items: center; padding: 8px 9px; border: 1px solid rgba(255,255,255,.05); opacity: .45; }
.achv.unlocked { opacity: 1; border-color: rgba(233,201,136,.25); background: rgba(233,201,136,.04); }
.achv span { font-size: 14px; color: var(--gold-dim); }
.achv.unlocked span { color: var(--gold); text-shadow: 0 0 10px rgba(233,201,136,.4); }
.achv b { display: block; font-family: var(--display); font-size: 7px; letter-spacing: .06em; color: var(--parch-dim); }
.achv small { font-size: 9.5px; color: rgba(205,189,158,.45); font-style: italic; }

/* shop */
.shop-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; }
.npc-card { display: flex; gap: 12px; padding: 12px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.022); margin-bottom: 7px; }
.npc-card.active { border-color: var(--gold-dim); background: rgba(233,201,136,.05); }
.npc-face { width: 40px; height: 40px; flex: none; border-radius: 50%; display: grid; place-items: center; font-family: var(--display); font-size: 12px; color: var(--gold); background: radial-gradient(circle at 35% 30%, var(--npc, #4a3a72), #120c20); border: 1px solid rgba(233,201,136,.25); }
.npc-info { flex: 1; min-width: 0; }
.npc-name { font-family: var(--display); font-size: 9.5px; color: var(--parch); }
.npc-desc { font-size: 10.5px; font-style: italic; color: rgba(205,189,158,.55); line-height: 1.35; margin: 2px 0 5px; }
.npc-wants { display: flex; flex-wrap: wrap; gap: 3px; }
.want-chip { font-family: var(--display); font-size: 5.8px; letter-spacing: .08em; padding: 2px 5px; border: 1px solid var(--line-soft); color: var(--parch-dim); text-transform: uppercase; }
.npc-budget { font-family: var(--display); font-size: 7px; color: var(--gold); margin-left: auto; white-space: nowrap; }
.offer-list { max-height: 360px; overflow-y: auto; display: flex; flex-direction: column; gap: 5px; }
.offer-wand { display: flex; align-items: center; gap: 10px; padding: 9px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.018); transition: .15s; text-align: left; }
.offer-wand:hover { border-color: var(--gold-dim); background: rgba(233,201,136,.04); }
.offer-wand.equipped { border-color: rgba(125,230,208,.25); }
.offer-wand .ow-icon { font-size: 18px; color: var(--rar, var(--gold)); text-shadow: 0 0 12px var(--rar, var(--gold)); width: 24px; text-align: center; }
.offer-wand .ow-info { flex: 1; min-width: 0; }
.offer-wand .ow-name { font-family: var(--display); font-size: 8.5px; color: var(--parch); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.offer-wand .ow-sub { font-size: 10px; font-style: italic; color: rgba(205,189,158,.48); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.offer-wand .ow-val { font-family: var(--display); font-size: 8px; color: var(--gold); }
.match-badge { position: absolute; }
.upgrade-card { display: flex; gap: 12px; align-items: center; padding: 12px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.02); margin-bottom: 6px; }
.upgrade-card.owned { opacity: .55; border-color: rgba(125,230,208,.2); }
.upg-icon { font-size: 20px; color: var(--gold); width: 30px; text-align: center; }
.upg-info { flex: 1; }
.upg-info b { display: block; font-family: var(--display); font-size: 8.5px; color: var(--parch); }
.upg-info small { font-size: 10.5px; font-style: italic; color: rgba(205,189,158,.55); line-height: 1.35; display: block; margin-top: 2px; }
.buy-btn { font-family: var(--display); font-size: 7px; letter-spacing: .1em; padding: 6px 9px; border: 1px solid var(--line); color: var(--gold); text-transform: uppercase; white-space: nowrap; }
.buy-btn:hover { border-color: var(--gold); background: rgba(233,201,136,.08); }
.market-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.market-item { display: flex; align-items: center; gap: 8px; padding: 8px; border: 1px solid rgba(255,255,255,.05); background: rgba(255,255,255,.018); }
.market-item .ing-orb { width: 24px; height: 24px; }
.market-item b { font-family: var(--display); font-size: 7px; color: var(--parch-dim); flex: 1; }
.market-item small { font-family: var(--display); font-size: 7px; color: var(--gold); }

/* map */
.atlas-layout { display: grid; grid-template-columns: 1fr 280px; gap: 22px; }
.atlas-map { position: relative; aspect-ratio: 1.25; border: 1px solid var(--line-soft); overflow: hidden; background: radial-gradient(ellipse at 45% 40%, #1a2030, #0a0a16 75%); }
.atlas-map svg { width: 100%; height: 100%; }
.atlas-side { display: flex; flex-direction: column; gap: 6px; }
.zone-card { display: flex; gap: 10px; padding: 10px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.018); text-align: left; transition: .15s; }
.zone-card:hover { border-color: var(--line); }
.zone-card.locked { opacity: .45; }
.zone-card.here { border-color: var(--gold-dim); background: rgba(233,201,136,.05); }
.zone-rune { font-size: 15px; color: var(--gold-dim); width: 20px; text-align: center; }
.zone-card.here .zone-rune { color: var(--gold); }
.zone-info { flex: 1; }
.zone-name { font-family: var(--display); font-size: 8px; letter-spacing: .04em; color: var(--parch); }
.zone-sub { font-size: 9.5px; font-style: italic; color: rgba(205,189,158,.45); line-height: 1.3; margin-top: 2px; }
.zone-travel { font-family: var(--display); font-size: 6px; letter-spacing: .1em; padding: 4px 6px; border: 1px solid var(--line); color: var(--gold-dim); align-self: center; text-transform: uppercase; }
.zone-travel:hover { color: var(--gold); border-color: var(--gold); }
.zone-travel:disabled { opacity: .3; cursor: not-allowed; }

/* character */
.char-layout { display: grid; grid-template-columns: 280px 1fr; gap: 24px; }
.char-hero { border: 1px solid var(--line-soft); background: radial-gradient(ellipse at 50% 0%, rgba(120,83,190,.16), transparent 65%), rgba(255,255,255,.015); padding: 22px; text-align: center; height: fit-content; }
.char-sigil { width: 92px; height: 92px; margin: 0 auto 12px; border-radius: 50%; display: grid; place-items: center; border: 1px solid rgba(233,201,136,.35); background: radial-gradient(circle at 35% 28%, #3e2c63, #100b1e 70%); position: relative; font-family: var(--display); font-size: 26px; color: var(--gold); }
.char-sigil::before { content: ''; position: absolute; inset: -7px; border: 1px dashed rgba(233,201,136,.2); border-radius: 50%; animation: spin 40s linear infinite; }
.char-hero h3 { font-family: var(--display); font-size: 16px; margin: 0 0 2px; }
.char-hero .char-title { font-size: 12px; font-style: italic; color: var(--gold-dim); }
.char-levelbar { margin: 16px 0 10px; height: 4px; background: rgba(255,255,255,.08); }
.char-levelbar div { height: 100%; background: linear-gradient(90deg, var(--arcane-2), var(--arcane)); }
.char-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; text-align: left; margin-top: 18px; }
.char-stat { padding: 8px; border: 1px solid rgba(255,255,255,.05); }
.char-stat span { display: block; font-family: var(--display); font-size: 6px; letter-spacing: .14em; text-transform: uppercase; color: rgba(205,189,158,.45); }
.char-stat b { font-family: var(--display); font-size: 13px; color: var(--gold); }
.equipped-wand { display: flex; gap: 14px; align-items: center; padding: 15px; border: 1px solid var(--line-soft); background: rgba(233,201,136,.03); margin-bottom: 14px; }
.equipped-wand .ew-art { width: 80px; height: 80px; flex: none; display: grid; place-items: center; }
.equipped-wand .ew-art svg { width: 100%; height: 100%; }
.equipped-wand h4 { font-family: var(--display); font-size: 12px; margin: 0 0 2px; }
.equipped-wand p { margin: 0; font-size: 10.5px; font-style: italic; color: rgba(205,189,158,.5); }
.trait-list { display: flex; flex-direction: column; gap: 5px; }
.trait-line { display: flex; gap: 8px; align-items: baseline; font-size: 11.5px; color: rgba(205,189,158,.72); padding: 6px 0; border-top: 1px solid var(--line-soft); }
.trait-line b { font-family: var(--display); font-size: 6.5px; letter-spacing: .1em; color: var(--gold); text-transform: uppercase; min-width: 85px; }

/* ── MODAL ───────────────────────────────────────────────── */
#modal { position: absolute; inset: 0; z-index: 70; display: flex; align-items: center; justify-content: center; padding: 4vh 4vw; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(5,3,10,.75); backdrop-filter: blur(6px); }
.modal-card {
  position: relative; width: min(680px, 92vw); max-height: 88vh; overflow-y: auto;
  background: linear-gradient(145deg, rgba(26,18,44,.99), rgba(11,8,20,.995));
  border: 1px solid rgba(233,201,136,.3); box-shadow: var(--shadow); padding: 30px 32px;
  animation: modalIn .3s cubic-bezier(.2,.8,.2,1);
}
.modal-card::before { content: ''; position: absolute; inset: 6px; border: 1px solid rgba(233,201,136,.08); pointer-events: none; }
@keyframes modalIn { from { opacity: 0; transform: scale(.95) translateY(12px); } }
.modal-card.wide { width: min(860px, 94vw); }
.modal-kicker { font-family: var(--display); font-size: 7px; letter-spacing: .28em; color: var(--gold-dim); text-transform: uppercase; text-align: center; }
.modal-title { font-family: var(--display); font-size: 24px; text-align: center; margin: 5px 0 6px; color: var(--parch); }
.modal-sub { font-size: 13px; font-style: italic; text-align: center; color: rgba(205,189,158,.6); margin: 0 0 20px; line-height: 1.5; }
.modal-actions { display: flex; justify-content: center; gap: 10px; margin-top: 22px; }
.modal-sep { height: 1px; background: linear-gradient(90deg, transparent, var(--line), transparent); margin: 16px 0; }
.reward-row { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; margin: 16px 0; }
.reward { display: flex; align-items: center; gap: 7px; font-family: var(--display); font-size: 9px; letter-spacing: .05em; color: var(--parch); }
.reward span { font-size: 14px; color: var(--gold); }
.reward.rep span { color: var(--arcane); }
.reward.xp span { color: var(--teal); }

/* challenge */
.challenge { text-align: center; }
.challenge-head { display: flex; justify-content: space-between; font-family: var(--display); font-size: 7px; letter-spacing: .18em; color: var(--gold-dim); text-transform: uppercase; margin-bottom: 12px; }
.challenge-timer { height: 3px; background: rgba(255,255,255,.08); margin-bottom: 20px; }
.challenge-timer div { height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); transition: width .1s linear; }
.rune-row { display: flex; justify-content: center; gap: 9px; flex-wrap: wrap; margin: 8px 0 18px; }
.rune-btn {
  width: 62px; height: 62px; display: grid; place-items: center; font-size: 25px; color: var(--rn, var(--gold));
  border: 1px solid rgba(233,201,136,.2); background: radial-gradient(circle at 40% 32%, rgba(255,255,255,.06), transparent 60%), rgba(255,255,255,.02);
  transition: .15s; position: relative;
}
.rune-btn:hover { border-color: var(--rn, var(--gold)); background: rgba(233,201,136,.06); }
.rune-btn.flash { background: color-mix(in srgb, var(--rn) 22%, transparent); border-color: var(--rn); box-shadow: 0 0 26px color-mix(in srgb, var(--rn) 55%, transparent); transform: scale(1.06); }
.rune-btn.wrong { animation: shake .3s; border-color: var(--rose); }
.rune-btn.done { opacity: .35; pointer-events: none; }
@keyframes shake { 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }
.rune-preview { font-size: 12.5px; font-style: italic; color: rgba(205,189,158,.55); min-height: 19px; margin-bottom: 6px; }
.timing-track { position: relative; height: 44px; border: 1px solid rgba(233,201,136,.2); background: rgba(255,255,255,.025); margin: 22px 0; overflow: hidden; }
.timing-track .zone { position: absolute; top: 0; bottom: 0; background: rgba(233,201,136,.14); border-left: 1px solid rgba(233,201,136,.5); border-right: 1px solid rgba(233,201,136,.5); }
.timing-track .zone.best { background: rgba(255,220,140,.28); }
.timing-track .needle { position: absolute; top: -3px; bottom: -3px; width: 3px; background: var(--parch); box-shadow: 0 0 14px var(--gold); }
.lesson-steps { display: flex; justify-content: center; gap: 7px; margin: 10px 0 2px; }
.lesson-step { width: 24px; height: 3px; background: rgba(255,255,255,.1); }
.lesson-step.done { background: var(--teal); box-shadow: 0 0 8px var(--teal); }
.challenge-status { font-family: var(--display); font-size: 8px; letter-spacing: .16em; color: rgba(205,189,158,.55); min-height: 18px; text-transform: uppercase; }

/* ── DIALOGUE ────────────────────────────────────────────── */
#dialogue {
  position: absolute; left: 50%; bottom: 116px; transform: translateX(-50%); z-index: 40;
  width: min(680px, 88vw); display: flex; gap: 16px; padding: 17px 20px;
  background: linear-gradient(140deg, rgba(24,17,41,.97), rgba(11,8,20,.97));
  border: 1px solid rgba(233,201,136,.3); box-shadow: 0 20px 60px rgba(0,0,0,.6);
  animation: dlgIn .3s ease;
}
@keyframes dlgIn { from { opacity: 0; transform: translate(-50%, 12px); } }
.dlg-portrait { width: 52px; height: 52px; flex: none; border-radius: 50%; display: grid; place-items: center; font-family: var(--display); font-size: 16px; color: var(--gold); border: 1px solid rgba(233,201,136,.35); background: radial-gradient(circle at 35% 30%, #4b376f, #0f0a1a 70%); }
.dlg-body { flex: 1; min-width: 0; }
.dlg-name { font-family: var(--display); font-size: 9px; letter-spacing: .18em; color: var(--gold); text-transform: uppercase; margin-bottom: 4px; }
.dlg-text { font-size: 14px; font-style: italic; line-height: 1.5; color: var(--parch-dim); }
.dlg-choices { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 11px; }
.dlg-choice { font-family: var(--display); font-size: 7.5px; letter-spacing: .1em; padding: 7px 11px; border: 1px solid var(--line); color: var(--parch-dim); text-transform: uppercase; transition: .15s; }
.dlg-choice:hover { border-color: var(--gold); color: var(--gold); background: rgba(233,201,136,.06); }
.dlg-close { position: absolute; top: 8px; right: 10px; font-size: 10px; color: rgba(205,189,158,.5); }
.dlg-close:hover { color: var(--gold); }

/* ── FX ──────────────────────────────────────────────────── */
#fade { position: absolute; inset: 0; z-index: 80; background: #06040c; opacity: 0; pointer-events: none; transition: opacity .55s ease; }
#fade.on { opacity: 1; pointer-events: all; }
#spell-banner {
  position: absolute; z-index: 65; top: 22%; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 16px; padding: 16px 40px 16px 24px;
  background: radial-gradient(ellipse at left, rgba(171,140,255,.2), transparent 70%), rgba(12,8,22,.9);
  border: 1px solid rgba(233,201,136,.3); border-left: 2px solid var(--gold); animation: bannerIn .5s ease both;
  box-shadow: 0 20px 70px rgba(0,0,0,.6);
}
#spell-banner.hide { animation: bannerOut .5s ease forwards; }
#spell-banner-rune { font-size: 28px; color: var(--gold); text-shadow: 0 0 20px var(--gold); }
#spell-banner small { display: block; font-family: var(--display); font-size: 6.5px; letter-spacing: .26em; color: var(--gold-dim); }
#spell-banner b { font-family: var(--display); font-size: 19px; letter-spacing: .04em; color: var(--parch); }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, -18px) scale(.96); } }
@keyframes bannerOut { to { opacity: 0; transform: translate(-50%, -20px) scale(.97); } }
#level-flash { position: absolute; inset: 0; z-index: 66; display: grid; place-items: center; pointer-events: none; }
.lf-ring { position: absolute; width: 240px; height: 240px; border-radius: 50%; border: 1px solid var(--gold); animation: lfRing 1.8s ease-out forwards; }
.lf-text { text-align: center; animation: lfText 2.2s ease forwards; }
.lf-text small { display: block; font-family: var(--display); font-size: 8px; letter-spacing: .4em; color: var(--gold); }
.lf-text b { display: block; font-family: var(--display); font-size: 64px; line-height: 1; color: var(--parch); text-shadow: 0 0 40px rgba(233,201,136,.6); }
.lf-text span { font-family: var(--display); font-size: 9px; letter-spacing: .24em; text-transform: uppercase; color: var(--gold-dim); }
@keyframes lfRing { from { transform: scale(.3); opacity: 1; } to { transform: scale(1.7); opacity: 0; } }
@keyframes lfText { 0% { opacity: 0; transform: translateY(10px); } 15%, 70% { opacity: 1; transform: none; } 100% { opacity: 0; } }

/* misc animation classes */
.shake { animation: shake .3s; }
.flash-white { animation: flashWhite .25s; }
@keyframes flashWhite { from { filter: brightness(2.2); } }
.fade-in { animation: fadeIn .4s ease; }

/* responsive-ish */
@media (max-width: 1100px) {
  .title-side { display: none; }
  .title-inner { width: 70vw; }
  .craft-layout, .shop-layout { grid-template-columns: 1fr; }
  .spell-layout, .atlas-layout, .char-layout { grid-template-columns: 1fr; }
  .ing-grid { max-height: 190px; }
  .wand-stage { min-height: 200px; }
}
@media (max-height: 760px) {
  .title-features { margin-top: 22px; }
  .game-title { font-size: clamp(60px, 8vw, 110px); }
  .title-tagline { margin-bottom: 20px; }
  .hint-panel { display: none; }
}
@media (max-width: 760px) {
  #title-screen { align-items: flex-start; padding-top: 12vh; }
  .title-inner { width: 100%; }
  .title-features { flex-wrap: wrap; }
  .hud-left { display: none; }
  .hud-top-left { transform: scale(.8); transform-origin: top left; }
  .minimap-wrap { width: 100px; height: 100px; }
  .action-rail { right: 10px; }
  .grimoire-nav { width: 54px; }
  .nav-brand, .nav-btn { font-size: 0; padding: 13px 0; justify-content: center; }
  .nav-btn span { font-size: 16px; }
  .nav-foot { display: none; }
  .grimoire-head { padding: 16px 18px 12px; }
  .grimoire-body { padding: 16px; }
  .spell-grid { grid-template-columns: 1fr; }
  .ing-grid, .market-grid, .achievement-grid { grid-template-columns: 1fr; }
}

