    pad.rotation.x = -Math.PI / 2; pad.position.set(x, 0.14, z); group.add(pad);
    if (random() > 0.55) {
      const f = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.28, 6), flowerMat);
      f.position.set(x, 0.28, z); group.add(f);
      addGlow(group, '#d3a7ff', 0.8, x, 0.3, z, 0.4);
    }
    lilies.push(pad);
  }
  // island shrine
  const island = new THREE.Group(); island.position.set(66, 0, 96); group.add(island);
  const rockBase = new THREE.Mesh(new THREE.DodecahedronGeometry(5.2, 1), std('#4a4d52'));
  rockBase.scale.set(1.5, 0.7, 1.2); rockBase.position.y = 0.8; island.add(rockBase);
  addBox(island, { w: 4.4, h: 0.3, d: 3.6, y: 2.9, mat: std('#6c6a63') });
  for (const sx of [-1.4, 1.4]) addCyl(island, { r: 0.22, h: 3.2, seg: 6, x: sx, y: 4.5, z: 0, color: '#6c6a63' });
  addBox(island, { w: 3.3, h: 0.3, d: 0.4, y: 6.05, mat: std('#6c6a63') });
  addGlow(island, '#8fe7ff', 3.2, 0, 5.2, 0, 0.25);
  addTreeCluster(island, 1.8, -0.8, random, { scale: 0.55, n: 1, leaf: ['#2f4d3a'] });

  // moon path on water
  const shimmer = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 44), new THREE.MeshBasicMaterial({ map: canvasTexture(128, 512, (c, w, h) => {
    const g = c.createLinearGradient(0, 0, w, 0);
    g.addColorStop(0, 'rgba(220,235,255,0)'); g.addColorStop(0.5, 'rgba(220,235,255,.35)'); g.addColorStop(1, 'rgba(220,235,255,0)');
    c.fillStyle = g; c.fillRect(0, 0, w, h);
    for (let i = 0; i < 60; i++) { c.fillStyle = `rgba(255,255,240,${Math.random() * 0.35})`; c.fillRect(Math.random() * w, Math.random() * h, 2 + Math.random() * 3, 1); }
  }), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.55 }));
  shimmer.rotation.x = -Math.PI / 2; shimmer.position.set(52, 0.2, 92); group.add(shimmer);
  anims.push((dt, t) => { shimmer.material.opacity = 0.35 + Math.sin(t * 0.7) * 0.12; lilies.forEach((p, i) => { p.rotation.z = Math.sin(t * 0.4 + i) * 0.03; }); });

  // lake spot interact hints handled in world
  const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(2.2, 0), std('#454a50'));
  rock.position.set(40, 0.4, 80); rock.scale.set(1.2, 0.5, 1); group.add(rock);
  addGlow(group, '#7de6d0', 1.6, 40, 1.0, 80, 0.2);
}

import * as THREE from 'three';
import { std, addBox, addCyl, addCone, addGlow, addPointLight, textPlane, canvasTexture, heightAt, mulberry32, TAU, pick, addTreeCluster, runeRingTexture } from './worldkit.js';

function portalVisual(color = '#8fe7ff', radius = 2.4, opacity = 0.9) {
  const group = new THREE.Group();
  const ringMat = new THREE.MeshStandardMaterial({ color: '#2b2733', roughness: 0.7 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(radius + 0.25, 0.22, 8, 36), ringMat);
  group.add(ring);
  const innerRing = new THREE.Mesh(new THREE.TorusGeometry(radius - 0.12, 0.07, 6, 36), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending }));
  group.add(innerRing);
  const uniforms = { time: { value: 0 }, color: { value: new THREE.Color(color) }, opacity: { value: opacity } };
  const mat = new THREE.ShaderMaterial({
    uniforms, transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader: `
      varying vec2 vUv; uniform float time; uniform vec3 color; uniform float opacity;
      void main(){
        vec2 p = vUv - 0.5; float r = length(p) * 2.0; float a = atan(p.y, p.x);
        float swirl = sin(a * 6.0 + r * 15.0 - time * 2.2) * 0.5 + 0.5;
        float swirl2 = sin(a * -3.0 + r * 9.0 + time * 1.3) * 0.5 + 0.5;
        float edge = smoothstep(1.0, 0.72, r) * smoothstep(0.0, 0.12, r);
        float alpha = edge * (0.28 + 0.72 * swirl * (0.5 + swirl2 * 0.5)) * opacity;
        vec3 col = mix(color * 0.35, color * 1.5, swirl) + vec3(0.8,0.95,1.0) * pow(swirl * swirl2, 9.0) * 0.7;
        gl_FragColor = vec4(col, alpha);
      }`
  });
  const disc = new THREE.Mesh(new THREE.CircleGeometry(radius, 40), mat);
  group.add(disc);
  const glow = addGlow(group, color, radius * 5, 0, 0, 0, 0.35);
  const light = addPointLight(group, color, 2.2, radius * 7, 0, 0, 0.4);
  return { group, uniforms, disc, glow, light, ring, innerRing };
}

function emberFlame(group, x, y, z, color = '#ffb35c', scale = 1) {
  const g = new THREE.Group(); g.position.set(x, y, z); group.add(g);
  addGlow(g, color, 1.6 * scale, 0, 0, 0, 0.7);
  addGlow(g, color, 3.4 * scale, 0, 0.2, 0, 0.22);
  const core = new THREE.Mesh(new THREE.SphereGeometry(0.16 * scale, 8, 6), new THREE.MeshBasicMaterial({ color: '#fff2cc' }));
  core.position.y = 0.1 * scale; g.add(core);
  const light = addPointLight(g, color, 1.5, 12 * scale, 0, 0.4, 0);
  return { g, light };
}

/* ══════════════════════════════════════════ SUNKEN RUINS */
export function buildRuins(ctx) {
  const { group, colliders, anims } = ctx;
  const random = mulberry32(4411);
  const cx = -78, cz = 82;
  const baseY = heightAt(cx, cz);
  const g = new THREE.Group(); g.position.set(cx, baseY, cz); group.add(g);
  const stoneMat = std('#4b5254', { roughness: 0.95 });
  const stoneDark = std('#383e42', { roughness: 0.95 });

  addCyl(g, { rt: 13.5, rb: 14.5, h: 1.3, seg: 32, y: 0.15, mat: stoneMat });
  const floorTex = canvasTexture(512, 512, (c, w, h) => {
    c.fillStyle = '#3d4345'; c.fillRect(0, 0, w, h);
    for (let i = 0; i < 900; i++) { c.fillStyle = `rgba(${40 + Math.random() * 40},${48 + Math.random() * 40},${50 + Math.random() * 36},.5)`; c.fillRect(Math.random() * w, Math.random() * h, 3 + Math.random() * 10, 2 + Math.random() * 6); }
    c.strokeStyle = 'rgba(120,200,220,.25)'; c.lineWidth = 2;
    for (let i = 0; i < 5; i++) { c.beginPath(); c.arc(256, 256, 40 + i * 42, 0, TAU); c.stroke(); }
  });
  const floor = new THREE.Mesh(new THREE.CircleGeometry(13.2, 48), new THREE.MeshStandardMaterial({ map: floorTex, roughness: 0.92 }));
  floor.rotation.x = -Math.PI / 2; floor.position.y = 0.82; floor.receiveShadow = true; g.add(floor);

  // pools
  for (const [px, pz, r] of [[-5, 4, 2.6], [6, -2, 2.0], [2, 7, 1.6]]) {
    const pool = new THREE.Mesh(new THREE.CircleGeometry(r, 24), new THREE.MeshPhysicalMaterial({ color: '#1d4b55', emissive: '#0b2e36', emissiveIntensity: 0.5, roughness: 0.05, metalness: 0.4, transparent: true, opacity: 0.92 }));
    pool.rotation.x = -Math.PI / 2; pool.position.set(px, 0.93, pz); g.add(pool);
  }

  // broken columns
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU + 0.2;
    const r = 10.4;
    const h = 2 + random() * 6;
    const col = addCyl(g, { rt: 0.52, rb: 0.68, h, seg: 10, x: Math.cos(a) * r, y: h / 2 + 0.8, z: Math.sin(a) * r, color: '#4d5456', mat: stoneMat });
    col.rotation.z = (random() - 0.5) * 0.13;
    col.rotation.x = (random() - 0.5) * 0.1;
    if (h > 4) addBox(g, { w: 1.5, h: 0.35, d: 1.5, x: Math.cos(a) * r, y: h + 0.9, z: Math.sin(a) * r, mat: stoneDark });
    if (i % 2 === 0) {
      const rune = textPlane(pick(['ᚦ', 'ᛉ', 'ᛟ', 'ᚱ', 'ᛏ', 'ᛒ']), { color: '#8fe7ff', bg: 'transparent', border: 'transparent', width: 128, height: 128, font: '90px Georgia, serif' });
      const rr = 2.5;
      rune.scale.set(0.7, 0.7, 1);
      rune.position.set(Math.cos(a) * r - Math.cos(a) * 0.6, 2.4, Math.sin(a) * r - Math.sin(a) * 0.6);
      rune.rotation.y = -a + Math.PI / 2;
      g.add(rune);
    }
  }

  // fall arches
  for (const [ax, az, ry, h] of [[-4.5, -7, 0.3, 6.5], [8, 6, -0.8, 5.2], [-10, 3, 1.2, 4.6]]) {
    const arch = new THREE.Group(); arch.position.set(ax, 0.8, az); arch.rotation.y = ry; g.add(arch);
    for (const sx of [-1.6, 1.6]) addCyl(arch, { r: 0.4, h, seg: 8, x: sx, y: h / 2, z: 0, color: '#4d5456' });
    addBox(arch, { w: 3.9, h: 0.65, d: 0.9, y: h, mat: stoneDark });
    arch.rotation.z = (random() - 0.5) * 0.06;
  }

  // central warden seal / portal
  const seal = new THREE.Group(); seal.position.set(0, 1.5, 0); g.add(seal);
  const portal = portalVisual('#8fe7ff', 2.3, 0.75);
  portal.group.position.set(0, 2.8, 0); seal.add(portal.group);
  // arch frame around portal
  for (const sx of [-2.9, 2.9]) addCyl(seal, { r: 0.45, h: 5.4, seg: 8, x: sx, y: 2.7, z: 0, color: '#434b4d' });
  addBox(seal, { w: 6.3, h: 0.7, d: 1.0, y: 5.5, mat: stoneDark });
  addBox(seal, { w: 0.8, h: 2.6, d: 0.3, y: 6.6, mat: stoneDark });
  const sealRing = new THREE.Mesh(new THREE.RingGeometry(3.7, 4.2, 40), new THREE.MeshBasicMaterial({ map: runeRingTexture('#8fe7ff'), color: '#8fe7ff', transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false }));
  sealRing.rotation.x = -Math.PI / 2; sealRing.position.y = -0.55; seal.add(sealRing);
  addGlow(seal, '#8fe7ff', 11, 0, 0.2, 0, 0.15);
  addPointLight(seal, '#8fe7ff', 3.2, 30, 0, 3.4, 1);
  colliders.push({ x: cx, z: cz, r: 2.2 });

  // floating stones
  const floats = [];
  for (let i = 0; i < 8; i++) {
    const a = random() * TAU, r = 5 + random() * 8;
    const st = new THREE.Mesh(new THREE.DodecahedronGeometry(0.3 + random() * 0.7, 0), stoneMat);
    st.position.set(Math.cos(a) * r, 2 + random() * 5, Math.sin(a) * r); g.add(st);
    floats.push({ m: st, base: st.position.y, phase: random() * TAU, spin: (random() - 0.5) * 0.5 });
  }
  // rubble
  for (let i = 0; i < 26; i++) {
    const a = random() * TAU, r = 3 + random() * 12;
    const rb = new THREE.Mesh(new THREE.DodecahedronGeometry(0.15 + random() * 0.5, 0), stoneMat);
    rb.position.set(Math.cos(a) * r, 0.95, Math.sin(a) * r); rb.rotation.set(random() * 3, random() * 3, random() * 3); g.add(rb);
  }
  // broken statue
  const statue = new THREE.Group(); statue.position.set(-8, 0.9, -4); g.add(statue);
  addBox(statue, { w: 1.1, h: 2.4, d: 0.8, y: 1.2, mat: stoneMat, rz: 0.18 });
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.46, 10, 8), stoneMat);
  head.position.set(0.5, 2.6, 0); statue.add(head);
  const halo = new THREE.Mesh(new THREE.TorusGeometry(0.7, 0.06, 6, 24, Math.PI), new THREE.MeshBasicMaterial({ color: '#8fe7ff', transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending }));
  halo.position.set(0.5, 2.8, -0.2); halo.rotation.z = 0.2; statue.add(halo);

  anims.push((dt, t) => {
    portal.uniforms.time.value = t;
    portal.innerRing.rotation.z = t * 0.4;
    sealRing.rotation.z = t * 0.06;
    floats.forEach((f, i) => { f.m.position.y = f.base + Math.sin(t * 0.7 + f.phase) * 0.3; f.m.rotation.y += dt * f.spin; });
  });
}

/* ══════════════════════════════════════════ GLIMMER CAVERNS */
export function buildCaverns(ctx) {
  const { group, colliders, anims } = ctx;
  const random = mulberry32(6311);
  const cx = 104, cz = 66;
  const baseY = heightAt(cx, cz);
  const g = new THREE.Group(); g.position.set(cx, baseY, cz); group.add(g);
  const rockMat = std('#3b3748', { roughness: 0.98 });
  const rockMat2 = std('#302d3e', { roughness: 0.98 });

  // mound
  const mound = new THREE.Mesh(new THREE.DodecahedronGeometry(12, 1), rockMat);
  mound.scale.set(1.35, 0.9, 1.1); mound.position.y = 3; mound.rotation.y = 0.4; g.add(mound);
  for (let i = 0; i < 8; i++) {
    const a = random() * TAU, r = 7 + random() * 6;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const h = 3 + random() * 9;
    const peak = new THREE.Mesh(new THREE.ConeGeometry(1.4 + random() * 2.2, h, 5), random() > 0.5 ? rockMat : rockMat2);
    peak.position.set(x, h / 2 + 2, z); peak.rotation.y = random() * 3; peak.rotation.z = (random() - 0.5) * 0.2; g.add(peak);
  }
  // entrance facing south-west (towards village)
  const mouth = new THREE.Group(); mouth.position.set(-7.6, 4.2, -6.4); mouth.rotation.y = -2.36; g.add(mouth);
  const dark = new THREE.Mesh(new THREE.CircleGeometry(2.6, 26), new THREE.MeshBasicMaterial({ color: '#07050f' }));
  dark.scale.y = 1.3; mouth.add(dark);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(2.75, 0.4, 7, 26), rockMat2);
  rim.scale.y = 1.3; mouth.add(rim);
  addGlow(mouth, '#8a5bff', 6, 0, 0, -0.4, 0.3);
  addPointLight(mouth, '#7d55ff', 2.6, 22, 0, 0.4, -0.4);
  // steps into the dark
  for (let i = 0; i < 5; i++) addBox(g, { w: 3.6 - i * 0.25, h: 0.25, d: 0.9, x: -8.2 - i * 0.15, y: 0.1 + i * 0.28, z: -5.8 + i * 0.4, mat: rockMat2, shadow: false });

  // crystals
  const crystalMats = [
    new THREE.MeshStandardMaterial({ color: '#6b4dff', emissive: '#5b34e6', emissiveIntensity: 1.1, roughness: 0.15, metalness: 0.2 }),
    new THREE.MeshStandardMaterial({ color: '#65e6ff', emissive: '#24c5e8', emissiveIntensity: 1.0, roughness: 0.1, metalness: 0.2 }),
    new THREE.MeshStandardMaterial({ color: '#c56bff', emissive: '#9b32e0', emissiveIntensity: 0.9, roughness: 0.2 })
  ];
  const crystals = [];
  for (let i = 0; i < 46; i++) {
    const a = random() * TAU, r = 3 + random() * 11;
    const x = cx + Math.cos(a) * r, z = cz + Math.sin(a) * r;
    if (Math.hypot(x - (cx - 7), z - (cz - 7)) < 2.5) continue;
    const y = heightAt(x, z) + 0.1;
    const s = 0.3 + random() * 1.5;
    const cr = new THREE.Mesh(new THREE.OctahedronGeometry(s, 0), pick(crystalMats));
    cr.position.set(x, y + s * 1.2, z); cr.rotation.set((random() - 0.5) * 0.5, random() * 3, (random() - 0.5) * 0.5);
    cr.scale.y = 1.4 + random() * 1.8; g.add(cr);
    crystals.push(cr);
    if (s > 1.1) addGlow(group, '#9d7bff', s * 4, x, y + s * 1.6, z, 0.18);
  }
  // giant crystal cluster
  for (let i = 0; i < 5; i++) {
    const cr = new THREE.Mesh(new THREE.ConeGeometry(0.8 + i * 0.15, 4 + i * 1.2, 5), crystalMats[i % 3]);
    cr.position.set(cx + 7 + i * 0.9, heightAt(cx + 7, cz - 2) + 2 + i * 0.6, cz - 2 - i * 0.5);
    cr.rotation.z = -0.15 - i * 0.08; g.add(cr);
  }
  addGlow(g, '#b58cff', 16, 8, 6, -2, 0.16);
  addPointLight(g, '#9d7bff', 2.4, 30, 7, 5, -2);
  addPointLight(g, '#5fe0ff', 1.6, 20, -7, 3, 3);
  colliders.push({ x: cx, z: cz, r: 10.5 });
  // warning sign post
  const sign = textPlane('GLIMMER CAVERNS', { font: '700 40px Cinzel, Georgia, serif' });
  sign.scale.set(3.4, 1.05, 1); sign.position.set(cx - 11, heightAt(cx - 11, cz - 10) + 2.4, cz - 10); sign.rotation.y = -0.9; group.add(sign);
  anims.push((dt, t) => {
    crystals.forEach((c, i) => { c.material.emissiveIntensity = 0.8 + Math.sin(t * 1.4 + i) * 0.2; });
  });
}

/* ══════════════════════════════════════════ DRAGON'S CRAG */
export function buildCrag(ctx) {
  const { group, colliders, anims } = ctx;
  const random = mulberry32(9302);
  const cx = 112, cz = -88;
  const baseY = heightAt(cx, cz);
  const g = new THREE.Group(); g.position.set(cx, baseY, cz); group.add(g);
  const rock = std('#4a4640', { roughness: 0.97 });
  const rockDark = std('#37342f', { roughness: 0.97 });
  // peaks
  for (let i = 0; i < 9; i++) {
    const a = random() * TAU, r = 3 + random() * 9;
    const h = 8 + random() * 20;
    const peak = new THREE.Mesh(new THREE.ConeGeometry(2 + random() * 3.5, h, 6), random() > 0.5 ? rock : rockDark);
    peak.position.set(Math.cos(a) * r, h / 2 - 1, Math.sin(a) * r);
    peak.rotation.y = random() * 3; peak.rotation.z = (random() - 0.5) * 0.1; g.add(peak);
  }
  // flat ritual ledge
  addCyl(g, { rt: 8, rb: 9, h: 0.8, seg: 20, y: 0.2, mat: std('#5a554c') });
  // dragon skeleton
  const skel = new THREE.Group(); skel.position.set(2, 0.8, 1); skel.rotation.y = 0.7; g.add(skel);
  const bone = std('#d8cfb4', { roughness: 0.8 });
  addCyl(skel, { rt: 0.18, rb: 0.28, h: 13, seg: 6, y: 0.3, z: 0, color: '#d8cfb4', mat: bone }).rotation.x = Math.PI / 2;
  for (let i = 0; i < 8; i++) {
    const rib = new THREE.Mesh(new THREE.TorusGeometry(1.7 - i * 0.08, 0.11, 5, 18, Math.PI), bone);
    rib.position.set(0, 1.8, 5.4 - i * 1.1);
    rib.rotation.z = Math.PI; rib.rotation.x = 0.12;
    skel.add(rib);
  }
  // skull
  const skull = new THREE.Group(); skull.position.set(0, 1.7, 6.7); skel.add(skull);
  addBox(skull, { w: 1.3, h: 0.85, d: 2.0, mat: bone });
  addCone(skull, { r: 0.55, h: 2.0, seg: 5, y: -0.05, z: 1.5, rx: Math.PI / 2, mat: bone });
  for (const sx of [-0.42, 0.42]) addGlow(skull, '#ff9a5a', 0.55, sx, 0.3, 0.7, 0.7);
  // horns
  for (const sx of [-0.65, 0.65]) {
    const horn = addCone(skull, { r: 0.14, h: 1.6, seg: 5, x: sx, y: 0.55, z: -0.4, mat: bone });
    horn.rotation.x = -0.8; horn.rotation.z = sx > 0 ? -0.3 : 0.3;
  }
  // ember crystals and cracks
  const emberMat = new THREE.MeshStandardMaterial({ color: '#ff8b45', emissive: '#ff5a1f', emissiveIntensity: 1.4, roughness: 0.2 });
  for (let i = 0; i < 18; i++) {
    const a = random() * TAU, r = 2 + random() * 7;
    const s = 0.25 + random() * 0.9;
    const cr = new THREE.Mesh(new THREE.OctahedronGeometry(s, 0), emberMat);
    cr.position.set(Math.cos(a) * r, 1 + s, Math.sin(a) * r); cr.scale.y = 1.5; g.add(cr);
    addGlow(g, '#ff8b45', s * 3, cr.position.x, cr.position.y, cr.position.z, 0.2);
  }
  const rift = new THREE.Mesh(new THREE.PlaneGeometry(12, 1.1), new THREE.MeshBasicMaterial({ map: canvasTexture(256, 64, (c, w, h) => {
    const gr = c.createLinearGradient(0, 0, 0, h); gr.addColorStop(0, 'rgba(255,140,60,0)'); gr.addColorStop(0.5, 'rgba(255,150,70,.85)'); gr.addColorStop(1, 'rgba(255,80,20,0)');
    c.fillStyle = gr; c.fillRect(0, 0, w, h);
  }), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.65 }));
  rift.rotation.x = -Math.PI / 2; rift.position.set(-2, 0.72, -3); rift.rotation.z = 0.5; g.add(rift);
  addPointLight(g, '#ff7a3d', 2.4, 24, 0, 3, 2);
  addGlow(g, '#ff8b45', 13, 0, 3, 1, 0.1);
  // floating rocks
  const floats = [];
  for (let i = 0; i < 7; i++) {
    const a = random() * TAU, r = 6 + random() * 8;
    const m = new THREE.Mesh(new THREE.DodecahedronGeometry(0.5 + random() * 1.2, 0), rock);
    m.position.set(Math.cos(a) * r, 3 + random() * 7, Math.sin(a) * r); m.rotation.set(random() * 3, random() * 3, 0); g.add(m);
    floats.push({ m, base: m.position.y, phase: random() * TAU });
  }
  colliders.push({ x: cx, z: cz, r: 7.5 });
  anims.push((dt, t) => {
    floats.forEach(f => { f.m.position.y = f.base + Math.sin(t * 0.6 + f.phase) * 0.35; f.m.rotation.y += dt * 0.1; });
    emberMat.emissiveIntensity = 1.2 + Math.sin(t * 2.1) * 0.2;
  });
}

/* ══════════════════════════════════════════ VEILED SPIRE */
export function buildSpire(ctx) {
  const { group, colliders, anims } = ctx;
  const cx = 0, cz = -132;
  const baseY = heightAt(cx, cz);
  const g = new THREE.Group(); g.position.set(cx, baseY, cz); group.add(g);
  const dark = std('#1c1727', { roughness: 0.9, metalness: 0.15 });
  const dark2 = std('#251d33', { roughness: 0.85 });
  addCyl(g, { rt: 6.2, rb: 8.6, h: 16, seg: 10, y: 8, mat: dark });
  addCyl(g, { rt: 4.6, rb: 6.2, h: 18, seg: 9, y: 24, mat: dark2 });
  addCyl(g, { rt: 2.4, rb: 4.6, h: 20, seg: 8, y: 43, mat: dark });
  const spike = new THREE.Mesh(new THREE.ConeGeometry(2.8, 16, 8), dark2);
  spike.position.y = 61; g.add(spike);
  // rune bands
  const bands = [];
  for (let i = 0; i < 7; i++) {
    const y = 7 + i * 8.2;
    const r = i < 2 ? 8.4 - i * 0.4 : i < 4 ? 6.2 - (i - 2) * 0.55 : 4.4 - (i - 4) * 0.65;
    const band = new THREE.Mesh(new THREE.TorusGeometry(r, 0.09, 4, 44), new THREE.MeshBasicMaterial({ color: '#b06bff', transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending }));
    band.rotation.x = Math.PI / 2; band.position.y = y; g.add(band);
    bands.push(band);
    const bandGlow = addGlow(g, '#b06bff', 8, Math.cos(i) * r * 0.7, y, Math.sin(i) * r * 0.7, 0.12);
  }
  // buttresses
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU;
    const b = addBox(g, { w: 1.8, h: 13, d: 1.4, x: Math.cos(a) * 7.4, y: 6.5, z: Math.sin(a) * 7.4, ry: -a, mat: dark2 });
    b.rotation.z = 0.12;
  }
  // base platform + portal
  addCyl(g, { rt: 14, rb: 15, h: 0.9, seg: 24, y: 0.2, mat: std('#2a2335') });
  const sealRing = new THREE.Mesh(new THREE.RingGeometry(8, 9.5, 48), new THREE.MeshBasicMaterial({ map: runeRingTexture('#d65cff'), color: '#d65cff', transparent: true, opacity: 0.4, side: THREE.DoubleSide, depthWrite: false }));
  sealRing.rotation.x = -Math.PI / 2; sealRing.position.y = 0.75; g.add(sealRing);
  const portal = portalVisual('#d65cff', 3.2, 0.9);
  portal.group.position.set(0, 4.6, 10.2); g.add(portal.group);
  addPointLight(g, '#b06bff', 4, 40, 0, 6, 8);
  addGlow(g, '#b06bff', 26, 0, 8, 0, 0.12);
  // floating shards
  const shards = [];
  for (let i = 0; i < 10; i++) {
    const a = Math.random() * TAU, r = 10 + Math.random() * 12;
    const m = new THREE.Mesh(new THREE.OctahedronGeometry(0.5 + Math.random() * 1.4, 0), dark2);
    m.position.set(Math.cos(a) * r, 4 + Math.random() * 24, Math.sin(a) * r); m.rotation.set(Math.random() * 3, Math.random() * 3, 0); g.add(m);
    shards.push({ m, base: m.position.y, phase: Math.random() * TAU, spin: (Math.random() - 0.5) * 0.3 });
  }
  // dead trees at approach
  for (let i = 0; i < 5; i++) {
    const a = Math.random() * TAU;
    addCyl(g, { rt: 0.1, rb: 0.4, h: 5 + Math.random() * 5, seg: 5, x: Math.cos(a) * (18 + Math.random() * 6), y: 2.5, z: Math.sin(a) * (18 + Math.random() * 6), color: '#241d2b', mat: std('#241d2b') });
  }
  colliders.push({ x: cx, z: cz, r: 13 });
  anims.push((dt, t) => {
    portal.uniforms.time.value = t;
    sealRing.rotation.z = t * 0.05;
    bands.forEach((b, i) => { b.material.opacity = 0.35 + Math.sin(t * 1.2 + i) * 0.18; b.rotation.z = t * 0.03 * (i % 2 ? 1 : -1); });
    shards.forEach(s => { s.m.position.y = s.base + Math.sin(t * 0.5 + s.phase) * 0.6; s.m.rotation.y += dt * s.spin; });
  });
}

/* ══════════════════════════════════════════ DUELLING RING */
export function buildDuelRing(ctx) {
  const { group, colliders, anims } = ctx;
  const cx = -30, cz = 14;
  const baseY = heightAt(cx, cz);
  const g = new THREE.Group(); g.position.set(cx, baseY, cz); group.add(g);
  addCyl(g, { rt: 8.6, rb: 9.6, h: 0.7, seg: 32, y: 0.25, mat: std('#5a564e') });
  addCyl(g, { rt: 7.8, rb: 8.1, h: 0.25, seg: 32, y: 0.66, mat: std('#656159') });
  const runes = new THREE.Mesh(new THREE.CircleGeometry(7.7, 48), new THREE.MeshBasicMaterial({ map: runeRingTexture('#9fe7ff'), transparent: true, opacity: 0.5, depthWrite: false, side: THREE.DoubleSide }));
  runes.rotation.x = -Math.PI / 2; runes.position.y = 0.8; g.add(runes);
  const underGlow = addGlow(g, '#8fe7ff', 14, 0, 0.9, 0, 0.15);
  // pillars + flames
  const flames = [];
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + Math.PI / 4;
    const px = Math.cos(a) * 9.3, pz = Math.sin(a) * 9.3;
    addCyl(g, { r: 0.55, h: 3.2, seg: 8, x: px, y: 1.8, z: pz, mat: std('#59554d') });
    addBox(g, { w: 1.3, h: 0.35, d: 1.3, x: px, y: 3.4, z: pz, mat: std('#6a665d') });
    const f = emberFlame(g, px, 3.8, pz, '#8fe7ff', 1);
    flames.push(f);
    addGlow(g, '#9fe7ff', 2.6, px, 3.9, pz, 0.3);
  }
  // low ring wall segments
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    const wall = addBox(g, { w: 3.1, h: 0.45, d: 0.5, x: Math.cos(a) * 10.2, y: 0.75, z: Math.sin(a) * 10.2, ry: -a, mat: std('#4d4a43') });
  }
  // benches
  for (const [bx, bz, ry] of [[-14, 22, 0.5], [16, 8, -1.2], [-13, 4, 1.1]]) {
    const bench = new THREE.Group(); bench.position.set(bx, heightAt(cx + bx, cz + bz), bz); bench.rotation.y = ry; g.add(bench);
    addBox(bench, { w: 3.2, h: 0.18, d: 0.7, y: 0.55, mat: std('#5a4030') });
    for (const sx of [-1.3, 1.3]) addBox(bench, { w: 0.18, h: 0.55, d: 0.6, x: sx, y: 0.27, mat: std('#3f2c21') });
  }
  // banner pole
  addCyl(g, { r: 0.08, h: 6, seg: 5, x: 11.5, y: 3, z: -6, color: '#3b3027' });
  const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 3.4), new THREE.MeshStandardMaterial({ map: canvasTexture(256, 512, (c, w, h) => {
    c.fillStyle = '#3b2b5e'; c.fillRect(0, 0, w, h);
    c.fillStyle = '#e9c988'; c.font = '700 180px Georgia, serif'; c.textAlign = 'center'; c.fillText('⚔', w / 2, 280);
    c.strokeStyle = '#e9c988'; c.lineWidth = 8; c.strokeRect(10, 10, w - 20, h - 20);
  }), side: THREE.DoubleSide, roughness: 0.9 }));
  banner.position.set(11.5, 4.1, -6); g.add(banner);
  // sign
  const sign = textPlane('THE DUELLING RING', { font: '700 40px Cinzel, Georgia, serif' });
  sign.scale.set(4.0, 1.0, 1); sign.position.set(-13, heightAt(cx - 13, cz + 10) + 2.8, 10); sign.rotation.y = 0.7; group.add(sign);
  anims.push((dt, t) => {
    runes.material.opacity = 0.35 + Math.sin(t * 1.6) * 0.12;
    underGlow.material.opacity = 0.1 + Math.sin(t * 1.3) * 0.05;
    flames.forEach((f, i) => { f.light.intensity = 1.25 + Math.sin(t * 7 + i) * 0.25; });
  });
}

import * as THREE from 'three';
import { WOODS, CORES, MATERIALS, ZONES } from './data.js';
import { createWizard, getGlowTexture } from './character.js';
import {
  heightAt, canvasTexture, std, addBox, addCyl, addCone, addGlow, addPointLight,
  textPlane, groundTexture, mulberry32, TAU, clamp, lerp, smooth, pick, addTreeCluster
} from './worldkit.js';
import { buildVillage, buildAcademy, buildForest, buildLake } from './sites.js';
import { buildRuins, buildCaverns, buildCrag, buildSpire, buildDuelRing } from './sites2.js';

const itemInfo = id => {
  const w = WOODS.find(x => x.id === id); if (w) return { kind: 'woods', kindLabel: 'Wood', name: w.name, color: w.light, rarity: w.rarity };
  const c = CORES.find(x => x.id === id); if (c) return { kind: 'cores', kindLabel: 'Core', name: c.name, color: c.glow, rarity: c.rarity };
  const m = MATERIALS.find(x => x.id === id); if (m) return { kind: 'materials', kindLabel: 'Material', name: m.name, color: m.color, rarity: m.rarity };
  return { kind: 'materials', kindLabel: 'Reagent', name: id, color: '#ffffff', rarity: 'common' };
};

const RARITY_COLOR = { common: '#aaa69a', uncommon: '#8fd18a', rare: '#6fb8ff', epic: '#c395ff', legendary: '#ffc96b' };

export function makeSky(scene, opts = {}) {
  const skyGroup = new THREE.Group();
  scene.add(skyGroup);
  const skyUniforms = { time: { value: 0 } };
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false, uniforms: skyUniforms,
    vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec3 vDir; uniform float time;
      void main(){
        float h = clamp(vDir.y, -1.0, 1.0);
        vec3 bottom = vec3(0.055, 0.04, 0.10);
        vec3 horizon = vec3(0.30, 0.16, 0.30);
        vec3 mid = vec3(0.115, 0.075, 0.21);
        vec3 top = vec3(0.025, 0.02, 0.075);
        vec3 col = mix(horizon, mid, smoothstep(0.0, 0.28, h));
        col = mix(col, top, smoothstep(0.25, 0.8, h));
        col = mix(bottom, col, smoothstep(-0.35, 0.01, h));
        // warm glow low on the north-west horizon
        vec3 sunDir = normalize(vec3(-0.55, 0.08, -0.83));
        float d = max(dot(vDir, sunDir), 0.0);
        float sun = pow(d, 10.0);
        col += vec3(1.0, 0.48, 0.24) * sun * 0.42;
        col += vec3(1.0, 0.72, 0.45) * pow(d, 60.0) * 0.55;
        // soft cloud bands
        float band = sin(vDir.x * 6.0 + vDir.z * 4.0 + vDir.y * 9.0 + time * 0.015);
        col += vec3(0.15, 0.09, 0.19) * smoothstep(0.5, 1.0, band) * smoothstep(0.4, 0.8, h) * 0.15;
        gl_FragColor = vec4(col, 1.0);
      }`
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(420, 32, 24), skyMat);
  skyGroup.add(sky);

  // stars
  const starGeo = new THREE.BufferGeometry();
  const starN = 700, sp = new Float32Array(starN * 3), sc = new Float32Array(starN * 3);
  const rng = mulberry32(12345);
  for (let i = 0; i < starN; i++) {
    const a = rng() * TAU, h = Math.acos(1 - rng() * 0.85);
    const r = 350;
    sp[i * 3] = Math.sin(h) * Math.cos(a) * r * (0.5 + rng() * 0.5);
    sp[i * 3 + 1] = Math.cos(h) * r * 0.9 + 30;
    sp[i * 3 + 2] = Math.sin(h) * Math.sin(a) * r;
    const tint = rng();
    sc[i * 3] = 0.7 + tint * 0.3; sc[i * 3 + 1] = 0.72 + tint * 0.22; sc[i * 3 + 2] = 1;
  }
  starGeo.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  starGeo.setAttribute('color', new THREE.BufferAttribute(sc, 3));
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ size: 1.1, vertexColors: true, transparent: true, opacity: 0.85, depthWrite: false, fog: false, blending: THREE.AdditiveBlending, sizeAttenuation: true }));
  stars.frustumCulled = false;
  skyGroup.add(stars);

  // moon
  const moonGroup = new THREE.Group();
  moonGroup.position.set(-118, 96, -240);
  const moon = new THREE.Mesh(new THREE.SphereGeometry(15, 24, 18), new THREE.MeshBasicMaterial({ color: '#f4ecd8', fog: false }));
  moonGroup.add(moon);
  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: getGlowTexture(), color: '#cfd8ff', transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
  moonGlow.scale.set(90, 90, 1);
  moonGroup.add(moonGlow);
  const moonHalo = new THREE.Mesh(new THREE.RingGeometry(17, 30, 40), new THREE.MeshBasicMaterial({ color: '#c9d4ff', transparent: true, opacity: 0.06, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending, fog: false }));
  moonGroup.add(moonHalo);
  skyGroup.add(moonGroup);

  // aurora curtains
  const auroraGroup = new THREE.Group();
  const auroraMat = () => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, fog: false,
    uniforms: { time: { value: 0 } },
    vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader: `
      varying vec2 vUv; uniform float time;
      void main(){
        float edge = smoothstep(0.0, 0.25, vUv.y) * smoothstep(1.0, 0.55, vUv.y);
        float curtain = sin(vUv.x * 22.0 + time * 0.25) * 0.5 + 0.5;
        curtain *= sin(vUv.x * 9.0 - time * 0.16 + 1.7) * 0.35 + 0.65;
        float flow = sin(vUv.x * 4.0 + time * 0.1) * 0.5 + 0.5;
        vec3 col = mix(vec3(0.20,0.85,0.65), vec3(0.55,0.35,1.0), flow);
        col = mix(col, vec3(0.9,0.4,0.8), sin(vUv.x * 3.0 + 2.0) * 0.5 + 0.5);
        float alpha = edge * (0.10 + curtain * 0.30) * (0.5 + 0.5 * sin(vUv.y * 10.0 - time * 0.4));
        gl_FragColor = vec4(col, alpha);
      }`
  });
  const a1 = new THREE.Mesh(new THREE.PlaneGeometry(260, 52, 1, 1), auroraMat());
  a1.position.set(-30, 95, -260); a1.rotation.x = -0.18; auroraGroup.add(a1);
  const a2 = new THREE.Mesh(new THREE.PlaneGeometry(200, 38, 1, 1), auroraMat());
  a2.position.set(120, 110, -250); a2.rotation.set(-0.14, 0.5, 0.06); auroraGroup.add(a2);
  skyGroup.add(auroraGroup);

  // distant mountains
  const mountains = new THREE.Group();
  const mRng = mulberry32(880);
  const mountainMat = std('#1b1629', { roughness: 1 });
  for (let i = 0; i < 34; i++) {
    const a = (i / 34) * TAU + mRng() * 0.12;
    const r = 185 + mRng() * 55;
    const h = 22 + mRng() * 55;
    const m = new THREE.Mesh(new THREE.ConeGeometry(18 + mRng() * 22, h, 5), mountainMat);
    m.position.set(Math.cos(a) * r, h / 2 - 8, Math.sin(a) * r);
    m.rotation.y = mRng() * 3;
    mountains.add(m);
  }
  skyGroup.add(mountains);

  return {
    group: skyGroup,
    update(t) { skyUniforms.time.value = t; a1.material.uniforms.time.value = t; a2.material.uniforms.time.value = t; moonGroup.rotation.y = Math.sin(t * 0.02) * 0.02; stars.rotation.y = t * 0.003; }
  };
}

function makeWater() {
  const uniforms = { time: { value: 0 }, deep: { value: new THREE.Color('#0b2636') }, shallow: { value: new THREE.Color('#2c7a83') }, moon: { value: new THREE.Color('#cfe6ff') } };
  const mat = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, uniforms,
    vertexShader: `varying vec2 vUv; varying vec3 vPos; void main(){ vUv=uv; vPos=(modelMatrix*vec4(position,1.0)).xyz; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader: `
      varying vec2 vUv; varying vec3 vPos; uniform float time; uniform vec3 deep, shallow, moon;
      void main(){
        vec2 p = vUv - 0.5;
        float r = length(p) * 2.0;
        float wave = sin(p.x * 42.0 + time * 1.1) * sin(p.y * 36.0 - time * 0.8);
        float wave2 = sin((p.x + p.y) * 90.0 + time * 1.7) * 0.5;
        float ripple = wave * 0.5 + wave2 * 0.25;
        vec3 col = mix(deep, shallow, smoothstep(0.15, 0.95, r) * 0.55 + ripple * 0.08);
        float sparkle = pow(max(0.0, ripple), 12.0) * (1.0 - r) * 0.8;
        col += moon * sparkle;
        float shore = smoothstep(0.78, 1.0, r);
        col = mix(col, vec3(0.09,0.14,0.17), shore * 0.55);
        float alpha = 0.88 - shore * 0.15;
        gl_FragColor = vec4(col, alpha);
      }`
  });
  const mesh = new THREE.Mesh(new THREE.CircleGeometry(46, 64), mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(52, 0.05, 78);
  mesh.renderOrder = 2;
  return { mesh, uniforms };
}

function floatingIsland(x, y, z, scale, rng) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  const rockMat = std('#3a3348', { roughness: 1 });
  const base = new THREE.Mesh(new THREE.DodecahedronGeometry(5, 1), rockMat);
  base.scale.set(1.6, 2.1, 1.3);
  g.add(base);
  const top = new THREE.Mesh(new THREE.CylinderGeometry(7.4, 6.2, 0.9, 9), std('#3c5334', { roughness: 1 }));
  top.position.y = 4.6; g.add(top);
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(7.6, 7.5, 0.3, 9), std('#5b4d38'));
  rim.position.y = 4.1; g.add(rim);
  addTreeCluster(g, 0, 0, rng, { n: 3, spread: 4.5, scale: 0.8, conifer: true });
  addGlow(g, '#9fe7ff', 5, 0, 4.2, 0, 0.2);
  const fallTex = canvasTexture(64, 256, (c, w, h) => {
    const gr = c.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, 'rgba(170,235,255,.55)'); gr.addColorStop(0.7, 'rgba(140,210,255,.2)'); gr.addColorStop(1, 'rgba(140,210,255,0)');
    c.fillStyle = gr; c.fillRect(0, 0, w, h);
    for (let i = 0; i < 20; i++) { c.fillStyle = `rgba(220,245,255,${0.1 + Math.random() * 0.3})`; c.fillRect(Math.random() * w, Math.random() * h, 1 + Math.random() * 2, 8 + Math.random() * 30); }
  });
  const fall = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 14), new THREE.MeshBasicMaterial({ map: fallTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.7, side: THREE.DoubleSide }));
  fall.position.set(2.4, -4, 4.2); fall.rotation.x = 0.1; g.add(fall);
  const crystal = new THREE.Mesh(new THREE.OctahedronGeometry(1.1, 0), new THREE.MeshStandardMaterial({ color: '#8f7bff', emissive: '#6f4bff', emissiveIntensity: 1.1, roughness: 0.2 }));
  crystal.position.set(-3.2, 5.9, 1.5); crystal.scale.y = 2.2; g.add(crystal);
  g.scale.setScalar(scale);
  return { g, fall, baseY: y };
}

function createNodeVisual(itemId, kind) {
  const info = itemInfo(itemId);
  const g = new THREE.Group();
  const rarity = RARITY_COLOR[info.rarity] || '#e9c988';
  if (kind === 'woods') {
    addCyl(g, { rt: 0.38, rb: 0.55, h: 0.7, seg: 7, y: 0.35, mat: std('#4d3626', { roughness: 1 }) });
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU + 0.4;
      const br = addCyl(g, { rt: 0.06, rb: 0.12, h: 1.8, seg: 5, x: Math.cos(a) * 0.28, y: 0.95, z: Math.sin(a) * 0.28, mat: std('#5b4130') });
      br.rotation.z = Math.cos(a) * 0.55; br.rotation.x = Math.sin(a) * 0.55;
      const leaf = new THREE.Mesh(new THREE.IcosahedronGeometry(0.28, 0), std(info.color, { emissive: info.color, emissiveIntensity: 0.25, roughness: 0.9 }));
      leaf.position.set(Math.cos(a) * 0.85, 1.6, Math.sin(a) * 0.85); g.add(leaf);
    }
    const cut = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.04, 7), new THREE.MeshStandardMaterial({ color: info.color, emissive: info.color, emissiveIntensity: 0.3 }));
    cut.position.y = 0.72; g.add(cut);
  } else if (kind === 'cores') {
    const nest = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.16, 6, 14), std('#4b3b2b'));
    nest.rotation.x = Math.PI / 2; nest.position.y = 0.2; g.add(nest);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU;
      const twig = addCyl(g, { r: 0.03, h: 1.1, seg: 3, x: Math.cos(a) * 0.5, y: 0.18, z: Math.sin(a) * 0.5, mat: std('#5a4832') });
      twig.rotation.z = Math.cos(a) * 1.1; twig.rotation.x = Math.sin(a) * 1.1;
    }
    const feather = new THREE.Mesh(new THREE.ConeGeometry(0.18, 1.0, 5), new THREE.MeshStandardMaterial({ color: info.color, emissive: info.color, emissiveIntensity: 0.6, roughness: 0.4 }));
    feather.position.y = 0.85; feather.rotation.z = 0.3; g.add(feather);
  } else {
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU;
      const h = 0.5 + Math.random() * 1.2;
      const cr = new THREE.Mesh(new THREE.OctahedronGeometry(0.22 + Math.random() * 0.16, 0), new THREE.MeshStandardMaterial({ color: info.color, emissive: info.color, emissiveIntensity: 0.9, roughness: 0.15, metalness: 0.2 }));
      cr.position.set(Math.cos(a) * 0.3, h * 0.6, Math.sin(a) * 0.3); cr.scale.y = 2; g.add(cr);
    }
    addCyl(g, { rt: 0.25, rb: 0.45, h: 0.25, seg: 6, y: 0.1, mat: std('#4a4550') });
  }
  const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.16, 7, 6, 1, true), new THREE.MeshBasicMaterial({ color: rarity, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
  beam.position.y = 3.8; g.add(beam);
  const halo = addGlow(g, info.color, 2.4, 0, 0.7, 0, 0.32);
  const ring = new THREE.Mesh(new THREE.RingGeometry(0.65, 1.0, 26), new THREE.MeshBasicMaterial({ color: rarity, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false }));
  ring.rotation.x = -Math.PI / 2; ring.position.y = 0.05; g.add(ring);
  return {g, beam, halo, ring, color: info.color};
}

export function createWorld(scene) {
  const rng = mulberry32(50505);
  const group = new THREE.Group();
  scene.add(group);
  const colliders = [];
  const anims = [];
  const ctx = { scene, group, colliders, anims, smokeSources: [] };

  scene.fog = new THREE.FogExp2('#2a2240', 0.0062);
  scene.background = new THREE.Color('#0b0716');

  // lights
  const hemi = new THREE.HemisphereLight('#9a8ad4', '#202422', 0.95);
  scene.add(hemi);
  const moonLight = new THREE.DirectionalLight('#ffd7ae', 2.1);
  moonLight.position.set(-70, 95, 40);
  moonLight.castShadow = true;
  moonLight.shadow.mapSize.set(2048, 2048);
  moonLight.shadow.camera.near = 10; moonLight.shadow.camera.far = 260;
  moonLight.shadow.camera.left = -75; moonLight.shadow.camera.right = 75;
  moonLight.shadow.camera.top = 75; moonLight.shadow.camera.bottom = -75;
  moonLight.shadow.bias = -0.0008;
  moonLight.shadow.normalBias = 0.03;
  scene.add(moonLight);
  scene.add(moonLight.target);
  moonLight.target.position.set(0, 0, 20);
  const fill = new THREE.DirectionalLight('#7a6bd8', 0.55);
  fill.position.set(70, 40, -80);
  scene.add(fill);
  const ambient = new THREE.AmbientLight('#4a3d68', 0.35);
  scene.add(ambient);

  const sky = makeSky(scene);
  const water = makeWater();
  group.add(water.mesh);

  // terrain
  const geo = new THREE.PlaneGeometry(300, 300, 128, 128);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    pos.setY(i, heightAt(x, z));
  }
  geo.computeVertexNormals();
  const ground = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ map: groundTexture(), roughness: 0.98, metalness: 0 }));
  ground.receiveShadow = true;
  group.add(ground);

  // underwater floor tint
  const deep = new THREE.Mesh(new THREE.CircleGeometry(45, 32), new THREE.MeshBasicMaterial({ color: '#12232c', transparent: true, opacity: 0.75 }));
  deep.rotation.x = -Math.PI / 2; deep.position.set(52, -4.5, 78); group.add(deep);
  const foam = new THREE.Mesh(new THREE.RingGeometry(45.2, 47.5, 64), new THREE.MeshBasicMaterial({ color: '#b9e6e8', transparent: true, opacity: 0.07, side: THREE.DoubleSide, depthWrite: false }));
  foam.rotation.x = -Math.PI / 2; foam.position.set(52, 0.12, 78); group.add(foam);

  // tree instancing
  const treeRng = mulberry32(4242);
  const treePositions = [];
  const zonesForTrees = [
    { x: 52, z: -36, r: 48, density: 0.95 }, { x: -64, z: -44, r: 46, density: 0.35 },
    { x: 0, z: 46, r: 40, density: 0.25 }, { x: -78, z: 82, r: 42, density: 0.3 },
    { x: 112, z: -88, r: 44, density: 0.35 }, { x: 104, z: 66, r: 36, density: 0.2 },
    { x: 0, z: -132, r: 40, density: 0.25 }
  ];
  for (let i = 0; i < 420; i++) {
    const zone = zonesForTrees[Math.floor(treeRng() * zonesForTrees.length)];
    const a = treeRng() * TAU, r = Math.sqrt(treeRng()) * zone.r;
    const x = zone.x + Math.cos(a) * r, z = zone.z + Math.sin(a) * r;
    if (Math.hypot(x - 52, z - 78) < 40 && treeRng() > 0.25) continue;
    if (Math.hypot(x - 0, z - 46) < 16) continue;
    if (Math.hypot(x + 64, z + 44) < 18) continue;
    if (Math.hypot(x - 52, z + 36) < 10) continue;
    if (treeRng() > zone.density) continue;
    if (heightAt(x, z) < -0.8) continue;
    treePositions.push({ x, z, s: 0.65 + treeRng() * 0.9, rot: treeRng() * TAU, conifer: treeRng() > 0.52, tint: treeRng() });
  }
  const trunkGeo = new THREE.CylinderGeometry(0.16, 0.3, 4.2, 5);
  const trunkMat = std('#4a3428', { roughness: 1 });
  const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, treePositions.length);
  const leafGeo = new THREE.IcosahedronGeometry(1.65, 0);
  const leafMat = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 1, flatShading: true, vertexColors: false });
  const leaves = new THREE.InstancedMesh(leafGeo, leafMat, treePositions.length * 2);
  const coneGeo = new THREE.ConeGeometry(1.55, 3.4, 7);
  const cones = new THREE.InstancedMesh(coneGeo, leafMat, treePositions.length);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3(), pv = new THREE.Vector3();
  const dummy = new THREE.Object3D();
  const leafColors = ['#2b4429', '#33502f', '#3b5a34', '#263d28', '#44603a', '#314b33'];
  let li = 0, ci = 0;
  treePositions.forEach((t, i) => {
    const y = heightAt(t.x, t.z);
    dummy.position.set(t.x, y + 2.1 * t.s, t.z);
    dummy.rotation.set(0, t.rot, 0);
    dummy.scale.setScalar(t.s);
    dummy.updateMatrix();
    trunks.setMatrixAt(i, dummy.matrix);
    if (t.conifer) {
      dummy.position.set(t.x, y + 4.4 * t.s, t.z);
      dummy.rotation.set(0, t.rot, 0);
      dummy.scale.set(t.s * 1.0, t.s * 1.3, t.s);
      dummy.updateMatrix();
      cones.setMatrixAt(ci, dummy.matrix);
      cones.setColorAt(ci, new THREE.Color(leafColors[(i + 1) % leafColors.length]));
      ci++;
    }
    dummy.position.set(t.x, y + 4.6 * t.s, t.z);
    dummy.rotation.set(t.rot * 0.2, t.rot, 0);
    dummy.scale.set(t.s * (0.9 + t.tint * 0.35), t.s * (0.8 + t.tint * 0.25), t.s * (0.9 + t.tint * 0.3));
    dummy.updateMatrix();
    leaves.setMatrixAt(li, dummy.matrix);
    leaves.setColorAt(li, new THREE.Color(pick(leafColors)));
    li++;
    dummy.position.set(t.x + 0.8 * t.s, y + 3.8 * t.s, t.z - 0.5 * t.s);
    dummy.scale.set(t.s * 0.62, t.s * 0.55, t.s * 0.62);
    dummy.updateMatrix();
    leaves.setMatrixAt(li, dummy.matrix);
    leaves.setColorAt(li, new THREE.Color(pick(leafColors)));
    li++;
  });
  leaves.count = li; cones.count = ci;
  trunks.castShadow = false; leaves.castShadow = false; cones.castShadow = false;
  trunks.receiveShadow = true;
  group.add(trunks, leaves, cones);

  // rocks
  const rockGeo = new THREE.DodecahedronGeometry(1, 0);
  const rocks = new THREE.InstancedMesh(rockGeo, std('#4b4b54', { roughness: 1 }), 60);
  for (let i = 0; i < 60; i++) {
    const a = rng() * TAU, r = 15 + rng() * 120;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const y = heightAt(x, z);
    dummy.position.set(x, y + 0.2, z);
    dummy.rotation.set(rng() * 3, rng() * 3, rng() * 3);
    dummy.scale.set(0.4 + rng() * 1.5, 0.3 + rng() * 0.9, 0.4 + rng() * 1.4);
    dummy.updateMatrix();
    rocks.setMatrixAt(i, dummy.matrix);
  }
  rocks.castShadow = false; rocks.receiveShadow = true; group.add(rocks);

  // site builds
  buildVillage(ctx);
  buildAcademy(ctx);
  buildForest(ctx);
  buildLake(ctx);
  buildRuins(ctx);
  buildCaverns(ctx);
  buildCrag(ctx);
  buildSpire(ctx);
  buildDuelRing(ctx);

  // stone paths
  const pathCurves = [
    [[0, 42], [-16, 30], [-34, 18], [-53, -6], [-62, -26]],
    [[0, 42], [18, 34], [32, 18], [42, -2], [50, -22], [52, -32]],
    [[0, 42], [22, 50], [36, 60], [46, 68]],
    [[0, 42], [-22, 54], [-44, 64], [-62, 74], [-74, 80]],
    [[0, 42], [30, 46], [58, 52], [86, 60], [100, 65]],
    [[100, 65], [108, 40], [110, 5], [110, -40], [112, -80]],
    [[0, 42], [4, 12], [2, -25], [0, -65], [0, -108]],
    [[-16, 30], [2, 27], [18, 25]]
  ];
  const stoneGeo = new THREE.CylinderGeometry(1.1, 1.25, 0.1, 7);
  const stoneMat = std('#67635a', { roughness: 0.95 });
  const pathPoints = [];
  for (const pts of pathCurves) {
    const curve = new THREE.CatmullRomCurve3(pts.map(([x, z]) => new THREE.Vector3(x, 0, z)));
    for (let i = 0; i < 60; i++) {
      const p = curve.getPoint(i / 60);
      if (heightAt(p.x, p.z) < 0.2) continue;
      if (Math.hypot(p.x, p.z - 46) < 13) continue;
      if (Math.hypot(p.x + 64, p.z + 44) < 17) continue;
      pathPoints.push({ x: p.x + (rng() - 0.5) * 0.7, z: p.z + (rng() - 0.5) * 0.7, r: rng() * TAU, s: 0.5 + rng() * 0.5 });
    }
  }
  const pathStones = new THREE.InstancedMesh(stoneGeo, stoneMat, pathPoints.length);
  pathPoints.forEach((p, i) => {
    dummy.position.set(p.x, heightAt(p.x, p.z) + 0.06, p.z);
    dummy.rotation.set(0, p.r, 0);
    dummy.scale.set(p.s, 1, p.s * (0.8 + rng() * 0.5));
    dummy.updateMatrix();
    pathStones.setMatrixAt(i, dummy.matrix);
  });
  pathStones.receiveShadow = true; group.add(pathStones);

  // floating islands
  const islands = [
    floatingIsland(-120, 48, -110, 1.25, mulberry32(17)),
    floatingIsland(135, 38, -120, 1.0, mulberry32(33)),
    floatingIsland(120, 58, 20, 0.8, mulberry32(51))
  ];
  for (const isl of islands) group.add(isl.g);

  // ── gathering nodes
  const nodeSpecs = [
    { x: -9, z: 55, item: 'oak' }, { x: 6, z: 38, item: 'oak' }, { x: -21, z: 39, item: 'willow' },
    { x: 18, z: 55, item: 'unicorn' }, { x: -17, z: 64, item: 'willow' }, { x: 7, z: 62, item: 'moonstone' },
    { x: 42, z: -20, item: 'holly' }, { x: 35, z: -44, item: 'moonwillow' }, { x: 66, z: -26, item: 'moonwillow' },
    { x: 58, z: -52, item: 'thestral' }, { x: 28, z: -30, item: 'unicorn' }, { x: 70, z: -14, item: 'hawthorn' },
    { x: 45, z: -60, item: 'coral' }, { x: 75, z: -40, item: 'augurey' }, { x: 39, z: -55, item: 'thunderbird' },
    { x: 38, z: 66, item: 'coral' }, { x: 64, z: 70, item: 'pearl' }, { x: 48, z: 58, item: 'willow' },
    { x: -46, z: -22, item: 'silverlime' }, { x: -72, z: -20, item: 'phoenix' }, { x: -86, z: -32, item: 'runeetch' },
    { x: -54, z: 68, item: 'ebony' }, { x: -84, z: 74, item: 'thestral' }, { x: -70, z: 96, item: 'basilisk' },
    { x: -92, z: 88, item: 'runeetch' }, { x: -66, z: 90, item: 'augurey' },
    { x: 94, z: 56, item: 'starfall' }, { x: 112, z: 52, item: 'frostpine' }, { x: 118, z: 74, item: 'starlight' },
    { x: 96, z: 78, item: 'thunderbird' }, { x: 108, z: 82, item: 'voidsalt' },
    { x: 102, z: -70, item: 'sunwood' }, { x: 120, z: -78, item: 'dragon' }, { x: 88, z: -82, item: 'emberresin' },
    { x: 108, z: -104, item: 'phoenix' }, { x: 124, z: -96, item: 'stariron' }, { x: 98, z: -96, item: 'chimaera' },
    { x: 132, z: -70, item: 'emberoak' }, { x: 10, z: -116, item: 'voidbriar' }, { x: -12, z: -120, item: 'wraithglass' },
    { x: 14, z: -140, item: 'starlight' }, { x: -8, z: -148, item: 'voidsalt' }, { x: 2, z: -104, item: 'frostpine' }
  ];
  const nodes = [];
  const nodeGroup = new THREE.Group(); group.add(nodeGroup);
  nodeSpecs.forEach((spec, i) => {
    const info = itemInfo(spec.item);
    const y = heightAt(spec.x, spec.z);
    if (y < -1.5) return;
    const vis = createNodeVisual(spec.item, info.kind);
    vis.g.position.set(spec.x, y + 0.05, spec.z);
    vis.g.rotation.y = rng() * TAU;
    nodeGroup.add(vis.g);
    const node = {
      id: `node-${i}`, x: spec.x, z: spec.z, y: y + 0.05, item: spec.item, kind: info.kind,
      label: `Gather ${info.name}`, info, mesh: vis.g, beam: vis.beam, halo: vis.halo, ring: vis.ring,
      active: true, respawnAt: 0, phase: rng() * TAU, radius: 3.0
    };
    nodes.push(node);
  });

  // ── NPCs
  const npcs = [];
  const npcSpecs = [
    { id: 'orin', name: 'Master Orin Vale', sub: 'Wandmaker of Emberfall', x: -4, z: 33.5, robe: '#5b4430', accent: '#c9a25f', hair: '#cfc4b0', face: 0.2, hat: true },
    { id: 'mira', name: 'Mira Fen', sub: 'Village Elder', x: 6, z: 43.5, robe: '#3d4d5f', accent: '#7fb3c9', hair: '#9a8b7a', face: -1.2, hat: false },
    { id: 'reed', name: 'Professor Cassian Reed', sub: 'Charms & Combat', x: -56, z: -25, robe: '#34405e', accent: '#c9b37d', hair: '#2a2020', face: 1.9, hat: true },
    { id: 'sable', name: 'Duel Captain Sable', sub: 'Master of the Ring', x: -21, z: 17.5, robe: '#4a2f38', accent: '#c98d7a', hair: '#1e1818', face: -2.3, hat: false },
    { id: 'keeper', name: 'The Keeper', sub: 'Black Archive', x: -79, z: -31, robe: '#241d33', accent: '#a06bff', hair: '#d8d2c8', face: 0.7, hat: true }
