/* ═══════════════════════════════════════════════════════════
   WANDLORE · SOUND
   Tiny procedural WebAudio score — no assets, no loading.
   ═══════════════════════════════════════════════════════════ */

export class Audio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.ambient = null;
    this.ambientGain = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.5 : 0;
    this.master.connect(this.ctx.destination);
    this.startAmbient();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.setTargetAtTime(on ? 0.5 : 0, this.ctx.currentTime, 0.1);
  }

  startAmbient() {
    if (!this.ctx || this.ambient) return;
    const ctx = this.ctx;
    const gain = ctx.createGain();
    gain.gain.value = 0.0;
    gain.connect(this.master);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 520;
    filter.Q.value = 0.7;
    filter.connect(gain);
    // slow drifting pad
    const freqs = [110, 164.81, 220, 261.63, 329.63];
    const oscs = freqs.map((f, i) => {
      const osc = ctx.createOscillator();
      osc.type = i % 2 ? 'sine' : 'triangle';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.value = 0.02 + (i === 0 ? 0.02 : 0);
      osc.connect(g); g.connect(filter);
      osc.start();
      return { osc, g, base: f };
    });
    // breathy noise
    const len = ctx.sampleRate * 4;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * 0.35;
    const noise = ctx.createBufferSource();
    noise.buffer = buf; noise.loop = true;
    const nGain = ctx.createGain(); nGain.gain.value = 0.012;
    const nFilter = ctx.createBiquadFilter(); nFilter.type = 'bandpass'; nFilter.frequency.value = 900; nFilter.Q.value = 0.6;
    noise.connect(nFilter); nFilter.connect(nGain); nGain.connect(gain);
    noise.start();
    gain.gain.setTargetAtTime(0.5, ctx.currentTime, 4);
    this.ambient = { oscs, noise, gain };
    this.ambientGain = gain;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.055;
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 140;
    lfo.connect(lfoGain); lfoGain.connect(filter.frequency);
    lfo.start();
  }

  tone({ freq = 440, type = 'sine', dur = 0.3, vol = 0.2, slide = 0, delay = 0, filter = 0, q = 1, pan = 0 }) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + Math.min(0.04, dur * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = filter; f.Q.value = q;
      node.connect(f); node = f;
    }
    if (pan && ctx.createStereoPanner) {
      const p = ctx.createStereoPanner(); p.pan.value = pan;
      node.connect(p); p.connect(g);
    } else node.connect(g);
    g.connect(this.master);
    osc.start(t0); osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.3, vol = 0.2, freq = 1200, delay = 0, type = 'bandpass', q = 0.8, slide = 0 }) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const len = Math.floor(ctx.sampleRate * dur);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = ctx.createBufferSource(); src.buffer = buf;
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t0); f.Q.value = q;
    if (slide) f.frequency.exponentialRampToValueAtTime(Math.max(60, freq + slide), t0 + dur);
    const g = ctx.createGain(); g.gain.value = vol;
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t0); src.stop(t0 + dur);
  }

  cast(cat = 'offense') {
    const table = {
      offense: { f: 620, t: 'triangle', s: -260, d: 0.32, v: 0.16, n: 2400 },
      defense: { f: 320, t: 'sine', s: 180, d: 0.6, v: 0.13, n: 900 },
      healing: { f: 520, t: 'sine', s: 240, d: 0.7, v: 0.11, n: 1600 },
      elemental: { f: 480, t: 'sawtooth', s: -180, d: 0.42, v: 0.1, n: 2800 },
      transformation: { f: 380, t: 'triangle', s: 320, d: 0.5, v: 0.13, n: 1800 },
      forbidden: { f: 180, t: 'sawtooth', s: -90, d: 0.7, v: 0.14, n: 700 }
    };
    const c = table[cat] || table.offense;
    this.tone({ freq: c.f, type: c.t, dur: c.d, vol: c.v, slide: c.s });
    this.noise({ dur: c.d * 0.7, vol: c.v * 0.4, freq: c.n, slide: -c.n * 0.4 });
  }

  hit() {
    this.noise({ dur: 0.18, vol: 0.24, freq: 280, type: 'lowpass', q: 1.4, slide: -180 });
    this.tone({ freq: 140, type: 'square', dur: 0.12, vol: 0.1, slide: -70 });
  }

  shield() {
    this.tone({ freq: 280, type: 'sine', dur: 0.6, vol: 0.14, slide: 140 });
    this.tone({ freq: 560, type: 'sine', dur: 0.5, vol: 0.07, slide: 210, delay: 0.04 });
  }

  heal() {
    [523, 659, 784].forEach((f, i) => this.tone({ freq: f, type: 'sine', dur: 0.5, vol: 0.08, delay: i * 0.08 }));
  }

  gather() {
    [660, 990].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.25, vol: 0.09, delay: i * 0.07 }));
  }

  ui() { this.tone({ freq: 880, type: 'sine', dur: 0.07, vol: 0.05 }); }

  error() { this.tone({ freq: 190, type: 'square', dur: 0.16, vol: 0.08, slide: -50 }); }

  levelup() {
    [392, 523, 659, 784, 1046].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.5, vol: 0.1, delay: i * 0.09 }));
    this.tone({ freq: 130, type: 'sine', dur: 1.4, vol: 0.1, delay: 0.1 });
  }

  victory() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.7, vol: 0.11, delay: i * 0.12 }));
  }

  defeat() {
    [392, 330, 262, 196].forEach((f, i) => this.tone({ freq: f, type: 'sine', dur: 0.8, vol: 0.1, delay: i * 0.16 }));
  }

  duelStart() {
    for (let i = 0; i < 3; i++) this.tone({ freq: 300 - i * 40, type: 'sine', dur: 0.2, vol: 0.16, delay: i * 0.45 });
    this.tone({ freq: 440, type: 'triangle', dur: 0.8, vol: 0.14, delay: 1.35 });
    this.noise({ dur: 0.7, vol: 0.12, freq: 1600, delay: 1.35 });
  }

  step() { this.noise({ dur: 0.06, vol: 0.03, freq: 380, type: 'lowpass' }); }
}

/* ═══════════════════════════════════════════════════════════
   WANDLORE · PANELS
   Every book in the grimoire, rendered from state.
   ═══════════════════════════════════════════════════════════ */
import {
  WOODS, CORES, MATERIALS, RECIPES, SPELLS, LESSON_TRACKS, QUESTS,
  ACHIEVEMENTS, UPGRADES, MARKET, ENEMIES, TOURNAMENTS, ZONES, CUSTOMERS, CATEGORIES, RARITIES, LORE
} from './data.js';
import { computeWand, wandSVG, saleEvaluation, categoryPower, BENCH, materialById } from './crafting.js';

export const PANELS = [
  { id: 'craft', kicker: "THE WANDMAKER'S BENCH", title: 'Wandcrafting', rune: '⚒', label: 'Craft' },
  { id: 'spells', kicker: 'THE GRIMOIRE', title: 'Spells & Lessons', rune: '✦', label: 'Spells' },
  { id: 'shop', kicker: 'THE SHOP LEDGER', title: 'The Wand Shop', rune: '◉', label: 'Shop' },
  { id: 'journal', kicker: 'THE JOURNAL', title: 'Journal', rune: '❖', label: 'Journal' },
  { id: 'map', kicker: 'THE ATLAS', title: 'The Atlas', rune: '◈', label: 'Atlas' },
  { id: 'character', kicker: 'THE WIZARD', title: 'Character', rune: '☾', label: 'Character' },
  { id: 'duel', kicker: 'THE DUELLING RING', title: 'Duels & Tournaments', rune: '⚔', label: 'Duel' }
];

const q = (n) => Math.round(n);
const esc = (s = '') => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const rarTag = r => `<span class="rar-tag" style="--rar:${RARITIES[r]?.color}">${RARITIES[r]?.name || r}</span>`;
const fmt = n => n >= 10000 ? `${(n / 1000).toFixed(1)}k` : n >= 1000 ? `${(n / 1000).toFixed(2)}k` : String(n);

function statBar(label, value, color) {
  return `<div class="stat"><span>${label}</span><div class="stat-bar"><div style="width:${Math.min(100, value)}%;--sc:${color}"></div></div><b>${value}</b></div>`;
}

function previewWand(ui) {
  const s = ui.game.s;
  const d = ui.craft;
  if (!d.woodId || !d.coreId) return null;
  return computeWand({ woodId: d.woodId, coreId: d.coreId, length: d.length, flexibility: d.flexibility, materials: d.materials, bench: s.upgrades.bench });
}

function wandReadout(wand) {
  if (!wand) return `<div class="wand-placeholder"><span>✦</span>Select a wood and a core to see what wants to be made.</div>`;
  const wood = WOODS.find(w => w.id === wand.woodId);
  const core = CORES.find(c => c.id === wand.coreId);
  return `
    <div class="wand-readout">
      <span class="wand-name">${esc(wand.name)}</span>
      <span class="wand-sub">${esc(wood?.name || '')} · ${esc(core?.name || '')} · ${wand.length}″ · ${wand.flexibility}% flex</span>
    </div>
    <div class="affinity-row">
      ${wand.affinity.slice(0, 3).map(([cat, v]) => `<span class="affinity-chip">${CATEGORIES[cat].rune} ${CATEGORIES[cat].name} +${q(v)}</span>`).join('')}
      ${wand.affinity.filter(([, v]) => v < 0).slice(0, 1).map(([cat, v]) => `<span class="affinity-chip neg">${CATEGORIES[cat].name} ${q(v)}</span>`).join('')}
    </div>
    <div class="stat-grid">
      ${statBar('Potency', wand.stats.pot, '#ff9d6b')}
      ${statBar('Control', wand.stats.ctrl, '#78b4ff')}
      ${statBar('Harmony', wand.stats.harm, '#8ef0b0')}
      ${statBar('Aether', wand.stats.aether, '#c79bff')}
    </div>
    <div class="wand-trait"><b>${esc(wand.trait.name)}</b>${esc(wand.trait.desc)}</div>
    <div class="affinity-row">
      <span class="affinity-chip" style="--gold">${rarTag(wand.rarity)}</span>
      <span class="affinity-chip">Quality ${wand.quality}</span>
      <span class="affinity-chip">Value ◉ ${fmt(wand.value)}</span>
      ${wand.recipe ? `<span class="affinity-chip" style="border-color:#ffc96b">✦ Legendary combination</span>` : ''}
    </div>`;
}

/* ── CRAFT ─────────────────────────────────────────────────── */
export function renderCraft(ui) {
  const s = ui.game.s;
  const d = ui.craft;
  const inv = s.inventory;
  const preview = previewWand(ui);
  const kind = d.tab;
  const items = kind === 'woods' ? WOODS : kind === 'cores' ? CORES : MATERIALS;
  const owned = kind === 'woods' ? inv.woods : kind === 'cores' ? inv.cores : inv.materials;
  const bench = BENCH[s.upgrades.bench];

  const cards = items.map(item => {
    const qty = owned?.[item.id] || 0;
    const selected = kind === 'woods' ? d.woodId === item.id : kind === 'cores' ? d.coreId === item.id : d.materials.includes(item.id);
    const act = kind === 'woods' ? 'select-wood' : kind === 'cores' ? 'select-core' : 'toggle-mat';
    return `<button class="ing-card ${selected ? 'selected' : ''} ${qty ? '' : 'empty'} rar-${item.rarity}" data-act="${act}" data-id="${item.id}" ${qty ? '' : 'disabled'}>
      <span class="ing-orb ${kind === 'woods' ? 'wood' : kind === 'cores' ? 'core' : 'mat'}" style="--swatch:${item.light || item.glow || item.color}"></span>
      <span class="ing-info">
        <span class="ing-name">${esc(item.name)}</span>
        <span class="ing-meta">${kind === 'materials' ? esc(item.desc.slice(0, 30)) + '…' : esc(item.desc.slice(0, 34)) + '…'}</span>
        ${rarTag(item.rarity)}
      </span>
      <span class="ing-qty">×${qty}</span>
    </button>`;
  }).join('');

  const matSlots = Array.from({ length: bench.slots }).map((_, i) => {
    const id = d.materials[i];
    if (id) {
      const m = materialById(id);
      return `<button class="mat-slot filled" data-act="remove-mat" data-id="${id}">${esc(m?.name || id)}<br><span style="opacity:.5">remove</span></button>`;
    }
    return `<div class="mat-slot">Empty slot</div>`;
  }).join('');

  const lockedSlots = s.upgrades.bench < 4 ? `<div class="mat-slot locked">Bench II+</div>` : '';

  return `
  <div class="craft-layout">
    <div class="craft-left">
      <div class="ing-section-head">
        <h3>Materials</h3>
        <small>${WOODS.length + CORES.length + MATERIALS.length} known to the trade</small>
      </div>
      <div class="ing-tabs">
        <button class="ing-tab ${kind === 'woods' ? 'active' : ''}" data-act="ing-tab" data-id="woods">Woods</button>
        <button class="ing-tab ${kind === 'cores' ? 'active' : ''}" data-act="ing-tab" data-id="cores">Cores</button>
        <button class="ing-tab ${kind === 'materials' ? 'active' : ''}" data-act="ing-tab" data-id="materials">Extra materials</button>
      </div>
      <div class="ing-grid">${cards || '<div class="empty-state">Nothing here yet.</div>'}</div>

      <div class="discovery-strip">
        <div class="ing-section-head">
          <h3>Legendary combinations</h3>
          <small>${s.discovered.recipes.length} / ${RECIPES.length} discovered</small>
        </div>
        <div class="discovery-grid">
          ${RECIPES.slice(0, 8).map(r => {
            const found = s.discovered.recipes.includes(r.name);
            return `<div class="disc ${found ? 'found' : ''}"><span>${found ? '✦' : '?'}</span><small>${found ? esc(r.name) : 'Undiscovered'}</small></div>`;
          }).join('')}
        </div>
      </div>
    </div>

    <div class="craft-right">
      <div class="wand-stage ${preview ? 'wand-idle' : ''}">
        <span class="stage-tag">The bench · ${esc(bench.name)}</span>
        ${preview ? `<span class="stage-rarity" style="--rar:${RARITIES[preview.rarity].color}">${RARITIES[preview.rarity].name}</span>` : ''}
        ${preview ? wandSVG(preview) : `<div class="wand-placeholder"><span>⚒</span>Nothing on the bench yet.</div>`}
      </div>

      ${wandReadout(preview)}

      <div class="slider-row">
        <div class="slider-head"><span>Length</span><b>${d.length}″</b></div>
        <input type="range" id="craft-length" min="9" max="15" step="0.5" value="${d.length}" />
      </div>
      <div class="slider-row">
        <div class="slider-head"><span>Flexibility</span><b>${d.flexibility}%</b></div>
        <input type="range" id="craft-flex" min="0" max="100" step="1" value="${d.flexibility}" />
      </div>

      <div class="ing-section-head" style="margin-top:12px"><h3>Finishings</h3><small>${d.materials.length}/${bench.slots} slots</small></div>
      <div class="mat-slots">${matSlots}${lockedSlots}</div>

      <div class="craft-actions">
        <button class="btn-gold" data-act="craft" ${preview ? '' : 'disabled'}>Shape the wand</button>
        <button class="btn-line" data-act="craft-clear">Clear bench</button>
        <div class="craft-hint">Consumes 1 wood, 1 core${d.materials.length ? ', ' + d.materials.length + ' finishing(s)' : ''}.</div>
      </div>
    </div>
  </div>`;
}

export function updateCraftPreview(ui) {
  const preview = previewWand(ui);
  const stage = document.querySelector('.wand-stage');
  if (stage) {
    stage.classList.toggle('wand-idle', !!preview);
    stage.querySelector('svg')?.remove();
    stage.querySelector('.wand-placeholder')?.remove();
    const rar = stage.querySelector('.stage-rarity');
    rar?.remove();
    if (preview) {
      stage.insertAdjacentHTML('beforeend', `<span class="stage-rarity" style="--rar:${RARITIES[preview.rarity].color}">${RARITIES[preview.rarity].name}</span>` + wandSVG(preview));
    } else {
      stage.insertAdjacentHTML('beforeend', `<div class="wand-placeholder"><span>⚒</span>Nothing on the bench yet.</div>`);
    }
  }
  const readout = document.querySelector('.craft-right');
  if (readout) {
    // replace everything from readout block through mat-slots with fresh markup
    const old = readout.querySelector('.wand-readout');
    const anchor = old || readout.querySelector('.wand-placeholder');
    if (anchor) {
      const wrap = document.createElement('div');
      wrap.innerHTML = wandReadout(preview);
      if (old) old.replaceWith(...wrap.childNodes);
    }
  }
  const craftBtn = document.querySelector('[data-act="craft"]');
  if (craftBtn) craftBtn.disabled = !preview;
}

/* ── SPELLS ────────────────────────────────────────────────── */
export function renderSpells(ui) {
  const s = ui.game.s;
  const cat = ui.spellCat;
  const known = s.known;
  const filtered = SPELLS.filter(sp => cat === 'all' || sp.cat === cat);

  const cards = filtered.map(sp => {
    const isKnown = known[sp.id] !== undefined;
    const mastery = known[sp.id] || 0;
    const rank = ui.game.masteryRank(sp.id);
    const equipped = s.loadout.includes(sp.id);
    return `<button class="spell-card ${isKnown ? '' : 'locked'}" data-act="${isKnown ? 'toggle-loadout' : 'spell-info'}" data-id="${sp.id}" style="--sc:${CATEGORIES[sp.cat].color}">
      <span class="sc-icon">${sp.rune}</span>
      <span class="sc-body">
        <span class="sc-name">${esc(sp.name)} ${equipped ? '<span style="color:var(--teal);font-size:7px">◆</span>' : ''}</span>
        <span class="sc-cat">${CATEGORIES[sp.cat].name} · ${isKnown ? rank.name : 'Unknown'}</span>
        <span class="sc-desc">${esc(sp.desc)}</span>
        ${isKnown ? `<span class="sc-mastery"><div style="width:${mastery}%"></div></span>` : ''}
      </span>
      ${isKnown ? '' : `<span class="lock-tag">LOCKED</span>`}
    </button>`;
  }).join('');

  const cats = `<button class="cat-chip ${cat === 'all' ? 'active' : ''}" data-act="spell-cat" data-id="all"><span class="dot" style="--cc:#e9c988"></span>All</button>` +
    Object.values(CATEGORIES).map(c => `<button class="cat-chip ${cat === c.id ? 'active' : ''}" data-act="spell-cat" data-id="${c.id}"><span class="dot" style="--cc:${c.color}"></span>${c.name}</button>`).join('');

  const tracks = LESSON_TRACKS.map(track => {
    const lessons = track.lessons.map(l => {
      const done = !!s.lessons[l.id];
      const locked = !done && l.req && ((l.req.level && s.level < l.req.level) || (l.req.rep && s.rep < l.req.rep));
      const req = l.req ? [l.req.level ? `Lv ${l.req.level}` : '', l.req.rep ? `Rep ${l.req.rep}` : ''].filter(Boolean).join(' · ') : '';
      return `<div class="lesson-item ${done ? 'done' : ''}">
        <span class="lesson-num">${done ? '✓' : ''}</span>
        <span class="li-body">
          <span class="li-name">${esc(l.name)}</span>
          <span class="li-sub">${done ? 'Mastered' : locked ? 'Requires ' + req : esc(l.desc)}</span>
        </span>
        <button data-act="attend-lesson" data-id="${l.id}" ${done || locked ? 'disabled' : ''}>${done ? 'Done' : 'Attend'}</button>
      </div>`;
    }).join('');
    const knownCount = track.lessons.filter(l => s.lessons[l.id]).length;
    return `<div style="margin-bottom:16px">
      <div class="ing-section-head"><h3>${esc(track.name)}</h3><small>${knownCount}/${track.lessons.length}</small></div>
      <p style="font-size:11px;font-style:italic;color:rgba(205,189,158,.5);margin:0 0 4px;line-height:1.4">${esc(track.teacher)} — ${esc(track.desc)}</p>
      ${lessons}
    </div>`;
  }).join('');

  return `
  <div class="spell-layout">
    <div>
      <div class="ing-section-head"><h3>Your grimoire</h3><small>${Object.keys(known).length} of ${SPELLS.length} spells · click a known spell to ready it</small></div>
      <div class="spell-cats">${cats}</div>
      <div class="spell-grid">${cards}</div>
    </div>
    <aside class="lesson-side">
      <h3>Lessons at the Academy</h3>
      <p>Attend a lesson to learn its spell. The old teachers do not hand these out for free — but they do hand them out.</p>
      ${tracks}
    </aside>
  </div>`;
}

/* ── SHOP ──────────────────────────────────────────────────── */
export function renderShop(ui) {
  const s = ui.game.s;
  const tab = ui.shopTab;
  const customers = s.customers.map(c => {
    const info = ui.game.getCustomerInfo(c);
    if (!info) return '';
    const active = ui.shopCustomer === c.id;
    return `<button class="npc-card ${active ? 'active' : ''}" data-act="select-customer" data-id="${c.id}">
      <span class="npc-face" style="--npc:${info.color}">${info.initials}</span>
      <span class="npc-info">
        <span class="npc-name">${esc(info.name)}</span>
        <span class="npc-desc">${esc(info.line)}</span>
        <span class="npc-wants">
          <span class="want-chip" style="color:${CATEGORIES[c.wants.cat].color}">${CATEGORIES[c.wants.cat].rune} ${CATEGORIES[c.wants.cat].name}</span>
          <span class="want-chip">${esc(c.wants.trait)}</span>
        </span>
      </span>
      <span class="npc-budget">◉ ${c.budget[0]}–${c.budget[1]}</span>
    </button>`;
  }).join('');

  const customer = s.customers.find(c => c.id === ui.shopCustomer) || s.customers[0];
  const cinfo = customer ? ui.game.getCustomerInfo(customer) : null;
  const wands = s.wands.map(w => {
    const ev = customer ? saleEvaluation(customer, w, s.upgrades.advert ? 0.1 : 0) : null;
    const equipped = w.id === s.equipped;
    return `<button class="offer-wand ${equipped ? 'equipped' : ''} rar-${w.rarity}" data-act="sell-wand" data-id="${w.id}" ${equipped ? 'disabled' : ''}>
      <span class="ow-icon" style="--rar:${RARITIES[w.rarity].color}">⌁</span>
      <span class="ow-info">
        <span class="ow-name">${esc(w.name)} ${equipped ? '<span style="color:var(--teal);font-size:7px">EQUIPPED</span>' : ''}</span>
        <span class="ow-sub">${RARITIES[w.rarity].name} · Q${w.quality} · ${ev ? ev.mood : ''}${ev?.tagMatch ? ' · perfect match' : ''}</span>
      </span>
      <span class="ow-val">◉ ${ev ? ev.price : w.value}</span>
    </button>`;
  }).join('');

  const upgrades = UPGRADES.map(u => {
    const owned = u.id.startsWith('bench') ? s.upgrades.bench >= u.tier : !!s.upgrades[u.id];
    const available = u.id.startsWith('bench') ? s.upgrades.bench + 1 === u.tier : true;
    return `<div class="upgrade-card ${owned ? 'owned' : ''}">
      <span class="upg-icon">${u.icon}</span>
      <span class="upg-info"><b>${esc(u.name)}</b><small>${esc(u.desc)}</small></span>
      <button class="buy-btn" data-act="buy-upgrade" data-id="${u.id}" ${owned || !available ? 'disabled' : ''}>${owned ? 'Owned' : '◉ ' + fmt(u.cost)}</button>
    </div>`;
  }).join('');

  const market = MARKET.map(m => {
    const item = m.kind === 'wood' ? WOODS.find(w => w.id === m.id) : m.kind === 'core' ? CORES.find(c => c.id === m.id) : MATERIALS.find(x => x.id === m.id);
    if (!item) return '';
    return `<div class="market-item">
      <span class="ing-orb ${m.kind === 'wood' ? 'wood' : m.kind === 'core' ? 'core' : 'mat'}" style="--swatch:${item.light || item.glow || item.color}"></span>
      <b>${esc(item.name)} <span style="opacity:.5">×${m.qty}</span></b>
      <button class="buy-btn" data-act="buy-market" data-id="${m.id}" ${s.gold < m.price ? 'disabled' : ''}>◉ ${fmt(m.price)}</button>
    </div>`;
  }).join('');

  const tabs = `<div class="panel-tabs">
    <button class="panel-tab ${tab === 'customers' ? 'active' : ''}" data-act="shop-tab" data-id="customers">Customers & offers</button>
    <button class="panel-tab ${tab === 'upgrades' ? 'active' : ''}" data-act="shop-tab" data-id="upgrades">Workbench & shop</button>
    <button class="panel-tab ${tab === 'market' ? 'active' : ''}" data-act="shop-tab" data-id="market">Reagents market</button>
  </div>`;

  let right = '';
  if (tab === 'customers') {
    right = `<div class="ing-section-head"><h3>Wands on the shelf</h3><small>${cinfo ? 'Offering to ' + esc(cinfo.name) : 'No customer selected'}</small></div>
      <div class="offer-list">${wands || '<div class="empty-state">No wands to sell.</div>'}</div>
      <p style="font-size:11px;font-style:italic;color:rgba(205,189,158,.45);margin-top:12px;line-height:1.5">
        ${cinfo ? esc(cinfo.line) : ''}<br><span style="opacity:.7">A wand whose magic matches their need will fetch a far better price — and a better mood.</span>
      </p>`;
  } else if (tab === 'upgrades') {
    right = `<div class="ing-section-head"><h3>The workshop</h3><small>Invest in better work</small></div>${upgrades}`;
  } else {
    right = `<div class="ing-section-head"><h3>The market</h3><small>Rare stock, bought honestly (mostly)</small></div>
      <div class="market-grid">${market}</div>`;
  }

  return `<div class="shop-layout">
    <div>
      <div class="ing-section-head"><h3>In the shop today</h3><small>${s.customers.length} customers</small></div>
      ${customers}
      <div style="margin-top:14px;padding:12px;border:1px solid var(--line-soft);background:rgba(233,201,136,.03)">
        <div class="ing-section-head"><h3>Sales ledger</h3><small>${s.stats.wandsSold} wands sold</small></div>
        <div style="font-size:11.5px;font-style:italic;color:rgba(205,189,158,.6);line-height:1.6">
          Reputation ${s.rep} · ${s.upgrades.advert ? 'Lantern sign lit (+25% budgets)' : 'No signboard yet'}<br>
          ${s.upgrades.shelf ? 'Display shelf draws wanderers (+35 ◉ per duel)' : 'A bare shelf draws no one'}
        </div>
      </div>
    </div>
    <div>${tabs}${right}</div>
  </div>`;
}

/* ── JOURNAL ───────────────────────────────────────────────── */
export function renderJournal(ui) {
  const s = ui.game.s;
  const quests = QUESTS.map(quest => {
    const st = s.quests[quest.id] || { progress: 0, done: false };
    const active = ui.game.activeQuest()?.id === quest.id;
    const pct = Math.min(100, (st.progress / quest.target) * 100);
    return `<div class="quest-card ${active ? 'active' : ''} ${st.done ? 'done' : ''}">
      <span class="quest-rune">${st.done ? '✓' : quest.type === 'duel' || quest.type === 'enemy' ? '⚔' : '❖'}</span>
      <div class="quest-body">
        <div class="quest-name">${esc(quest.name)}</div>
        <div class="quest-desc">${esc(quest.desc)}</div>
        <div class="quest-obj ${st.done ? 'done' : ''}">${esc(quest.objective)} ${st.done ? '' : `(${st.progress}/${quest.target})`}
          <span class="quest-reward">◉ ${quest.rewards.gold} · ✧ ${quest.rewards.rep} · ✦ ${quest.rewards.xp}</span>
        </div>
        <div class="quest-progress"><div style="width:${pct}%"></div></div>
      </div>
    </div>`;
  }).join('');

  const achv = ACHIEVEMENTS.map(a => `<div class="achv ${s.achievements.includes(a.id) ? 'unlocked' : ''}">
    <span>${a.icon}</span><div><b>${esc(a.name)}</b><small>${esc(a.desc)}</small></div>
  </div>`).join('');

  const stats = s.stats;
  const lore = LORE[Math.floor(Date.now() / 20000) % LORE.length];

  return `
  <div class="quest-list" style="margin-bottom:18px">${quests}</div>
  <div class="ing-section-head"><h3>Field notes</h3><small>Collected along the way</small></div>
  <div class="achievement-grid" style="margin-bottom:16px">${achv}</div>
  <div class="ing-section-head"><h3>The ledger</h3><small>Everything the shop remembers</small></div>
  <div class="char-stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">
    <div class="char-stat"><span>Wands crafted</span><b>${stats.wandsCrafted}</b></div>
    <div class="char-stat"><span>Wands sold</span><b>${stats.wandsSold}</b></div>
    <div class="char-stat"><span>Duels won</span><b>${stats.duelsWon}</b></div>
    <div class="char-stat"><span>Duels lost</span><b>${stats.duelsLost}</b></div>
    <div class="char-stat"><span>Tournaments</span><b>${stats.tournaments}</b></div>
    <div class="char-stat"><span>Ingredients</span><b>${stats.ingredients}</b></div>
    <div class="char-stat"><span>Spells cast</span><b>${stats.spellsCast || 0}</b></div>
    <div class="char-stat"><span>Galleons earned</span><b>${fmt(stats.goldEarned || 0)}</b></div>
  </div>
  <div class="wand-trait"><b>A page from the shop diary</b>${esc(lore)}</div>
  <div class="affinity-row">${s.badges.map(b => `<span class="affinity-chip">♛ ${esc(b)}</span>`).join('')}</div>`;
}

/* ── ATLAS ─────────────────────────────────────────────────── */
export function renderAtlas(ui) {
  const s = ui.game.s;
  const project = (x, z) => ({ px: 260 + x * 1.55, py: 210 - z * 1.35 });
  const here = ui.playerZone || 'village';
  const paths = [
    [[0, 42], [-34, 18], [-62, -26]], [[0, 42], [30, 18], [50, -22]],
    [[0, 42], [36, 60], [46, 68]], [[0, 42], [-44, 64], [-62, 74]],
    [[0, 42], [58, 52], [100, 65]], [[100, 65], [110, 5], [112, -80]], [[0, 42], [0, -108]]
  ];
  const svg = `<svg viewBox="0 0 520 420" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <radialGradient id="atlasGlow"><stop offset="0" stop-color="#2a3350"/><stop offset="1" stop-color="#0a0a16"/></radialGradient>
      <pattern id="atlasGrid" width="26" height="26" patternUnits="userSpaceOnUse"><path d="M 26 0 L 0 0 0 26" fill="none" stroke="rgba(233,201,136,.06)" stroke-width="1"/></pattern>
    </defs>
    <rect width="520" height="420" fill="url(#atlasGlow)"/>
    <rect width="520" height="420" fill="url(#atlasGrid)"/>
    <ellipse cx="300" cy="320" rx="120" ry="92" fill="rgba(30,80,90,.18)"/>
    ${paths.map(p => `<path d="M ${p.map(([x, z]) => { const { px, py } = project(x, z); return `${px} ${py}`; }).join(' L ')}" fill="none" stroke="rgba(233,201,136,.22)" stroke-width="2" stroke-dasharray="3 5"/>`).join('')}
    ${ZONES.map(z => {
      const { px, py } = project(z.x, z.z);
      const discovered = s.discoveredZones.includes(z.id);
      const locked = s.rep < z.req;
      const isHere = here === z.id;
      return `<g opacity="${discovered ? (locked ? .55 : 1) : .3}">
        <circle cx="${px}" cy="${py}" r="${isHere ? 15 : 11}" fill="${locked ? '#1b1826' : z.color}" opacity=".13"/>
        <circle cx="${px}" cy="${py}" r="${isHere ? 7 : 4.5}" fill="${locked ? '#3a3547' : z.color}"/>
        ${isHere ? `<circle cx="${px}" cy="${py}" r="15" fill="none" stroke="${z.color}" stroke-width="1" stroke-dasharray="2 4"/>` : ''}
        <text x="${px}" y="${py - 14}" text-anchor="middle" font-family="Georgia, serif" font-size="13" fill="${z.color}">${z.rune}</text>
        <text x="${px}" y="${py + 24}" text-anchor="middle" font-family="Georgia, serif" font-size="10" letter-spacing="1.2" fill="${discovered ? 'rgba(241,228,200,.78)' : 'rgba(241,228,200,.3)'}">${z.name.toUpperCase()}</text>
      </g>`;
    }).join('')}
    <text x="260" y="402" text-anchor="middle" font-family="Georgia, serif" font-size="9" letter-spacing="3" fill="rgba(233,201,136,.32)">THE VALE OF EMBERFALL · ${s.rep} REPUTATION</text>
  </svg>`;

  const zones = ZONES.map(z => {
    const locked = s.rep < z.req;
    const discovered = s.discoveredZones.includes(z.id);
    return `<div class="zone-card ${locked ? 'locked' : ''} ${here === z.id ? 'here' : ''}">
      <span class="zone-rune" style="color:${z.color}">${z.rune}</span>
      <span class="zone-info">
        <span class="zone-name">${esc(z.name)}</span>
        <span class="zone-sub">${esc(z.sub)}${locked ? ` · needs ${z.req} reputation` : ''}</span>
      </span>
      <button class="zone-travel" data-act="travel" data-id="${z.id}" ${locked || here === z.id || !discovered ? 'disabled' : ''}>${here === z.id ? 'Here' : locked ? 'Sealed' : 'Travel'}</button>
    </div>`;
  }).join('');

  const disc = ui.game.discoveredWandStats();
  return `<div class="atlas-layout">
    <div class="atlas-map">${svg}</div>
    <div class="atlas-side">
      ${zones}
      <div class="ing-section-head" style="margin-top:10px"><h3>Field discoveries</h3></div>
      <div class="char-stats" style="grid-template-columns:1fr 1fr">
        <div class="char-stat"><span>Woods</span><b>${disc.woods}/${disc.woodsTotal}</b></div>
        <div class="char-stat"><span>Cores</span><b>${disc.cores}/${disc.coresTotal}</b></div>
        <div class="char-stat"><span>Combinations</span><b>${disc.recipes}/${disc.recipesTotal}</b></div>
        <div class="char-stat"><span>Spells</span><b>${disc.spells}/${disc.spellsTotal}</b></div>
      </div>
    </div>
  </div>`;
}

/* ── CHARACTER ─────────────────────────────────────────────── */
export function renderCharacter(ui) {
  const s = ui.game.s;
  const wand = ui.game.wand;
  const wood = WOODS.find(w => w.id === wand.woodId);
  const core = CORES.find(c => c.id === wand.coreId);
  const xpMax = ui.game.xpToNext();
  const initials = s.name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase();
  return `<div class="char-layout">
    <div class="char-hero">
      <div class="char-sigil">${initials}</div>
      <h3>${esc(s.name)}</h3>
      <div class="char-title">${esc(ui.game.displayTitle())} · Level ${s.level}</div>
      <div class="char-levelbar"><div style="width:${(s.xp / xpMax) * 100}%"></div></div>
      <div style="font-family:var(--display);font-size:7px;letter-spacing:.14em;color:rgba(233,201,136,.55)">${s.xp} / ${xpMax} XP</div>
      <div class="char-stats">
        <div class="char-stat"><span>Health</span><b>${ui.game.maxHp()}</b></div>
        <div class="char-stat"><span>Mana</span><b>${ui.game.maxMp()}</b></div>
        <div class="char-stat"><span>Reputation</span><b>${s.rep}</b></div>
        <div class="char-stat"><span>Galleons</span><b>${fmt(s.gold)}</b></div>
      </div>
      <div style="margin-top:14px" class="affinity-row">${s.badges.map(b => `<span class="affinity-chip">♛ ${esc(b)}</span>`).join('') || '<span class="affinity-chip" style="opacity:.5">No titles yet</span>'}</div>
    </div>
    <div>
      <div class="ing-section-head"><h3>Equipped wand</h3><small>${WANDS_COUNT(s)} wands in the collection</small></div>
      <div class="equipped-wand">
        <span class="ew-art">${wandSVG(wand, { scale: 0.7 })}</span>
        <div>
          <h4>${esc(wand.name)}</h4>
          <p>${esc(wood?.name || '')} · ${esc(core?.name || '')} · ${wand.length}″ · ${RARITIES[wand.rarity].name}</p>
          <div class="affinity-row" style="margin:6px 0 0">
            <span class="affinity-chip">P ${wand.stats.pot}</span>
            <span class="affinity-chip">C ${wand.stats.ctrl}</span>
            <span class="affinity-chip">H ${wand.stats.harm}</span>
            <span class="affinity-chip">A ${wand.stats.aether}</span>
          </div>
        </div>
      </div>
      <div class="wand-trait"><b>${esc(wand.trait.name)}</b>${esc(wand.trait.desc)}</div>
      <div class="ing-section-head"><h3>Collection</h3><small>Click to equip</small></div>
      <div class="offer-list" style="max-height:270px">
        ${s.wands.map(w => `<button class="offer-wand ${w.id === s.equipped ? 'equipped' : ''}" data-act="equip-wand" data-id="${w.id}">
          <span class="ow-icon" style="--rar:${RARITIES[w.rarity].color}">⌁</span>
          <span class="ow-info"><span class="ow-name">${esc(w.name)}</span><span class="ow-sub">${RARITIES[w.rarity].name} · Q${w.quality} · ${esc(w.trait.name)}</span></span>
          <span class="ow-val">${w.id === s.equipped ? 'WIELDING' : 'Equip'}</span>
        </button>`).join('')}
      </div>
    </div>
  </div>`;
}
const WANDS_COUNT = s => s.wands.length;

/* ── DUELS ─────────────────────────────────────────────────── */
export function renderDuelPanel(ui) {
  const s = ui.game.s;
  const cards = ENEMIES.map(e => {
    const locked = s.rep < e.reqRep;
    const wins = s.defeated[e.id] || 0;
    return `<div class="quest-card ${locked ? 'done' : ''}">
      <span class="quest-rune" style="color:${e.accent}">${e.boss ? '☾' : '⚔'}</span>
      <div class="quest-body">
        <div class="quest-name">${esc(e.name)} <span style="color:var(--gold-dim);font-size:8px">· ${e.title}</span> ${wins ? `<span style="color:var(--teal);font-size:8px">×${wins}</span>` : ''}</div>
        <div class="quest-desc">${esc(e.desc)}</div>
        <div class="quest-obj">Level ${e.level} · ${e.hp} HP · ${e.dmg ? e.dmg + ' ATK' : 'harmless'}
          <span class="quest-reward">◉ ${e.rewards.gold} · ✧ ${e.rewards.rep} · ✦ ${e.rewards.xp}</span>
        </div>
      </div>
      <button class="buy-btn" data-act="start-duel" data-id="${e.id}" ${locked ? 'disabled' : ''}>${locked ? '◈ ' + e.reqRep + ' rep' : e.boss ? 'Challenge' : 'Duel'}</button>
    </div>`;
  }).join('');

  const tours = TOURNAMENTS.map(t => {
    const locked = s.rep < t.reqRep;
    return `<div class="upgrade-card ${locked ? 'owned' : ''}">
      <span class="upg-icon">♛</span>
      <span class="upg-info"><b>${esc(t.name)}</b><small>${esc(t.desc)} · ${t.rounds.length} rounds · ${t.reqRep} reputation required</small></span>
      <button class="buy-btn" data-act="start-tournament" data-id="${t.id}" ${locked ? 'disabled' : ''}>${locked ? 'Sealed' : 'Enter'}</button>
    </div>`;
  }).join('');

  return `<div style="display:grid;grid-template-columns:1fr 320px;gap:22px">
    <div>
      <div class="ing-section-head"><h3>The duelling slate</h3><small>${s.stats.duelsWon} wins · ${s.stats.duelsLost} losses</small></div>
      <div class="quest-list">${cards}</div>
    </div>
    <aside>
      <div class="ing-section-head"><h3>Tournaments</h3><small>Rankings & rewards</small></div>
      ${tours}
      <div class="wand-trait" style="margin-top:14px"><b>Duel Captain Sable</b>“Shield early, dodge late, and never cast the same spell twice in a row. They will notice.”</div>
      <div style="font-size:11px;font-style:italic;color:rgba(205,189,158,.5);line-height:1.7;margin-top:10px">
        Controls in the ring:<br>
        <b style="color:var(--gold-dim)">WASD</b> move · <b style="color:var(--gold-dim)">Space</b> dodge<br>
        <b style="color:var(--gold-dim)">1–6</b> cast · <b style="color:var(--gold-dim)">Right mouse</b> shield<br>
        <b style="color:var(--gold-dim)">Left mouse</b> current spell
      </div>
    </aside>
  </div>`;
}

export function renderPanel(ui, name) {
  switch (name) {
    case 'craft': return renderCraft(ui);
    case 'spells': return renderSpells(ui);
    case 'shop': return renderShop(ui);
    case 'journal': return renderJournal(ui);
    case 'map': return renderAtlas(ui);
    case 'character': return renderCharacter(ui);
    case 'duel': return renderDuelPanel(ui);
    default: return '<div class="empty-state">Nothing here.</div>';
  }
}

/* ═══════════════════════════════════════════════════════════
   WANDLORE · INTERFACE
   ═══════════════════════════════════════════════════════════ */
import {
  SPELLS, LESSON_TRACKS, CATEGORIES, WOODS, CORES, RARITIES,
  ENEMIES, TOURNAMENTS, ZONES, DIALOGUE, QUESTS
} from './data.js';
import { saleEvaluation, customerReaction, wandSVG, computeWand, BENCH } from './crafting.js';
import { renderPanel, PANELS, updateCraftPreview } from './panels.js';

const $ = id => document.getElementById(id);
const el = (tag, cls, html) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (html !== undefined) n.innerHTML = html;
  return n;
};
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const RUNES = ['ᚦ', 'ᛉ', 'ᛟ', 'ᚱ', 'ᛏ', 'ᛒ', 'ᛗ', 'ᛊ', 'ᛖ', 'ᛞ'];
const shuffle = a => a.map(v => [Math.random(), v]).sort((x, y) => x[0] - y[0]).map(x => x[1]);

export class Ui {
  constructor(game, audio) {
    this.game = game;
    this.audio = audio;
    this.actions = {};
    this.panel = null;
    this.panelTab = 'craft';
    this.craft = { tab: 'woods', woodId: null, coreId: null, materials: [], length: 12, flexibility: 50 };
    this.spellCat = 'all';
    this.shopTab = 'customers';
    this.shopCustomer = null;
    this.modalOpen = false;
    this.dialogueOpen = false;
    this.challengeCleanup = null;
    this.locationName = 'Emberfall Village';
    this.playerZone = 'village';
    this.playerPos = { x: 0, z: 0 };
    this.cameraYaw = 0;
    this.spellSlots = [];
    this.cds = {};
    this.combo = 0;
    this.cache();
    this.bind();
    this.buildNav();
  }

  cache() {
    this.dom = {
      loading: $('loading'), title: $('title-screen'), hud: $('hud'),
      overlay: $('overlay'), nav: $('grimoire-nav'), body: $('panel-body'),
      kicker: $('panel-kicker'), title2: $('panel-title'),
      modal: $('modal'), modalCard: $('modal-card'),
      dialogue: $('dialogue'), dlgPortrait: $('dlg-portrait'), dlgName: $('dlg-name'),
      dlgText: $('dlg-text'), dlgChoices: $('dlg-choices'),
      toasts: $('toasts'), objective: $('objective-toast'),
      spellbar: $('spellbar'), castOrb: $('cast-orb'),
      interact: $('interact-prompt'), interactText: $('interact-text'),
      combat: $('combat-ui'), enemyName: $('enemy-name'), enemyRank: $('enemy-rank'),
      enemyHp: $('enemy-hp-fill'), enemyHpText: $('enemy-hp-text'),
      enemyCast: $('enemy-cast'), duelRound: $('duel-round'), comboEl: $('combo'),
      combatLog: $('combat-log'), crosshair: $('crosshair'),
      minimap: $('minimap'), minimapLabel: $('minimap-label'),
      questTitle: $('qt-title'), questObjective: $('qt-objective'), questBar: $('qt-bar'),
      questCount: $('quest-count'), location: $('location-name'), clock: $('clock'),
      hpFill: $('hp-fill'), hpText: $('hp-text'), mpFill: $('mp-fill'), mpText: $('mp-text'),
      xpFill: $('xp-fill'), xpLabel: $('xp-label'), playerName: $('player-name'),
      playerTitle: $('player-title'), playerLevel: $('player-level'), initials: $('player-initials'),
      gold: $('res-gold'), rep: $('res-rep'), rank: $('res-rank'), wands: $('res-wands'),
      panelGold: $('panel-gold'), panelRep: $('panel-rep'),
      damage: $('damage-layer'), spellBanner: $('spell-banner'), bannerName: $('spell-banner-name'),
      bannerRune: $('spell-banner-rune'), levelFlash: $('level-flash'), lfLevel: $('lf-level'),
      lfTitle: $('lf-title'), fade: $('fade'), autosave: $('autosave'),
      compass: $('compass-track'), sound: $('btn-sound'), panelGoldEl: $('panel-gold')
    };
    this.minimapCtx = this.dom.minimap?.getContext('2d');
  }

  bind() {
    this.dom.nav.addEventListener('click', e => {
      const b = e.target.closest('[data-panel]');
      if (!b) return;
      this.actions.sfx?.('ui');
      this.openPanel(b.dataset.panel);
    });
    this.dom.body.addEventListener('click', e => {
      const btn = e.target.closest('[data-act]');
      if (!btn || btn.disabled) return;
      this.onAction(btn.dataset.act, btn.dataset.id, btn);
    });
    this.dom.body.addEventListener('input', e => {
      if (e.target.id === 'craft-length') { this.craft.length = Number(e.target.value); e.target.closest('.slider-row').querySelector('b').textContent = `${this.craft.length}″`; updateCraftPreview(this); }
      if (e.target.id === 'craft-flex') { this.craft.flexibility = Number(e.target.value); e.target.closest('.slider-row').querySelector('b').textContent = `${this.craft.flexibility}%`; updateCraftPreview(this); }
    });
    $('btn-close-panel').addEventListener('click', () => this.closePanel());
    this.dom.overlay.querySelector('.overlay-backdrop').addEventListener('click', () => this.closePanel());
    $('btn-map').addEventListener('click', () => this.openPanel('map'));
    $('player-card').addEventListener('click', () => this.openPanel('character'));
    this.dom.modal.querySelector('.modal-backdrop').addEventListener('click', () => {
      if (!this.modalLocked) this.closeModal();
    });
    this.dom.dialogue.addEventListener('click', e => {
      if (e.target.closest('.dlg-close')) this.closeDialogue();
      const choice = e.target.closest('[data-choice]');
      if (choice) {
        const idx = Number(choice.dataset.choice);
        const fn = this.dialogueChoices?.[idx]?.action;
        this.audio.ui();
        fn?.();
      }
    });
  }

  buildNav() {
    this.dom.nav.innerHTML = `<div class="nav-brand">WANDLORE<b>THE GRIMOIRE</b></div>` +
      PANELS.map(p => `<button class="nav-btn" data-panel="${p.id}"><span>${p.rune}</span>${p.label}</button>`).join('') +
      `<div class="nav-foot"><b>${this.game.s.name}</b><br>${this.game.displayTitle()}<br><br>Emberfall · The Vale</div>`;
  }

  /* ── HUD ─────────────────────────────────────────────────── */
  refresh() {
    const g = this.game, s = g.s;
    if (!s) return;
    const initials = s.name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase();
    this.dom.initials.textContent = initials;
    this.dom.playerName.textContent = s.name;
    this.dom.playerTitle.textContent = g.displayTitle();
    this.dom.playerLevel.textContent = s.level;
    this.dom.gold.textContent = s.gold.toLocaleString();
    this.dom.rep.textContent = s.rep;
    this.dom.wands.textContent = s.wands.length;
    this.dom.rank.textContent = s.badges.includes('Silver Circle Champion') ? 'Silver Circle' : s.stats.duelsWon >= 3 ? 'Contender' : 'Unranked';
    this.dom.panelGold.textContent = s.gold.toLocaleString();
    this.dom.panelRep.textContent = s.rep;
    const xpMax = g.xpToNext();
    this.dom.xpFill.style.width = `${clamp((s.xp / xpMax) * 100, 0, 100)}%`;
    this.dom.xpLabel.textContent = `${s.xp} / ${xpMax} XP`;
    this.dom.minimapLabel.textContent = this.locationName.split(' ').slice(0, 2).join(' ');
    // quest
    const active = g.activeQuest();
    const activeCount = QUESTS.filter(q => { const st = g.s.quests[q.id]; return st && !st.done; }).length;
    this.dom.questCount.textContent = activeCount;
    if (active) {
      const st = g.questState(active);
      this.dom.questTitle.textContent = active.name;
      this.dom.questObjective.textContent = `${active.objective}${active.target > 1 ? ` · ${st.progress}/${active.target}` : ''}`;
      this.dom.questBar.style.width = `${clamp((st.progress / active.target) * 100, 0, 100)}%`;
    } else {
      this.dom.questTitle.textContent = 'All quests complete';
      this.dom.questObjective.textContent = 'The Vale is quieter. For now.';
      this.dom.questBar.style.width = '100%';
    }
    this.dom.location.textContent = this.locationName;
    this.dom.clock.textContent = this.clockLabel();
    this.updateSpellbar();
    this.updateMeters();
    if (this.panel) this.renderPanel();
    this.buildNavName();
  }

  buildNavName() {
    const foot = this.dom.nav.querySelector('.nav-foot');
    if (foot) foot.innerHTML = `<b>${this.game.s.name}</b><br>${this.game.displayTitle()}<br><br>Emberfall · The Vale`;
  }

  clockLabel() {
    const t = (this.game.s.playTime || 0) % 720;
    if (t < 180) return 'Dusk';
    if (t < 360) return 'Night';
    if (t < 540) return 'Deep Night';
    return 'Before Dawn';
  }

  setLocation(name, zoneId) {
    this.locationName = name;
    if (zoneId) this.playerZone = zoneId;
    this.dom.location.textContent = name;
    this.dom.minimapLabel.textContent = name.split(' ').slice(0, 2).join(' ');
  }

  updateMeters() {
    const s = this.game.s;
    const hp = this.combatHp ?? s.hp ?? this.game.maxHp();
    const mp = this.combatMp ?? s.mp ?? this.game.maxMp();
    const hpMax = this.game.maxHp();
    const mpMax = this.game.maxMp();
    this.dom.hpFill.style.width = `${clamp((hp / hpMax) * 100, 0, 100)}%`;
    this.dom.hpText.textContent = Math.max(0, Math.round(hp));
    this.dom.mpFill.style.width = `${clamp((mp / mpMax) * 100, 0, 100)}%`;
    this.dom.mpText.textContent = Math.max(0, Math.round(mp));
  }

  updateSpellbar() {
    const s = this.game.s;
    if (!this.dom.spellbar) return;
    const slots = s.loadout.map(id => SPELLS.find(x => x.id === id)).filter(Boolean);
    if (!this.spellSlots.length || this._barKey !== s.loadout.join(',')) {
      this._barKey = s.loadout.join(',');
      this.dom.spellbar.innerHTML = '';
      this.spellSlots = Array.from({ length: 6 }).map((_, i) => {
        const sp = slots[i];
        const b = el('button', 'spell-slot' + (sp ? '' : ' locked'));
        b.dataset.index = i;
        if (sp) {
          b.style.setProperty('--sc', CATEGORIES[sp.cat].color);
          b.innerHTML = `<span class="slot-key">${i + 1}</span><span class="slot-rune">${sp.rune}</span><span class="slot-name">${sp.name}</span><span class="slot-cost">${sp.mana}</span><span class="slot-cd"></span>`;
          b.title = `${sp.name} — ${sp.mana} MP · ${CATEGORIES[sp.cat].name}`;
          b.addEventListener('click', () => this.actions.cast?.(i));
        } else {
          b.innerHTML = `<span class="slot-key">${i + 1}</span><span class="slot-rune" style="opacity:.25">·</span><span class="slot-name">Empty</span>`;
        }
        this.dom.spellbar.appendChild(b);
        return { btn: b, cd: b.querySelector('.slot-cd') };
      });
    } else {
      // swap icons if loadout changed content but same key impossible; keep
    }
    this.spellSlots.forEach((slot, i) => {
      const sp = slots[i];
      if (!sp) return;
      const cd = this.cds[sp.id] || 0;
      if (slot.cd) slot.cd.style.transform = `scaleY(${clamp(cd, 0, 1)})`;
      slot.btn.classList.toggle('active', this.activeSpell === sp.id);
    });
    // cast orb icon
    const cur = SPELLS.find(x => x.id === s.loadout[this.activeIndex || 0]);
    if (cur) {
      $('cast-orb-icon').textContent = cur.rune;
      $('cast-orb-icon').style.color = CATEGORIES[cur.cat].color;
    }
  }

  setCds(cds) { this.cds = cds; }

  /* ── TOASTS / BANNERS ────────────────────────────────────── */
  toast(title, text, tone = '#e9c988', icon = '✦') {
    const t = el('div', 'toast');
    t.style.setProperty('--tone', tone);
    t.innerHTML = `<span class="t-ico">${icon}</span><span class="t-body"><b>${title}</b><span>${text}</span></span>`;
    this.dom.toasts.appendChild(t);
    setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, 3800);
    while (this.dom.toasts.children.length > 4) this.dom.toasts.firstChild.remove();
  }

  objective(text) {
    const o = this.dom.objective;
    o.innerHTML = `<b>OBJECTIVE UPDATED</b><span>${text}</span>`;
    o.classList.remove('hidden');
    clearTimeout(this._objT);
    this._objT = setTimeout(() => o.classList.add('hidden'), 3600);
  }

  spellBanner(spell) {
    if (!spell) return;
    const b = this.dom.spellBanner;
    this.dom.bannerName.textContent = spell.name;
    this.dom.bannerRune.textContent = spell.rune;
    this.dom.bannerRune.style.color = CATEGORIES[spell.cat].color;
    b.classList.remove('hidden', 'hide');
    clearTimeout(this._bannerT);
    this._bannerT = setTimeout(() => { b.classList.add('hide'); setTimeout(() => b.classList.add('hidden'), 500); }, 3000);
  }

  levelFlash(level, title) {
    this.dom.lfLevel.textContent = level;
    this.dom.lfTitle.textContent = title;
    const f = this.dom.levelFlash;
    f.classList.remove('hidden');
    const ring = f.querySelector('.lf-ring');
    ring.style.animation = 'none'; void ring.offsetWidth; ring.style.animation = '';
    clearTimeout(this._lfT);
    this._lfT = setTimeout(() => f.classList.add('hidden'), 2400);
  }

  floatText(x, y, text, cls = '') {
    const n = el('div', `dmg-num ${cls}`, text);
    n.style.left = `${x}px`;
    n.style.top = `${y}px`;
    this.dom.damage.appendChild(n);
    setTimeout(() => n.remove(), 950);
  }

  combatLog(text, cls = '') {
    const line = el('div', `log-line ${cls}`, text);
    this.dom.combatLog.prepend(line);
    while (this.dom.combatLog.children.length > 5) this.dom.combatLog.lastChild.remove();
    setTimeout(() => { line.style.opacity = '0'; line.style.transition = 'opacity .6s'; }, 3600);
  }

  setCombat(on) {
    this.dom.combat.classList.toggle('hidden', !on);
    document.body.classList.toggle('combat-on', on);
    this.dom.crosshair.style.display = on ? '' : 'none';
    if (!on) { this.combatHp = null; this.combatMp = null; this.combo = 0; this.dom.comboEl.classList.remove('on'); }
  }

  updateCombat({ hp, mp, enemyName, enemyRank, enemyHp, enemyMax, round, casting, castColor, combo }) {
    this.combatHp = hp; this.combatMp = mp;
    if (enemyName !== undefined) {
      this.dom.enemyName.textContent = enemyName;
      this.dom.enemyRank.textContent = enemyRank || 'DUEL';
    }
    if (enemyHp !== undefined) {
      this.dom.enemyHp.style.width = `${clamp((enemyHp / enemyMax) * 100, 0, 100)}%`;
      this.dom.enemyHpText.textContent = `${Math.max(0, Math.ceil(enemyHp))} / ${enemyMax}`;
    }
    if (round) this.dom.duelRound.textContent = `ROUND ${['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX'][round - 1] || round}`;
    this.dom.enemyCast.classList.toggle('on', !!casting);
    if (casting) this.dom.enemyCast.style.setProperty('--cast-col', castColor || 'var(--rose)');
    if (combo !== undefined) {
      this.combo = combo;
      this.dom.comboEl.textContent = `×${combo}`;
      this.dom.comboEl.classList.toggle('on', combo > 1);
    }
    this.updateMeters();
  }

  setInteract(label, icon = 'E') {
    if (!label) { this.dom.interact.classList.add('hidden'); return; }
    this.dom.interact.classList.remove('hidden');
    this.dom.interactText.textContent = label;
    this.dom.interact.querySelector('kbd').textContent = icon;
  }

  playInteract() { this.dom.interact.classList.add('hidden'); }

  /* ── PANEL ───────────────────────────────────────────────── */
  openPanel(name) {
    if (!name) return;
    this.panel = name;
    this.panelTab = name;
    this.dom.overlay.classList.remove('hidden');
    this.dom.modal.classList.add('hidden');
    const meta = PANELS.find(p => p.id === name) || PANELS[0];
    this.dom.kicker.textContent = meta.kicker;
    this.dom.title2.textContent = meta.title;
    this.dom.nav.querySelectorAll('.nav-btn').forEach(b => b.classList.toggle('active', b.dataset.panel === name));
    this.renderPanel();
    this.actions.onPanelOpen?.(name);
  }

  renderPanel() {
    if (!this.panel) return;
    const meta = PANELS.find(p => p.id === this.panel) || PANELS[0];
    this.dom.kicker.textContent = meta.kicker;
    this.dom.title2.textContent = meta.title;
    this.dom.body.innerHTML = renderPanel(this, this.panel);
    this.dom.panelGold.textContent = this.game.s.gold.toLocaleString();
    this.dom.panelRep.textContent = this.game.s.rep;
  }

  closePanel() {
    this.panel = null;
    this.dom.overlay.classList.add('hidden');
    this.actions.onPanelClose?.();
  }

  onAction(act, id, btn) {
    this.audio.ui();
    switch (act) {
      case 'ing-tab': this.craft.tab = id; this.renderPanel(); break;
      case 'select-wood': this.craft.woodId = this.craft.woodId === id ? null : id; this.renderPanel(); break;
      case 'select-core': this.craft.coreId = this.craft.coreId === id ? null : id; this.renderPanel(); break;
      case 'toggle-mat': {
        const slots = BENCH[this.game.s.upgrades.bench].slots;
        if (this.craft.materials.includes(id)) this.craft.materials = this.craft.materials.filter(x => x !== id);
        else if (this.craft.materials.length >= slots) { this.toast('Bench is full', 'Upgrade your workbench for more finishing slots.', '#ff8c9a', '⚒'); this.audio.error(); return; }
        else this.craft.materials.push(id);
        this.renderPanel();
        break;
      }
      case 'remove-mat': this.craft.materials = this.craft.materials.filter(x => x !== id); this.renderPanel(); break;
      case 'craft': this.doPlayerCraft(); break;
      case 'craft-clear': this.craft = { ...this.craft, woodId: null, coreId: null, materials: [] }; this.renderPanel(); break;
      case 'spell-cat': this.spellCat = id; this.renderPanel(); break;
      case 'toggle-loadout': this.toggleLoadout(id); break;
      case 'spell-info': {
        const sp = SPELLS.find(x => x.id === id);
        const track = LESSON_TRACKS.find(t => t.lessons.some(l => l.spell === id));
        const lesson = track?.lessons.find(l => l.spell === id);
        this.toast(sp.name, `Learn it in ${track ? track.name : 'the Academy'}${lesson?.req?.level ? ` (requires level ${lesson.req.level})` : ''}.`, CATEGORIES[sp.cat].color, sp.rune);
        break;
      }
      case 'attend-lesson': this.startLesson(id); break;
      case 'shop-tab': this.shopTab = id; this.renderPanel(); break;
      case 'select-customer': this.shopCustomer = id; this.renderPanel(); break;
      case 'sell-wand': this.doSell(id); break;
      case 'buy-market': {
        const ok = this.game.buyMarket(id);
        if (ok) { this.toast('Purchased', 'Added to your stores.', '#e9c988', '◉'); this.audio.gather(); }
        else this.audio.error();
        this.refresh(); this.renderPanel();
        break;
      }
      case 'buy-upgrade': {
        const ok = this.game.buyUpgrade(id);
        if (ok) this.audio.levelup(); else this.audio.error();
        this.refresh(); this.renderPanel();
        break;
      }
      case 'equip-wand': this.game.equip(id); this.refresh(); this.renderPanel(); break;
      case 'travel': this.actions.travel?.(id); break;
      case 'spell-detail': break;
      case 'start-duel': this.actions.startDuel?.(id); break;
      case 'start-tournament': this.actions.startTournament?.(id); break;
      default: break;
    }
  }

  doPlayerCraft() {
    const d = this.craft;
    if (!d.woodId || !d.coreId) return;
    const res = this.game.craft({ ...d });
    if (!res.ok) { this.toast('The wand resists', res.msg, '#ff8c9a', '⚒'); this.audio.error(); return; }
    this.audio.gather();
    this.craft.materials = [];
    if (!this.game.countItem('woods', d.woodId)) this.craft.woodId = null;
    if (!this.game.countItem('cores', d.coreId)) this.craft.coreId = null;
    this.refresh();
    this.renderPanel();
    this.toast(res.wand.name, `${RARITIES[res.wand.rarity].name} · quality ${res.wand.quality}`, RARITIES[res.wand.rarity].color, '⌁');
    if (res.isNewRecipe) {
      this.showModal(`<div class="modal-kicker">A COMBINATION THE SHOP WILL REMEMBER</div>
        <div class="modal-title">${res.wand.name}</div>
        <div class="modal-sub">${res.wand.recipe?.lore || ''}</div>
        <div class="modal-sep"></div>
        <div style="display:grid;place-items:center">${wandSVG(res.wand, { scale: 0.9 })}</div>
        <div class="wand-trait" style="margin-top:10px"><b>${res.wand.recipe?.trait || res.wand.trait.name}</b>${res.wand.recipe?.traitDesc || res.wand.trait.desc}</div>
        <div class="modal-actions"><button class="btn-gold" onclick="document.getElementById('modal').classList.add('hidden')">A wand for the ledger</button></div>`);
      this.audio.victory();
    }
  }

  toggleLoadout(id) {
    const known = this.game.s.known[id] !== undefined;
    if (!known) return;
    const on = !this.game.s.loadout.includes(id);
    this.game.setLoadout(id, on);
    this.updateSpellbar();
    this.refresh();
    this.renderPanel();
  }

  doSell(wandId) {
    const customer = this.game.s.customers.find(c => c.id === (this.shopCustomer || this.game.s.customers[0]?.id));
    if (!customer) return;
    const res = this.game.sell(wandId, customer.id);
    const info = this.game.getCustomerInfo(customer);
    const wand = this.game.s.wands.find(w => w.id === wandId) || { name: 'the wand' };
    if (res.ok) {
      this.audio.victory();
      this.showModal(`<div class="modal-kicker">A WAND FINDING ITS WIZARD</div>
        <div class="modal-title">◉ ${res.price.toLocaleString()}</div>
        <div class="modal-sub">${esc(customerReaction(res.eval, wand, info))}</div>
        <div class="reward-row">
          <div class="reward"><span>◉</span>${res.price} galleons</div>
          <div class="reward rep"><span>✧</span>+4 reputation</div>
          <div class="reward xp"><span>✦</span>+${Math.round(30 + res.eval.score * 0.9)} XP</div>
        </div>
        <div class="modal-actions"><button class="btn-gold" data-close>Lovely.</button></div>`);
      if (this.shopCustomer) {
        const still = this.game.s.customers.find(c => c.id === this.shopCustomer);
        if (!still) this.shopCustomer = this.game.s.customers[0]?.id || null;
      }
    } else {
      this.audio.error();
      this.showModal(`<div class="modal-kicker">NOT QUITE THE ONE</div>
        <div class="modal-title">${esc(info?.name || 'The customer')} declines</div>
        <div class="modal-sub">${esc(customerReaction(res.eval, wand, info))}</div>
        <div class="modal-actions"><button class="btn-line" data-close>Try another wand</button></div>`);
    }
    this.refresh();
    if (this.panel) this.renderPanel();
  }

  /* ── LESSONS ─────────────────────────────────────────────── */
  startLesson(lessonId) {
    let lesson, track;
    for (const t of LESSON_TRACKS) {
      const l = t.lessons.find(x => x.id === lessonId);
      if (l) { lesson = l; track = t; break; }
    }
    if (!lesson) return;
    const spell = SPELLS.find(s => s.id === lesson.spell);
    this.challenge(lesson, track, spell, () => {
      const learned = this.game.completeLesson(lessonId);
      if (learned) {
        this.audio.levelup();
        this.spellBanner(spell);
        this.refresh();
        if (this.panel) this.renderPanel();
        this.showModal(`<div class="modal-kicker">LESSON COMPLETE</div>
          <div class="modal-title">${spell.name}</div>
          <div class="modal-sub">${esc(spell.desc)}</div>
          <div class="reward-row">
            <div class="reward xp"><span>✦</span>+${lesson.xp} XP</div>
            <div class="reward rep"><span>✧</span>+3 reputation</div>
            <div class="reward"><span>${spell.rune}</span>${CATEGORIES[spell.cat].name} spell learned</div>
          </div>
          <div class="modal-actions"><button class="btn-gold" data-close>Add to the grimoire</button></div>`);
      }
    });
  }

  challenge(lesson, track, spell, onSuccess) {
    if (this.challengeCleanup) this.challengeCleanup();
    const type = lesson.type;
    const color = CATEGORIES[track.cat].color;
    this.modalLocked = true;
    const sequence = shuffle(RUNES).slice(0, type === 'rune' ? (lesson.runes || 4) : 6);
    let hearts = type === 'rune' ? 3 : 6;
    let hits = 0;
    let timeLeft = lesson.time;
    let phase = 'watch';
    let input = [];
    let needle = 8;
    let dir = 1;
    let zone = 34;
    let done = false;
    const totalTime = lesson.time;
    const zoneW = 20;

    const html = `<div class="challenge" id="ch-root">
      <div class="challenge-head"><span>${esc(lesson.name)}</span><span id="ch-timer-label">${Math.ceil(timeLeft)}s</span><span>${esc(track.teacher)}</span></div>
      <div class="challenge-timer"><div id="ch-timer" style="width:100%"></div></div>
      <div class="modal-sub" style="margin-bottom:6px">${type === 'rune' ? 'Watch the rune sequence, then repeat it with your wand. A mistake costs a heart.' : 'Cast when the needle passes through the bright band. Three clean casts will carry the lesson.'}</div>
      ${type === 'rune' ? `<div class="rune-row" id="ch-runes">${sequence.map((r, i) => `<button class="rune-btn" data-rune="${r}" style="--rn:${color}">${r}</button>`).join('')}</div>
        <div class="lesson-steps" id="ch-steps">${sequence.map((_, i) => `<div class="lesson-step"></div>`).join('')}</div>` :
      `<div class="timing-track" id="ch-track" style="--z:${zone}"><div class="zone" style="left:${zone - zoneW / 2}%;width:${zoneW}%"></div><div class="zone best" style="left:${zone - 3}%;width:6%"></div><div class="needle" id="ch-needle" style="left:8%"></div></div>
        <div class="lesson-steps" id="ch-steps"><div class="lesson-step"></div><div class="lesson-step"></div><div class="lesson-step"></div></div>
        <button class="btn-gold" id="ch-cast" style="margin-top:16px">Cast</button>`}
      <div class="challenge-status" id="ch-status">${type === 'rune' ? 'Watching the wand…' : 'Ready — wait for the needle.'}</div>
      <div class="modal-actions"><button class="btn-line" id="ch-leave">Leave the lesson</button></div>
      <div style="margin-top:10px;display:flex;justify-content:center;gap:8px" id="ch-hearts">${'❤'.repeat(hearts)}</div>
    </div>`;
    this.showModal(html, { wide: true, locked: true });
    const root = $('ch-root');
    const status = $('ch-status');
    const timerBar = $('ch-timer');
    const timerLabel = $('ch-timer-label');
    const heartsEl = $('ch-hearts');
    const steps = [...document.querySelectorAll('#ch-steps .lesson-step')];
    const runeBtns = [...document.querySelectorAll('.rune-btn')];

    const updateHearts = () => { heartsEl.textContent = '❤'.repeat(Math.max(0, hearts)) + '·'.repeat(Math.max(0, (type === 'rune' ? 3 : 6) - hearts)); };

    const fail = () => {
      if (done) return;
      done = true;
      cleanup();
      this.modalLocked = false;
      this.audio.error();
      this.showModal(`<div class="modal-kicker">THE LESSON RESISTS</div>
        <div class="modal-title">Not this time</div>
        <div class="modal-sub">${esc(track.teacher)} taps the desk. “Again. The wand doesn't care that you were close.”</div>
        <div class="modal-actions"><button class="btn-gold" id="ch-retry">Try again</button><button class="btn-line" data-close>Leave</button></div>`);
      $('ch-retry').addEventListener('click', () => this.challenge(lesson, track, spell, onSuccess));
    };
    const succeed = () => {
      if (done) return;
      done = true;
      cleanup();
      this.modalLocked = false;
      onSuccess();
    };
    const cleanup = () => {
      clearInterval(loop);
      document.querySelectorAll('.rune-btn').forEach(b => b.classList.remove('flash'));
      this.challengeCleanup = null;
      this.modalLocked = false;
    };
    this.challengeCleanup = cleanup;
    root.querySelector('#ch-leave').addEventListener('click', () => { cleanup(); this.closeModal(); });

    if (type === 'rune') {
      let idx = 0;
      const showNext = () => {
        if (done) return;
        if (idx >= sequence.length) { phase = 'play'; status.textContent = 'Your turn. Repeat the sequence.'; return; }
        const r = sequence[idx];
        const b = runeBtns.find(x => x.dataset.rune === r);
        b?.classList.add('flash');
        this.audio.tone({ freq: 420 + idx * 60, type: 'sine', dur: 0.18, vol: 0.09 });
        setTimeout(() => b?.classList.remove('flash'), 340);
        idx++;
        setTimeout(showNext, 520);
      };
      setTimeout(showNext, 650);
      runeBtns.forEach(b => b.addEventListener('click', () => {
        if (done || phase !== 'play') return;
        const expected = sequence[input.length];
        if (b.dataset.rune === expected) {
          b.classList.add('flash');
          setTimeout(() => b.classList.remove('flash'), 250);
          this.audio.tone({ freq: 520 + input.length * 70, type: 'triangle', dur: 0.2, vol: 0.1 });
          input.push(b.dataset.rune);
          steps[input.length - 1]?.classList.add('done');
          if (input.length >= sequence.length) succeed();
        } else {
          b.classList.add('wrong');
          setTimeout(() => b.classList.remove('wrong'), 320);
          hearts--; updateHearts(); this.audio.error();
          input = [];
          steps.forEach(s => s.classList.remove('done'));
          status.textContent = hearts > 0 ? 'The runes scatter. Start the sequence again.' : 'The lesson slips away.';
          if (hearts <= 0) fail();
        }
      }));
    } else {
      const castBtn = root.querySelector('#ch-cast');
      const needleEl = root.querySelector('#ch-needle');
      const doCast = () => {
        if (done) return;
        const inBest = Math.abs(needle - zone) <= 2.5;
        const inZone = Math.abs(needle - zone) <= zoneW / 2;
        if (inZone) {
          hits++;
          steps[hits - 1]?.classList.add('done');
          this.audio.tone({ freq: 560 + hits * 90, type: 'triangle', dur: 0.25, vol: 0.1 });
          status.textContent = inBest ? 'Perfect. The spell holds.' : 'Clean enough. Again.';
          if (hits >= 3) succeed();
        } else {
          hearts--; updateHearts(); this.audio.error();
          status.textContent = hearts > 0 ? 'The gesture slips. Steady your hand.' : 'The spell fizzles out.';
          if (hearts <= 0) fail();
        }
      };
      castBtn.addEventListener('click', doCast);
      root.addEventListener('keydown', e => { if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); doCast(); } });
      setTimeout(() => { phase = 'play'; status.textContent = 'Now — cast in the bright band.'; }, 700);
    }

    const loop = setInterval(() => {
      if (done) return;
      timeLeft -= 0.06;
      timerBar.style.width = `${clamp((timeLeft / totalTime) * 100, 0, 100)}%`;
      timerLabel.textContent = `${Math.max(0, Math.ceil(timeLeft))}s`;
      if (timeLeft <= 0) { fail(); return; }
      if (type === 'timing') {
        needle += dir * 1.7;
        if (needle >= 96) { needle = 96; dir = -1; }
        if (needle <= 4) { needle = 4; dir = 1; }
        const n = document.getElementById('ch-needle');
        if (n) n.style.left = (needle - 1) + '%';
      }
    }, 60);
  }

  /* ── DIALOGUE ────────────────────────────────────────────── */
  talk(npcId) {
    const d = DIALOGUE[npcId];
    if (!d) return;
    const lines = d.lines;
    const greet = lines.greet;
    const choices = [];
    if (npcId === 'orin') {
      choices.push({ label: 'Show me the bench', action: () => { this.closeDialogue(); this.openPanel('craft'); } });
      choices.push({ label: 'Tell me about wands', action: () => this.setDialogueText(lines.craft) });
      choices.push({ label: 'Any legendary pairings?', action: () => this.setDialogueText(lines.legendary) });
      choices.push({ label: 'Farewell', action: () => this.closeDialogue() });
    } else if (npcId === 'reed') {
      choices.push({ label: 'Attend a lesson', action: () => { this.closeDialogue(); this.openPanel('spells'); } });
      choices.push({ label: 'How does spellcraft work?', action: () => this.setDialogueText(lines.teach) });
      choices.push({ label: 'Farewell', action: () => this.closeDialogue() });
    } else if (npcId === 'sable') {
      choices.push({ label: 'Enter the ring', action: () => { this.closeDialogue(); this.openPanel('duel'); } });
      choices.push({ label: 'Advice?', action: () => this.setDialogueText(lines.duel) });
      choices.push({ label: 'Farewell', action: () => this.closeDialogue() });
    } else if (npcId === 'keeper') {
      choices.push({ label: 'The Forbidden Arts', action: () => { this.closeDialogue(); this.openPanel('spells'); } });
      choices.push({ label: 'Why keep them?', action: () => this.setDialogueText(lines.forbidden) });
      choices.push({ label: 'Farewell', action: () => this.closeDialogue() });
    } else {
      choices.push({ label: 'Farewell', action: () => this.closeDialogue() });
    }
    this.dom.dialogue.classList.remove('hidden');
    this.dialogueOpen = true;
    this.dom.dlgPortrait.textContent = d.initials;
    this.dom.dlgPortrait.style.color = d.color;
    this.dom.dlgName.textContent = d.name;
    this.dom.dlgText.textContent = greet;
    this.dialogueChoices = choices;
    this.dom.dlgChoices.innerHTML = choices.map((c, i) => `<button class="dlg-choice" data-choice="${i}">${c.label}</button>`).join('') +
      `<button class="dlg-close" aria-label="Close">✕</button>`;
    this.actions.onDialogue?.(true);
  }

  setDialogueText(text) {
    this.dom.dlgText.style.opacity = '0';
    setTimeout(() => { this.dom.dlgText.textContent = text; this.dom.dlgText.style.opacity = '1'; }, 120);
  }

  closeDialogue() {
    this.dom.dialogue.classList.add('hidden');
    this.dialogueOpen = false;
    this.actions.onDialogue?.(false);
  }

  /* ── MODAL ───────────────────────────────────────────────── */
  showModal(html, { wide = false, locked = false } = {}) {
    this.modalOpen = true;
    this.modalLocked = locked;
    this.dom.modal.classList.remove('hidden');
    this.dom.modalCard.classList.toggle('wide', wide);
    this.dom.modalCard.innerHTML = html;
    this.dom.modalCard.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => this.closeModal()));
    this.actions.onModal?.(true);
  }

  closeModal() {
    this.modalOpen = false;
    this.modalLocked = false;
    this.dom.modal.classList.add('hidden');
    this.dom.modalCard.innerHTML = '';
    if (this.challengeCleanup) { this.challengeCleanup(); this.challengeCleanup = null; }
    this.actions.onModal?.(false);
  }

  /* ── MINIMAP ─────────────────────────────────────────────── */
  drawMinimap(world, player, yaw = 0) {
    const ctx = this.minimapCtx;
    if (!ctx || !world) return;
    const W = 320, H = 320, cx = W / 2, cy = H / 2;
    const viewR = 92;
    const scale = (W / 2 - 8) / viewR;
    ctx.clearRect(0, 0, W, H);
    ctx.save();
    ctx.beginPath(); ctx.arc(cx, cy, W / 2 - 2, 0, Math.PI * 2); ctx.clip();
    const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, W / 2);
    bg.addColorStop(0, '#1a2033'); bg.addColorStop(0.7, '#11131f'); bg.addColorStop(1, '#08080f');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    const toMap = (x, z) => ({ x: cx + (x - player.x) * scale, y: cy + (z - player.z) * scale });
    // terrain tint blobs
    for (const zone of ZONES) {
      const p = toMap(zone.x, zone.z);
      const r = zone.r * scale;
      const grd = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, Math.max(6, r));
      grd.addColorStop(0, zone.color + '33'); grd.addColorStop(1, zone.color + '00');
      ctx.fillStyle = grd;
      ctx.beginPath(); ctx.arc(p.x, p.y, Math.max(6, r), 0, Math.PI * 2); ctx.fill();
    }
    // nodes
    for (const n of world.nodes) {
      if (!n.active) continue;
      const p = toMap(n.x, n.z);
      if (p.x < -10 || p.x > W + 10 || p.y < -10 || p.y > H + 10) continue;
      ctx.fillStyle = n.info.color;
      ctx.globalAlpha = 0.8;
      ctx.beginPath(); ctx.arc(p.x, p.y, 2.4, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    // interactables
    for (const it of world.interactables) {
      const p = toMap(it.x, it.z);
      if (p.x < 0 || p.x > W || p.y < 0 || p.y > H) continue;
      ctx.fillStyle = it.markerColor || '#e9c988';
      ctx.globalAlpha = 0.75;
      ctx.beginPath(); ctx.arc(p.x, p.y, 3, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    // npcs
    for (const n of world.npcs) {
      const p = toMap(n.x, n.z);
      ctx.fillStyle = '#ffd27a';
      ctx.beginPath(); ctx.arc(p.x, p.y, 3.4, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(255,210,122,.4)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(p.x, p.y, 5.5, 0, Math.PI * 2); ctx.stroke();
    }
    // player arrow
    ctx.save();
    ctx.translate(cx, cy);
    const heading = yaw;
    ctx.rotate(-heading + Math.PI);
    ctx.fillStyle = '#ffe6b0';
    ctx.shadowColor = '#e9c988'; ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(6.5, 6); ctx.lineTo(0, 2.5); ctx.lineTo(-6.5, 6); ctx.closePath(); ctx.fill();
    ctx.restore();
    // ring grid
    ctx.strokeStyle = 'rgba(233,201,136,.12)'; ctx.lineWidth = 1;
    for (const r of [40, 80, 120]) { ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke(); }
    ctx.restore();
  }

  zoneFor(x, z) {
    let best = null, bd = Infinity;
    for (const zn of ZONES) {
      const d = Math.hypot(x - zn.x, z - zn.z);
      if (d < zn.r && d < bd) { best = zn; bd = d; }
    }
    return best;
  }

  compass(yaw) {
    const track = this.dom.compass;
    if (!track) return;
    const norm = ((-yaw * 180 / Math.PI) % 360 + 360) % 360;
    track.style.transform = `translateX(${-(norm / 360) * 100}%)`;
  }
}

function esc(s = '') { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;'); }

/* ═══════════════════════════════════════════════════════════
   WANDLORE · THE DUELLING RING
   Real-time spell combat: projectiles, wards, dodges, statuses.
   ═══════════════════════════════════════════════════════════ */
import * as THREE from 'three';
import { SPELLS } from './data.js';
import { categoryPower } from './crafting.js';
import { createWizard } from './character.js';
import { createArena } from './effects.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rnd = (a, b) => a + Math.random() * (b - a);
const dist = (a, b) => Math.hypot(a.x - b.x, a.z - b.z);

export class Duel {
  constructor(game, effects, audio, callbacks = {}) {
    this.game = game;
    this.effects = effects;
    this.audio = audio;
    this.cb = callbacks;
    this.scene = null;
    this.arena = null;
    this.active = false;
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.summons = [];
    this.cds = {};
    this.combo = 0;
    this.comboTimer = 0;
    this.resultSent = false;
    this.shieldHeld = false;
    this.spellCount = 0;
  }

  dispose() {
    this.active = false;
    this.resultSent = true;
    for (const p of [...this.projectiles, ...this.enemyProjectiles]) this.destroyProjectile(p);
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.summons = [];
    if (this.scene) this.effects.setScene(null);
    this.scene = null;
    this.arena = null;
  }

  start(def, opts = {}) {
    this.dispose();
    this.resultSent = false;
    this.active = true;
    this.def = def;
    this.scene = new THREE.Scene();
    this.arena = createArena(this.scene, def.arena || 'ring');
    this.effects.setScene(this.scene);
    this.cds = {};
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.summons = [];
    this.combo = 0;
    this.comboTimer = 0;
    this.spellCount = 0;
    this.phase = 'intro';
    this.introTime = 2.0;
    this.round = 1;
    this.shieldHeld = false;
    this.shieldVisual = null;
    this.wardTime = 0;
    this.aegisTime = 0;
    this.dodgeTime = 0;
    this.dodgeCd = 0;
    this.shieldHeldTime = 0;
    this.revived = false;
    this.enemyDots = [];
    this.enemyStatus = { stun: 0, slow: 0, silence: 0, fear: 0, wet: 0, lift: 0 };
    this.bossPhase = 1;
    this.castQueue = [];
    this.enemyCast = null;
    this.enemyCastCd = rnd(1.2, 2.2);

    const g = this.game;
    this.maxHp = g.maxHp() + (g.s.upgrades.cauldron ? 20 : 0);
    this.hp = this.maxHp;
    this.maxMp = g.maxMp();
    this.mp = this.maxMp;
    this.wand = g.wand;

    // player wizard
    this.player = createWizard({
      robe: '#2f3560', accent: '#d9b268', hair: '#2b1e1a', hat: true, scale: 1.02,
      name: opts.name || g.s.name, subtitle: g.displayTitle(), nameColor: '#f0d79e'
    });
    const ps = this.arena.playerSpawn;
    this.player.group.position.copy(ps);
    this.player.group.rotation.y = Math.PI;
    this.player.setWand(this.wand);
    this.scene.add(this.player.group);

    // enemy wizard
    const e = def;
    this.enemy = createWizard({
      robe: e.robe, accent: e.accent, hair: '#1c1518', hat: e.behavior !== 'brute',
      crown: e.behavior === 'boss', horns: e.behavior === 'guardian', scale: e.behavior === 'brute' ? 1.5 : e.behavior === 'boss' ? 1.3 : 1.04,
      name: e.name, subtitle: e.title, nameColor: e.accent
    });
    const es = this.arena.enemySpawn;
    this.enemy.group.position.copy(es);
    this.enemy.group.rotation.y = 0;
    this.enemy.setWand({ woodId: e.behavior === 'boss' ? 'voidbriar' : 'blackthorn', coreId: e.behavior === 'boss' ? 'wraithglass' : 'dragon', length: 12, stats: { aether: 40 } });
    this.scene.add(this.enemy.group);

    this.enemyHp = e.hp;
    this.enemyMaxHp = e.hp;
    this.playerPos = this.player.group.position;
    this.enemyPos = this.enemy.group.position;

    // intro fx
    this.arena.update(0, 0);
    this.effects.runeCircle(new THREE.Vector3(ps.x, 0.05, ps.z), '#e9c988', 3, 1.6);
    this.effects.runeCircle(new THREE.Vector3(es.x, 0.05, es.z), e.accent, 3, 1.6);
    this.effects.ring(new THREE.Vector3(0, 0.06, 0), '#e9c988', 16, 1.1);
    this.audio.duelStart?.();
    this.cb.onHud?.({ enemyName: e.name, enemyRank: e.boss ? 'BOSS DUEL' : e.rank.toUpperCase(), round: 1, hp: this.hp, mp: this.mp, enemyHp: this.enemyHp, enemyMax: this.enemyMaxHp, casting: false });
    this.cb.onLog?.(`<b>${e.name}</b> steps into the circle.`, 'spell');
    this.cb.onStart?.(this);
    return this;
  }

  trait(name) {
    return this.wand?.trait?.key === 'recipe' && this.wand.recipe?.name === name;
  }

  get cdMultiplier() {
    let m = 1;
    if (this.trait('Astral Sovereign')) m *= 0.8;
    if (this.wand?.coreId === 'moonstoneheart') m *= 0.85;
    if (this.wand?.coreId === 'augurey' && this.trait('Oracle’s Sigh')) m *= 0.85;
    return m;
  }

  manaCost(spell) {
    let m = spell.mana;
    const core = this.wand?.coreId;
    if (core === 'dragon' && spell.cat === 'offense') m *= 1.1;
    if (core === 'unicorn' && spell.cat === 'forbidden') m *= 1.15;
    if (core === 'wraithglass') m *= 0.9;
    if (this.trait('Nightfall') && spell.cat === 'forbidden') m *= 0.7;
    return Math.round(m);
  }

  cast(index) {
    if (!this.active || this.phase !== 'fight') return;
    const spellId = this.game.s.loadout[index];
    if (!spellId) return;
    const spell = SPELLS.find(x => x.id === spellId);
    if (!spell) return;
    if ((this.cds[spell.id] || 0) > 0) return;
    const cost = this.manaCost(spell);
    if (this.mp < cost) { this.cb.onToast?.('Not enough mana', 'The wand sputters. Let it breathe.', '#78b4ff', '✦'); return; }
    this.mp -= cost;
    this.cds[spell.id] = spell.cd * this.cdMultiplier;
    this.game.addMastery(spell.id, spell.cat === 'forbidden' ? 0.5 : 0.7);
    this.spellCount++;
    const mastery = this.game.masteryRank(spell.id).mult;
    const power = categoryPower(this.wand, spell.cat);
    let dmg = Math.max(1, spell.dmg) * power * mastery * rnd(0.92, 1.08);
    if (this.wand?.coreId === 'dragon' && spell.cat === 'offense') dmg *= 1.15;
    if (this.wand?.coreId === 'unicorn' && spell.cat === 'healing') dmg *= 1.2;
    if (this.trait('Nightfall') && spell.cat === 'forbidden') dmg *= 1.25;
    if (this.trait('Nightfall') && spell.cat === 'healing') dmg *= 0.5;
    const critChance = 0.07 + (this.wand?.stats.ctrl || 0) / 520;
    const crit = Math.random() < critChance;
    if (crit) dmg *= 1.55;

    this.player.cast();
    this.effects.castSpark(this.player.getTipWorld(), spell.color);
    this.audio.cast?.(spell.cat);
    this.cb.onLog?.(`You cast <b>${spell.name}</b>${crit ? ' — a perfect gesture!' : ''}`, 'spell');

    const tip = this.player.getTipWorld();
    const target = new THREE.Vector3(this.enemyPos.x, 1.15, this.enemyPos.z);

    switch (spell.effect) {
      case 'projectile': {
        this.spawnPlayerProjectile(tip, target, spell, dmg, crit, { status: spell.status, statusTime: spell.statusTime, knock: spell.knock });
        break;
      }
      case 'aoe_bolt': {
        this.spawnPlayerProjectile(tip, target, spell, dmg, crit, { status: spell.status, statusTime: spell.statusTime, radius: spell.radius || 3.5 });
        break;
      }
      case 'beam': {
        this.effects.beam(tip, target, spell.color, 0.16, 0.4);
        this.effects.burst(target, spell.color, 16, { speed: 4, size: 0.4 });
        this.hitEnemy(dmg, crit, spell, { knock: spell.knock });
        break;
      }
      case 'chain': {
        const pts = [tip, new THREE.Vector3(this.enemyPos.x + rnd(-0.4, 0.4), 1.4, this.enemyPos.z + rnd(-0.4, 0.4))];
        this.effects.lightning(pts, spell.color, 0.45);
        this.hitEnemy(dmg, crit, spell);
        if (this.trait('Stormcaller') || this.wand?.coreId === 'thunderbird') {
          setTimeout(() => { if (this.active) this.hitEnemy(dmg * 0.3, false, spell); }, 220);
        }
        break;
      }
      case 'burst': {
        this.effects.ring(new THREE.Vector3(this.playerPos.x, 0.06, this.playerPos.z), spell.color, spell.radius || 5, 0.7);
        this.effects.burst(new THREE.Vector3(this.playerPos.x, 1.2, this.playerPos.z), spell.color, 32, { speed: 8, size: 0.55 });
        if (dist(this.playerPos, this.enemyPos) <= (spell.radius || 5)) this.hitEnemy(dmg, crit, spell, { status: spell.status, statusTime: spell.statusTime });
        this.effects.shake(0.3);
        break;
      }
      case 'aoe_self': {
        this.effects.ring(new THREE.Vector3(this.playerPos.x, 0.06, this.playerPos.z), spell.color, spell.radius || 7, 0.9);
        this.effects.burst(new THREE.Vector3(this.playerPos.x, 1.4, this.playerPos.z), spell.color, 40, { speed: 9, size: 0.7, flash: 6 });
        this.effects.shake(0.6);
        if (dist(this.playerPos, this.enemyPos) <= (spell.radius || 7)) this.hitEnemy(dmg, crit, spell, { status: 'burn', statusTime: 4 });
        break;
      }
      case 'buff': {
        if (spell.buff === 'ward') {
          this.wardTime = spell.time;
          this.effects.runeCircle(new THREE.Vector3(this.playerPos.x, 0.05, this.playerPos.z), spell.color, 2.4, 0.8);
          this.cb.onLog?.('A ward settles over you.', 'good');
        } else {
          this.aegisTime = spell.time;
          this.effects.aegisPulse(new THREE.Vector3(this.playerPos.x, 0.05, this.playerPos.z), spell.color, 3.6);
          this.cb.onLog?.('Aegis raised — projectiles will break on it.', 'good');
        }
        break;
      }
      case 'heal':
      case 'hot': {
        const heal = spell.effect === 'heal' ? dmg : dmg;
        if (spell.effect === 'heal') this.healPlayer(heal);
        else {
          this.healPlayer(heal * 0.35);
          this.hotTime = spell.time;
          this.hotRate = (heal * 0.65) / spell.time;
        }
        this.effects.heal(new THREE.Vector3(this.playerPos.x, 0.1, this.playerPos.z), spell.color);
        this.audio.heal?.();
        if (this.trait('Tidecaller') || this.wand?.coreId === 'coral') {
          this.wardTime = Math.max(this.wardTime, 3);
          this.effects.ring(new THREE.Vector3(this.playerPos.x, 0.06, this.playerPos.z), '#8ef0b0', 2.2, 0.7);
        }
        break;
      }
      case 'summon': {
        this.effects.summon(new THREE.Vector3(this.playerPos.x + 1.2, 0.05, this.playerPos.z), spell.color);
        this.summons.push({ time: spell.time, tick: 0, dmg: 7 * power * mastery, color: spell.color });
        this.cb.onLog?.('A spectral serpent coils at your feet.', 'good');
        break;
      }
      default: break;
    }

    // Starfall: every fifth spell calls a meteor
    if (this.trait('Astral Sovereign') && this.spellCount % 5 === 0) {
      this.effects.meteor(target.clone(), '#b48cff', () => {
        if (this.active && this.enemyHp > 0) this.hitEnemy(40 * power, true, spell, { status: 'burn', statusTime: 3 });
      });
      this.cb.onLog?.('The wand remembers the sky. A meteor answers.', 'spell');
    }

    this.cb.onHud?.({ hp: this.hp, mp: this.mp });
  }

  spawnPlayerProjectile(from, to, spell, dmg, crit, opts = {}) {
    const orb = this.effects.createOrb(spell.color, 0.17);
    orb.group.position.copy(from);
    const dir = new THREE.Vector3().subVectors(to, from).normalize();
    const speed = spell.effect === 'aoe_bolt' ? 20 : 26;
    const vel = dir.multiplyScalar(speed);
    this.projectiles.push({ orb, vel, dmg, crit, spell, opts, life: 2.2, radius: opts.radius });
  }

  spawnEnemyProjectile(from, target, spell, dmg, opts = {}) {
    const color = opts.color || spell?.color || '#ff6b7a';
    const orb = this.effects.createOrb(color, opts.size || 0.16);
    orb.group.position.copy(from);
    const dir = new THREE.Vector3().subVectors(target, from).normalize();
    dir.x += rnd(-0.03, 0.03); dir.z += rnd(-0.03, 0.03);
    this.enemyProjectiles.push({ orb, vel: dir.multiplyScalar(opts.speed || 15), dmg, life: 4, color });
  }

  destroyProjectile(p) {
    this.effects.removeOrb(p.orb);
  }

  hitEnemy(dmg, crit, spell, opts = {}) {
    if (this.enemyHp <= 0) return;
    let final = dmg;
    // boss damage reduction in later phases
    if (this.def.behavior === 'boss' && this.bossPhase > 1) final *= 0.92;
    this.enemyHp = Math.max(0, this.enemyHp - final);
    this.combo++;
    this.comboTimer = 3;
    this.enemy.flash();
    this.audio.hit?.();
    this.effects.shake(crit ? 0.34 : 0.14);
    this.cb.onDamage?.(new THREE.Vector3(this.enemyPos.x, 1.6, this.enemyPos.z), Math.round(final), crit ? 'crit' : '');
    this.cb.onHud?.({ enemyHp: this.enemyHp, combo: this.combo });
    if (opts.status) this.applyStatus(opts.status, opts.statusTime || 3);
    if (this.wand?.coreId === 'basilisk' && spell?.cat === 'forbidden') this.applyStatus('poison', 4);
    if (this.trait("Serpent's Kiss") && spell?.cat === 'forbidden') this.applyStatus('poison', 5);
    if (this.trait('Sunforged') && spell?.cat === 'elemental') this.healPlayer(final * 0.15, true);
    if (this.enemyHp <= 0) this.finishVictory();
  }

  applyStatus(type, time) {
    const st = this.enemyStatus;
    if (type === 'stun' || type === 'lift') { st.stun = Math.max(st.stun, time); this.cb.onLog?.(`${this.def.name} is ${type === 'lift' ? 'hoisted into the air' : 'stunned'}.`, 'good'); }
    if (type === 'slow') { st.slow = Math.max(st.slow, time); this.cb.onLog?.(`${this.def.name} slows.`, 'good'); }
    if (type === 'silence' || type === 'disarm') { st.silence = Math.max(st.silence, time); this.cb.onLog?.(`${this.def.name} cannot cast.`, 'good'); }
    if (type === 'fear') { st.fear = Math.max(st.fear, time); this.cb.onLog?.(`${this.def.name} recoils from the silver light.`, 'good'); }
    if (type === 'wet') st.wet = Math.max(st.wet, time);
    if (type === 'burn') this.enemyDots.push({ type: 'burn', time, dps: 5 + this.wand.stats.aether * 0.06 });
    if (type === 'bleed') this.enemyDots.push({ type: 'bleed', time, dps: 7 });
    if (type === 'poison') this.enemyDots.push({ type: 'poison', time, dps: 6 });
  }

  healPlayer(amount, silent = false) {
    const before = this.hp;
    this.hp = Math.min(this.maxHp, this.hp + amount);
    if (!silent) this.cb.onDamage?.(new THREE.Vector3(this.playerPos.x, 2.2, this.playerPos.z), Math.round(this.hp - before), 'heal');
    this.cb.onHud?.({ hp: this.hp });
  }

  takeDamage(dmg, fromPos, opts = {}) {
    if (!this.active || this.phase !== 'fight' || this.resultSent) return;
    if (this.dodgeTime > 0) {
      this.cb.onLog?.('You slip aside — the spell finds only air.', 'good');
      return;
    }
    let amount = dmg;
    if (this.shieldHeld && this.mp > 0) amount *= (this.wand?.coreId === 'chimaera' ? 0.36 : 0.45);
    if (this.wardTime > 0) amount *= 0.6;
    if (this.aegisTime > 0) amount *= 0.7;
    if (this.trait('Hearthward') && this.hp < this.maxHp * 0.3) amount *= 0.75;
    if (this.trait('Mirrormere') && fromPos) {
      const reflect = amount * 0.25;
      setTimeout(() => { if (this.active && this.enemyHp > 0) this.hitEnemy(reflect, false, null); }, 120);
    }
    this.hp = Math.max(0, this.hp - amount);
    this.combo = 0;
    this.cb.onHud?.({ hp: this.hp, mp: this.mp, combo: 0 });
    this.cb.onDamage?.(new THREE.Vector3(this.playerPos.x, 2.1, this.playerPos.z), Math.round(amount), 'enemy');
    this.player.flash();
    this.effects.shake(0.42);
    this.effects.burst(new THREE.Vector3(this.playerPos.x, 1.1, this.playerPos.z), '#ff8a9a', 14, { speed: 3.5, size: 0.4 });
    this.audio.hit?.();
    this.cb.onLog?.(`<b>${this.def.name}</b> strikes you for ${Math.round(amount)}.`, 'dmg');
    this.cb.onHudFlash?.();
    if (this.hp <= 0) this.checkDefeat();
  }

  checkDefeat() {
    if (this.trait('Emberheart') && !this.revived) { this.revive('Emberheart'); return; }
    if (this.wand?.coreId === 'phoenix' && !this.revived) { this.revive('phoenix'); return; }
    if (this.trait('Mirrormere') && !this.revived && Math.random() < 0.35) { this.revive('mirror'); return; }
    this.phase = 'lost';
    this.audio.defeat?.();
    this.cb.onLog?.('Your wand falls from your hand.', 'dmg');
    this.player.group.rotation.z = 0.9;
    setTimeout(() => this.finishDefeat(), 1400);
  }

  revive(kind) {
    this.revived = true;
    this.hp = Math.round(this.maxHp * 0.3);
    this.wardTime = 2;
    this.cb.onHud?.({ hp: this.hp });
    this.cb.onLog?.('The wand refuses. You rise again.', 'good');
    this.cb.onToast?.('Ashes to dawn', 'Your wand pulls you back from the dark.', '#ffbd5e', '✦');
    this.effects.ring(new THREE.Vector3(this.playerPos.x, 0.06, this.playerPos.z), '#ffbd5e', 6, 0.9);
    this.effects.burst(new THREE.Vector3(this.playerPos.x, 1.2, this.playerPos.z), '#ffbd5e', 40, { speed: 8, size: 0.7, flash: 6 });
    this.audio.levelup?.();
    if (kind === 'Emberheart') {
      setTimeout(() => { if (this.active && this.enemyHp > 0) this.hitEnemy(28, true, null); }, 300);
    }
  }

  finishVictory() {
    if (this.resultSent) return;
    this.resultSent = true;
    this.phase = 'won';
    this.enemy.group.rotation.z = -0.9;
    this.enemy.group.position.y = 0.2;
    this.effects.ring(new THREE.Vector3(this.enemyPos.x, 0.06, this.enemyPos.z), '#e9c988', 5, 1);
    this.effects.burst(new THREE.Vector3(this.enemyPos.x, 1.3, this.enemyPos.z), this.def.accent, 50, { speed: 8, size: 0.7, flash: 7 });
    this.audio.victory?.();
    this.cb.onLog?.(`<b>${this.def.name}</b> yields. The circle is yours.`, 'good');
    this.cb.onHud?.({ enemyHp: 0 });
    setTimeout(() => {
      if (this.active) this.cb.onEnd?.({ won: true, enemy: this.def, rounds: this.round, hpLeft: this.hp });
    }, 1500);
  }

  finishDefeat() {
    if (this.resultSent) return;
    this.resultSent = true;
    this.cb.onEnd?.({ won: false, enemy: this.def, hpLeft: 0 });
  }

  dodge() {
    if (!this.active || this.phase !== 'fight' || this.dodgeCd > 0) return;
    this.dodgeCd = 1.15;
    this.dodgeTime = 0.32;
    this.invuln = 0.42;
    this.audio.noise?.({ dur: 0.2, vol: 0.08, freq: 700, slide: 700 });
    this.effects.castSpark(new THREE.Vector3(this.playerPos.x, 0.5, this.playerPos.z), '#c9d8ff');
    this.cb.onLog?.('You dodge.', 'good');
  }

  enemyCastSpell() {
    if (!this.def.spells?.length) return;
    const spellId = this.def.spells[Math.floor(Math.random() * this.def.spells.length)];
    const spell = SPELLS.find(s => s.id === spellId) || SPELLS[0];
    const tip = this.enemy.getTipWorld();
    const target = new THREE.Vector3(this.playerPos.x, 1.0, this.playerPos.z);
    const dmg = (this.def.dmg || 10) * (spell.dmg ? clamp(spell.dmg / 26, 0.7, 1.6) : 1) * (this.bossPhase > 1 ? 1.15 : 1);
    this.enemy.cast();
    this.effects.castSpark(tip, spell.color);
    this.audio.cast?.(spell.cat);
    this.cb.onLog?.(`<b>${this.def.name}</b> casts ${spell.name}.`, 'dmg');
    const shots = this.def.behavior === 'boss' ? (this.bossPhase > 1 ? 2 : 1) : 1;
    for (let i = 0; i < shots; i++) {
      setTimeout(() => {
        if (!this.active || this.phase !== 'fight') return;
        const from = this.enemy.getTipWorld();
        this.spawnEnemyProjectile(from, new THREE.Vector3(this.playerPos.x + rnd(-1.2, 1.2), 1.0, this.playerPos.z + rnd(-1.2, 1.2)), spell, dmg);
      }, i * 180);
    }
    if (this.def.behavior === 'brute') {
      const targetPos = this.playerPos.clone();
      this.effects.ring(new THREE.Vector3(targetPos.x, 0.06, targetPos.z), '#96c46b', 4, 0.6);
      if (dist(this.playerPos, this.enemyPos) < 6) setTimeout(() => this.takeDamage(dmg * 1.3, this.enemyPos), 700);
    }
  }

  update(dt, input = {}) {
    if (!this.active) return;
    const t = performance.now() / 1000;
    this.arena.update(dt, t);
    this.effects.update(dt);

    // timers
    for (const k of Object.keys(this.cds)) this.cds[k] = Math.max(0, this.cds[k] - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    if (this.comboTimer === 0 && this.combo) { this.combo = 0; this.cb.onHud?.({ combo: 0 }); }
    this.dodgeCd = Math.max(0, this.dodgeCd - dt);
    this.dodgeTime = Math.max(0, this.dodgeTime - dt);
    this.wardTime = Math.max(0, this.wardTime - dt);
    this.aegisTime = Math.max(0, this.aegisTime - dt);
    if (this.hotTime > 0) {
      this.hotTime -= dt;
      this.healPlayer(this.hotRate * dt, true);
      this.cb.onHud?.({ hp: this.hp });
    }

    // shield drain
    const shieldActive = input.shield && this.mp > 0;
    this.shieldHeld = shieldActive;
    if (shieldActive) {
      this.mp = Math.max(0, this.mp - 9 * dt);
      this.cb.onHud?.({ mp: this.mp });
    }
    this.updateShieldVisual(shieldActive);

    if (this.phase === 'intro') {
      this.introTime -= dt;
      this.player.update(dt, false);
      this.enemy.update(dt, false);
      if (this.introTime <= 0.7 && !this._saidFight) { this._saidFight = true; this.cb.onLog?.('Wands up.', 'spell'); }
      if (this.introTime <= 0) {
        this.phase = 'fight';
        this.cb.onLog?.('The duel begins.', 'spell');
        this.cb.onIntroEnd?.();
      }
      this.cb.onHud?.({ hp: this.hp, mp: this.mp, enemyHp: this.enemyHp, combo: this.combo });
      return;
    }
    if (this.phase !== 'fight') {
      this.player.update(dt, false);
      this.enemy.update(dt, false);
      return;
    }

    // player movement
    const speed = this.dodgeTime > 0 ? 11.5 : 5.6;
    let vx = input.moveX || 0, vz = input.moveZ || 0;
    const mag = Math.hypot(vx, vz);
    if (mag > 0.001) { vx = vx / mag; vz = vz / mag; }
    this.playerPos.x += vx * speed * dt;
    this.playerPos.z += vz * speed * dt;
    this.arena.clamp(this.playerPos);
    this.playerPos.y = 0;
    const toEnemy = new THREE.Vector3(this.enemyPos.x - this.playerPos.x, 0, this.enemyPos.z - this.playerPos.z);
    if (mag > 0.001) this.player.group.rotation.y = Math.atan2(vx, vz);
    else this.player.group.rotation.y = Math.atan2(toEnemy.x, toEnemy.z);
    this.player.update(dt, mag > 0.01, this.dodgeTime > 0 ? 1.7 : 1);
    if (this.dodgeTime > 0) this.effects.castSpark(new THREE.Vector3(this.playerPos.x, 0.35, this.playerPos.z), '#8ea8ff');

    // enemy AI
    this.updateEnemy(dt, toEnemy);

    // projectiles
    this.updateProjectiles(dt);
    // summons
    for (const s of this.summons) {
      s.time -= dt;
      s.tick -= dt;
      if (s.tick <= 0) {
        s.tick = 0.85;
        s.visual?.update?.(0);
        if (this.enemyHp > 0) {
          this.hitEnemy(s.dmg, false, null);
          this.effects.burst(new THREE.Vector3(this.enemyPos.x, 0.9, this.enemyPos.z), s.color, 7, { speed: 2.5, size: 0.3, ttl: 0.4 });
        }
      }
    }
    this.summons = this.summons.filter(s => s.time > 0);

    // statuses
    this.enemyStatus.stun = Math.max(0, this.enemyStatus.stun - dt);
    this.enemyStatus.slow = Math.max(0, this.enemyStatus.slow - dt);
    this.enemyStatus.silence = Math.max(0, this.enemyStatus.silence - dt);
    this.enemyStatus.fear = Math.max(0, this.enemyStatus.fear - dt);
    for (const dot of this.enemyDots) {
      dot.time -= dt;
      if (dot.tick === undefined) dot.tick = 0;
      dot.tick -= dt;
      if (dot.tick <= 0) {
        dot.tick = 0.5;
        this.enemyHp = Math.max(0, this.enemyHp - dot.dps * 0.5);
        this.cb.onHud?.({ enemyHp: this.enemyHp });
        this.effects.burst(new THREE.Vector3(this.enemyPos.x + rnd(-0.3, 0.3), 1.2, this.enemyPos.z + rnd(-0.3, 0.3)), dot.type === 'burn' ? '#ff9a3d' : dot.type === 'poison' ? '#6effa0' : '#ff6f9f', 3, { speed: 1.5, size: 0.25, ttl: 0.4 });
        if (this.enemyHp <= 0) this.finishVictory();
      }
    }
    this.enemyDots = this.enemyDots.filter(d => d.time > 0);

    // boss phases
    if (this.def.behavior === 'boss' && this.bossPhase === 1 && this.enemyHp < this.enemyMaxHp * 0.55) {
      this.bossPhase = 2;
      this.cb.onLog?.('The air turns to smoke. <b>Something older</b> looks out from behind his eyes.', 'dmg');
      this.cb.onToast?.('Phase two', 'The Hollow stops pretending.', '#d65cff', '☾');
      this.effects.shake(0.9);
      this.effects.ring(new THREE.Vector3(this.enemyPos.x, 0.06, this.enemyPos.z), '#d65cff', 12, 1.2);
    }

    this.cb.onHud?.({ hp: this.hp, mp: this.mp, enemyHp: this.enemyHp, casting: !!this.enemyCast, castColor: this.enemyCast?.color, combo: this.combo });
  }

  updateShieldVisual(on) {
    if (on && !this.shieldVisual) {
      const w = this.effects.ward(this.player.group, '#8fd0ff', 1.05);
      this.shieldVisual = w;
      this.audio.shield?.();
    } else if (!on && this.shieldVisual) {
      this.shieldVisual.remove();
      this.shieldVisual = null;
    }
    if (this.shieldVisual) this.shieldVisual.mat.uniforms.opacity.value = 0.55 + Math.sin(performance.now() / 120) * 0.12;
  }

  updateEnemy(dt, toEnemy) {
    const e = this.def;
    const distToPlayer = toEnemy.length();
    const behavior = e.behavior;
    const statusSlow = this.enemyStatus.slow > 0 ? 0.45 : 1;
    const stunned = this.enemyStatus.stun > 0 || this.enemyStatus.fear > 0;
    const silenced = this.enemyStatus.silence > 0;
    const eSpeed = (e.speed || 2.5) * statusSlow;

    let desired = 7;
    if (behavior === 'brute') desired = 2.5;
    if (behavior === 'caster') desired = 12;
    if (behavior === 'guardian') desired = 8;
    if (behavior === 'boss') desired = 9;
    if (behavior === 'dummy') desired = 99;

    let mx = 0, mz = 0;
    if (!stunned && behavior !== 'dummy') {
      const nx = toEnemy.x / (distToPlayer || 1), nz = toEnemy.z / (distToPlayer || 1);
      if (distToPlayer > desired + 1) { mx = nx; mz = nz; }
      else if (distToPlayer < desired - 1) { mx = -nx; mz = -nz; }
      // strafe
      const strafe = Math.sin(performance.now() / 1300 + (e.id.charCodeAt(0) || 0)) * (behavior === 'duelist' || behavior === 'master' ? 1 : 0.35);
      mx += -nz * strafe; mz += nx * strafe;
      const ml = Math.hypot(mx, mz) || 1;
      this.enemyPos.x += (mx / ml) * eSpeed * dt;
      this.enemyPos.z += (mz / ml) * eSpeed * dt;
      this.arena.clamp(this.enemyPos);
      // don't overlap player
      if (dist(this.enemyPos, this.playerPos) < 1.8) {
        const a = Math.atan2(this.enemyPos.z - this.playerPos.z, this.enemyPos.x - this.playerPos.x);
        this.enemyPos.x = this.playerPos.x + Math.cos(a) * 1.8;
        this.enemyPos.z = this.playerPos.z + Math.sin(a) * 1.8;
      }
    }
    // face player
    const ang = Math.atan2(this.playerPos.x - this.enemyPos.x, this.playerPos.z - this.enemyPos.z);
    this.enemy.group.rotation.y = ang + (this.enemyStatus.fear > 0 ? Math.sin(performance.now() / 90) * 0.3 : 0);
    this.enemy.update(dt, Math.hypot(mx, mz) > 0.1, behavior === 'master' ? 1.3 : 1);

    // casting
    if (this.enemyCast) {
      this.enemyCast.time -= dt;
      if (this.enemyCast.time <= 0) {
        this.enemyCast = null;
        if (!silenced && this.enemyHp > 0) this.enemyCastSpell();
      }
      return;
    }
    if (stunned || silenced || behavior === 'dummy' || behavior === 'brute') {
      if (behavior === 'brute' && !stunned && distToPlayer < 3.2 && Math.random() < dt * 1.2) {
        this.enemy.cast();
        this.effects.ring(new THREE.Vector3(this.playerPos.x, 0.06, this.playerPos.z), '#96c46b', 3.4, 0.5);
        this.takeDamage((e.dmg || 12) * 1.2, this.enemyPos);
        this.cb.onLog?.(`<b>${e.name}</b> slams the ground.`, 'dmg');
      }
      return;
    }
    this.enemyCastCd -= dt * (this.bossPhase > 1 ? 1.45 : 1);
    if (this.enemyCastCd <= 0 && distToPlayer < 26) {
      const spellId = e.spells[Math.floor(Math.random() * e.spells.length)];
      const spell = SPELLS.find(s => s.id === spellId);
      this.enemyCast = { time: behavior === 'boss' ? 0.62 : behavior === 'master' ? 0.7 : 0.9, color: spell?.color };
      this.enemyCastCd = rnd(1.6, 2.9) + (behavior === 'master' ? -0.4 : 0) + (this.bossPhase > 1 ? -0.5 : 0);
      this.cb.onHud?.({ casting: true, castColor: spell?.color });
      this.cb.onLog?.(`<b>${e.name}</b> raises a wand…`, 'dmg');
    }
  }

  updateProjectiles(dt) {
    const enemyCenter = new THREE.Vector3(this.enemyPos.x, 1.1, this.enemyPos.z);
    const playerCenter = new THREE.Vector3(this.playerPos.x, 1.0, this.playerPos.z);
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.orb.group.position.addScaledVector(p.vel, dt);
      const d = p.orb.group.position.distanceTo(enemyCenter);
      if (d < 1.15 || p.life <= 0) {
        if (d < 1.6) {
          this.effects.burst(p.orb.group.position.clone(), p.spell.color, p.opts.radius ? 26 : 14, { speed: p.opts.radius ? 6 : 3.4, size: p.opts.radius ? 0.55 : 0.4 });
          if (p.opts.radius) {
            this.effects.ring(new THREE.Vector3(this.enemyPos.x, 0.06, this.enemyPos.z), p.spell.color, p.opts.radius, 0.6);
            this.effects.shake(0.3);
          }
          this.hitEnemy(p.dmg, p.crit, p.spell, { status: p.opts.status, statusTime: p.opts.statusTime });
          if (p.opts.knock) {
            const a = Math.atan2(this.enemyPos.z - this.playerPos.z, this.enemyPos.x - this.playerPos.x);
            this.enemyPos.x += Math.cos(a) * 0.6; this.enemyPos.z += Math.sin(a) * 0.6;
          }
        }
        this.destroyProjectile(p);
        this.projectiles.splice(i, 1);
      }
    }
    for (let i = this.enemyProjectiles.length - 1; i >= 0; i--) {
      const p = this.enemyProjectiles[i];
      p.life -= dt;
      p.orb.group.position.addScaledVector(p.vel, dt);
      const d = p.orb.group.position.distanceTo(playerCenter);
      if (d < 1.0 || p.life <= 0) {
        if (d < 1.5) {
          // shield reflect
          if (this.shieldHeld && this.mp > 0) {
            this.effects.burst(p.orb.group.position.clone(), '#8fd0ff', 14, { speed: 4, size: 0.4 });
            this.audio.shield?.();
            const tip = this.player.getTipWorld();
            this.spawnPlayerProjectile(tip, new THREE.Vector3(this.enemyPos.x, 1.1, this.enemyPos.z), { color: '#8fd0ff', effect: 'projectile' }, p.dmg * 0.5, false, {});
            this.mp = Math.max(0, this.mp - 4);
          } else {
            this.takeDamage(p.dmg, p.orb.group.position.clone());
            this.effects.burst(p.orb.group.position.clone(), p.color, 14, { speed: 3.5, size: 0.4 });
          }
        }
        this.destroyProjectile(p);
        this.enemyProjectiles.splice(i, 1);
      }
    }
  }

  get state() {
    return { hp: this.hp, mp: this.mp, maxHp: this.maxHp, maxMp: this.maxMp, enemyHp: this.enemyHp, cds: this.cds };
  }
}

