  for (let i = 0; i < 500; i++) {
    const a = rng() * Math.PI * 2, h = Math.acos(1 - rng() * 1.2);
    sp[i * 3] = Math.sin(h) * Math.cos(a) * 190;
    sp[i * 3 + 1] = Math.cos(h) * 190 + 20;
