  const accepted = price >= customer.budget[0] * 0.55 && score >= 44;
  return {
    score, price, accepted, tagMatch, primary,
    mood: score >= 85 ? 'delighted' : score >= 65 ? 'pleased' : score >= 44 ? 'considering' : 'unimpressed'
