  --teal: #7de6d0;
  --rose: #ff8c9a;
  --ember: #ffb05a;
  --green: #96e08a;
  --line: rgba(233, 201, 136, .22);
  --line-soft: rgba(233, 201, 136, .11);
  --shadow: 0 30px 90px rgba(0, 0, 0, .65);
  --serif: 'Cormorant Garamond', 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
  --display: 'Cinzel', 'Iowan Old Style', Palatino, Georgia, serif;
  --body: 'Spectral', 'Iowan Old Style', Palatino, Georgia, serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--ink);
  color: var(--parch);
  font-family: var(--body);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
button { font-family: inherit; color: inherit; border: none; background: none; cursor: pointer; }
input { font-family: inherit; }
.hidden { display: none !important; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,.03); }
::-webkit-scrollbar-thumb { background: linear-gradient(var(--gold-dim), #5c4728); border-radius: 8px; }

#app { position: fixed; inset: 0; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.scene-grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 30%, rgba(8,5,16,.22) 70%, rgba(8,5,16,.58) 100%),
    linear-gradient(to bottom, rgba(12,8,26,.18), transparent 22%, transparent 74%, rgba(7,5,14,.52));
}
.scene-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  box-shadow: inset 0 0 180px 20px rgba(5, 3, 12, .78);
}

/* ── LOADING ─────────────────────────────────────────────── */
#loading {
  position: absolute; inset: 0; z-index: 90; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 8px;
  background: radial-gradient(ellipse at center, #19112c 0%, #08060f 70%);
  transition: opacity .8s ease;
}
#loading.done { opacity: 0; pointer-events: none; }
.load-sigil { position: relative; width: 104px; height: 104px; display: grid; place-items: center; margin-bottom: 20px; }
.load-ring { position: absolute; inset: 0; border: 1px solid rgba(233,201,136,.5); border-radius: 50%; border-top-color: transparent; animation: spin 3s linear infinite; }
.load-ring.r2 { inset: 15px; border-color: rgba(171,140,255,.45); border-bottom-color: transparent; animation: spin 2s linear infinite reverse; }
.load-core { font-size: 28px; color: var(--gold); text-shadow: 0 0 26px var(--gold); animation: pulse 2.2s ease-in-out infinite; }
.load-title { font-family: var(--display); letter-spacing: .5em; font-size: 24px; color: var(--parch); padding-left: .5em; }
.load-sub { font-family: var(--display); font-size: 9px; letter-spacing: .32em; color: var(--gold-dim); text-transform: uppercase; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { 50% { opacity: .45; transform: scale(.88); text-shadow: 0 0 6px var(--gold); } }

/* ── TITLE ───────────────────────────────────────────────── */
#title-screen {
  position: absolute; inset: 0; z-index: 30; display: flex; align-items: center;
