  font-family: var(--display); font-size: 10px; font-weight: 700; letter-spacing: .42em; color: var(--gold);
}
.title-eyebrow span { width: 34px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold-2)); }
.title-eyebrow span:last-child { background: linear-gradient(90deg, var(--gold-2), transparent); }
.game-title {
  font-family: var(--display); font-weight: 900; margin: 0; line-height: .84;
  font-size: clamp(70px, 10.4vw, 152px); letter-spacing: .03em; color: var(--parch);
  text-shadow: 0 4px 40px rgba(0,0,0,.6), 0 0 70px rgba(206,170,255,.16);
}
.game-title em {
  display: block; font-style: normal; font-size: .48em; letter-spacing: .22em;
  color: var(--gold); padding-left: .16em; margin-bottom: .08em;
  background: linear-gradient(100deg, #f5dfae, #bd8f45 38%, #fff0c8 52%, #b8893f 68%, #edd196);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 24px rgba(233,201,136,.18));
}
.game-title strong { font-weight: 900; letter-spacing: .06em; }
.title-rule { display: flex; align-items: center; gap: 14px; margin: 22px 0 18px; width: 74%; }
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, var(--line)); }
.title-rule i:last-child { background: linear-gradient(90deg, var(--line), transparent); }
